(6,'6-1-soz-3',3,'{"id": "6-1-soz-3", "title": "Söz varlığı · 3", "theme": "Dilimizin Zenginliği", "kind": "words", "body": [{"kelime": "kalıp söz", "anlam": "Belirli durumlarda alışılmış biçimiyle kullanılan ifade", "ornek": "Geçmiş olsun bir kalıp sözdür.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "mani", "anlam": "Genellikle dört dizeden oluşan halk şiiri türü", "ornek": "Şenlikte yeni yazdığımız maniyi okuduk.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "ninni", "anlam": "Küçük çocukları uyutmak için ezgiyle söylenen söz", "ornek": "Ninninin yumuşak ritmini dinledim.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "tekerleme", "anlam": "Ses benzerlikleriyle kurulan ritimli söz dizisi", "ornek": "Tekerlemeyi yavaş söyleyerek başladık.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "bilmece", "anlam": "Bir varlığı özellikleriyle dolaylı anlatan sözlü soru", "ornek": "Bilmecenin cevabını ipuçlarından buldum.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "söyleyiş", "anlam": "Bir sözün söylenme biçimi", "ornek": "Söyleyiş farklı olsa da anlam aynıydı.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "etkileşim", "anlam": "Birbirini karşılıklı olarak etkileme", "ornek": "Diller arasında etkileşim olabilir.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "birikim", "anlam": "Zaman içinde toplanan bilgi ve deneyim", "ornek": "Okuma birikimim yazılarıma yansıdı.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "özen", "anlam": "Bir işi dikkatle ve titizlikle yapma", "ornek": "Kelimeleri seçerken özen gösterdim.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "incelik", "anlam": "Anlatımda veya davranışta gözetilen hassas ayrıntı", "ornek": "Bir teşekkürün inceliğini fark ettik.", "tip": "kelime", "cikti": "T.O.6.21"}], "questions": [{"id": "6-1-kelime-20", "prompt": "“kalıp söz” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Belirli durumlarda alışılmış biçimiyle kullanılan ifade", "Bir dilde kullanılan kelime ve kalıp sözlerin bütünü", "Bir dilin yörelere göre değişen söyleyiş biçimi", "Genellikle gerçek anlamından farklı bir anlam taşıyan kalıplaşmış söz"], "answer": "Belirli durumlarda alışılmış biçimiyle kullanılan ifade", "explanation": "Geçmiş olsun bir kalıp sözdür."}, {"id": "6-1-kelime-21", "prompt": "“mani” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Genellikle dört dizeden oluşan halk şiiri türü", "Bir dilin yörelere göre değişen söyleyiş biçimi", "Genellikle gerçek anlamından farklı bir anlam taşıyan kalıplaşmış söz", "Deneyimlerden doğan genel bir öğüdü bildiren kalıplaşmış söz"], "answer": "Genellikle dört dizeden oluşan halk şiiri türü", "explanation": "Şenlikte yeni yazdığımız maniyi okuduk."}, {"id": "6-1-kelime-22", "prompt": "“ninni” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Küçük çocukları uyutmak için ezgiyle söylenen söz", "Genellikle gerçek anlamından farklı bir anlam taşıyan kalıplaşmış söz", "Deneyimlerden doğan genel bir öğüdü bildiren kalıplaşmış söz", "Bir düşüncenin başka bir düşünceyi hatırlatması"], "answer": "Küçük çocukları uyutmak için ezgiyle söylenen söz", "explanation": "Ninninin yumuşak ritmini dinledim."}, {"id": "6-1-kelime-23", "prompt": "“tekerleme” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Ses benzerlikleriyle kurulan ritimli söz dizisi", "Deneyimlerden doğan genel bir öğüdü bildiren kalıplaşmış söz", "Bir düşüncenin başka bir düşünceyi hatırlatması", "Bir sözün anlamını belirleyen çevresindeki anlatım"], "answer": "Ses benzerlikleriyle kurulan ritimli söz dizisi", "explanation": "Tekerlemeyi yavaş söyleyerek başladık."}, {"id": "6-1-kelime-24", "prompt": "“bilmece” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir varlığı özellikleriyle dolaylı anlatan sözlü soru", "Bir düşüncenin başka bir düşünceyi hatırlatması", "Bir sözün anlamını belirleyen çevresindeki anlatım", "Birbirine yakın şeyler arasındaki ince ayrım"], "answer": "Bir varlığı özellikleriyle dolaylı anlatan sözlü soru", "explanation": "Bilmecenin cevabını ipuçlarından buldum."}, {"id": "6-1-kelime-25", "prompt": "“söyleyiş” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir sözün söylenme biçimi", "Bir sözün anlamını belirleyen çevresindeki anlatım", "Birbirine yakın şeyler arasındaki ince ayrım", "Söyleyişin veya anlatımın kesintisiz ilerlemesi"], "answer": "Bir sözün söylenme biçimi", "explanation": "Söyleyiş farklı olsa da anlam aynıydı."}, {"id": "6-1-kelime-26", "prompt": "“etkileşim” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Birbirini karşılıklı olarak etkileme", "Birbirine yakın şeyler arasındaki ince ayrım", "Söyleyişin veya anlatımın kesintisiz ilerlemesi", "Söyleyişte bir sesi veya kelimeyi belirginleştirme"], "answer": "Birbirini karşılıklı olarak etkileme", "explanation": "Diller arasında etkileşim olabilir."}, {"id": "6-1-kelime-27", "prompt": "“birikim” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Zaman içinde toplanan bilgi ve deneyim", "Söyleyişin veya anlatımın kesintisiz ilerlemesi", "Söyleyişte bir sesi veya kelimeyi belirginleştirme", "Konuşurken sesin anlamla uyumlu biçimde yükselip alçalması"], "answer": "Zaman içinde toplanan bilgi ve deneyim", "explanation": "Okuma birikimim yazılarıma yansıdı."}, {"id": "6-1-kelime-28", "prompt": "“özen” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir işi dikkatle ve titizlikle yapma", "Söyleyişte bir sesi veya kelimeyi belirginleştirme", "Konuşurken sesin anlamla uyumlu biçimde yükselip alçalması", "Dağınık kaynaklardan bilgi veya ürün toplama işi"], "answer": "Bir işi dikkatle ve titizlikle yapma", "explanation": "Kelimeleri seçerken özen gösterdim."}, {"id": "6-1-kelime-29", "prompt": "“incelik” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Anlatımda veya davranışta gözetilen hassas ayrıntı", "Konuşurken sesin anlamla uyumlu biçimde yükselip alçalması", "Dağınık kaynaklardan bilgi veya ürün toplama işi", "Yakın yıllarda doğup benzer dönemleri yaşayan insanlar topluluğu"], "answer": "Anlatımda veya davranışta gözetilen hassas ayrıntı", "explanation": "Bir teşekkürün inceliğini fark ettik."}]}'::jsonb),
(6,'6-1-okuma-1',4,'{"id": "6-1-okuma-1", "title": "Kaybolmayan Kelimeler", "theme": "Dilimizin Zenginliği", "kind": "reading", "body": {"text": "Zeynep, okulun dil atölyesine giderken yanında boş bir defter taşıyordu. Öğretmeni, çevrelerinde duydukları ama günlük konuşmalarında az kullandıkları kelimeleri toplamalarını istemişti. Zeynep başta bunun kolay olduğunu düşündü. Evdeki eski bir kitabı açıp sayfalar dolusu kelime yazabilirdi. Fakat görev kâğıdında küçük bir ayrıntı vardı: Her kelimenin hangi durumda kullanıldığını da kaydedeceklerdi. Liste yapmak tek başına yeterli değildi.\nO akşam komşuları Selma Hanım, birlikte hazırladıkları afişe bakarken “Pek özenli olmuş.” dedi. Zeynep hemen defterini açtı. Kelimeyi biliyordu ama özen ile dikkat arasındaki farkı açıklayamıyordu. Selma Hanım, her iki kelimenin bazı durumlarda birbirine yaklaşabileceğini söyledi. Sonra afişteki düzgün harfleri, seçilmiş renkleri ve okunaklı başlığı gösterdi. Zeynep, özenin yaptığı işe değer vermeyi de düşündürdüğünü kendi cümlesiyle not etti.\nErtesi gün atölyede herkes bir kelime sundu. Arda, dedesinden duyduğu yöresel bir söyleyişi getirmişti. Bazı arkadaşları gülmeye başlayınca durdu. Öğretmen, farklı söyleyişleri bir yarışın kazananı ve kaybedeni gibi düşünmemelerini istedi. Önce kelimenin nerede duyulduğunu, sonra ne anlama geldiğini konuştular. Arda anlatmaya yeniden başladı. Böylece defterdeki kelimenin yanında bir insanın sesi de yer buldu.\nGrup, topladıkları kelimeleri hemen çevrim içi yayımlamak istedi. Zeynep ise kayıtların sahiplerinden izin almaları gerektiğini hatırlattı. Sesini paylaşmak istemeyenlerin örnekleri yazıyla aktarılabilirdi. Üstelik bir kişinin açıklaması, kelimenin bütün kullanımlarını göstermeyebilirdi. Sözlükten ve başka örneklerden de yararlanmaya karar verdiler. Kesinleşmeyen anlamları ayrı bir renkle işaretlediler.\nHafta sonunda defter çok kalınlaşmamıştı. Buna karşılık her sayfada bağlam, örnek cümle ve kontrol edilen bir anlam vardı. Zeynep başlangıçta hızlıca doldurabileceğini sandığı sayfalara baktı. Az yazmış olmaktan utanmadı. Bir kelimeyi gerçekten tanımanın, onu yalnızca kopyalamaktan farklı olduğunu anlamıştı. Defterin kapağına “Bitmiş Sözlük” yerine “Sorularımız ve Kelimelerimiz” yazdı. Çünkü çalışma, yeni bir kullanım duyduklarında sürdürülebilirdi. Atölyeden çıkarken arkadaşları da kendi defterlerinin sonuna boş sayfalar ekledi. Bir sonraki buluşmaya kadar dinleyecekleri çok ses vardı. Zeynep artık bir kelimeyi bilmediğinde hemen geçmek yerine kısa bir soru sormayı düşünüyordu. Defteri, cevaplar kadar bu soruları da saklayacaktı.", "type": "oykuleyici"}, "questions": [{"id": "6-1-okuma-1-1", "prompt": "“Kaybolmayan Kelimeler” metnine göre: Görevde kelime listesine ek olarak ne istenmiştir?", "choices": ["Kelimeleri yalnız alfabetik sıraya koymak", "Bütün kelimeleri ezberlemek", "Kelimelerin kullanıldığı durumları kaydetmek"], "answer": "Kelimelerin kullanıldığı durumları kaydetmek", "explanation": "Görev kâğıdı, kelimelerin hangi durumda kullanıldığının kaydedilmesini ister."}, {"id": "6-1-okuma-1-2", "prompt": "“Kaybolmayan Kelimeler” metnine göre: Zeynep ilk kelimeyi kimden duymuştur?", "choices": ["Okul müdüründen", "Selma Hanım''dan", "Arda''nın dedesinden"], "answer": "Selma Hanım''dan", "explanation": "Özenli sözü, afişe bakan Selma Hanım''ın konuşmasında geçer."}, {"id": "6-1-okuma-1-3", "prompt": "“Kaybolmayan Kelimeler” metnine göre: Özen kelimesinin anlamını açıklarken hangi nesne kullanılmıştır?", "choices": ["Hazırlanan afiş", "Eski bir harita", "Bir ses cihazı"], "answer": "Hazırlanan afiş", "explanation": "Selma Hanım afişin harflerini, renklerini ve başlığını gösterir."}, {"id": "6-1-okuma-1-4", "prompt": "“Kaybolmayan Kelimeler” metnine göre: Kesinleşmeyen anlamlar nasıl gösterilmiştir?", "choices": ["Üzerleri tamamen silinerek", "Defterden koparılarak", "Ayrı bir renkle"], "answer": "Ayrı bir renkle", "explanation": "Grup, henüz doğrulanmayan anlamları ayrı renkle işaretler."}, {"id": "6-1-okuma-1-5", "prompt": "“Kaybolmayan Kelimeler” metnine göre: Bağlam kelimesi bu çalışmada hangi bilgiyi kapsar?", "choices": ["Afişin hangi duvara asıldığını", "Sözün hangi durumda kullanıldığını", "Defterin kaç liraya alındığını"], "answer": "Sözün hangi durumda kullanıldığını", "explanation": "Bağlam, kelimenin anlamını belirleyen kullanım çevresidir."}, {"id": "6-1-okuma-1-6", "prompt": "“Kaybolmayan Kelimeler” metnine göre: Çalışmayı en iyi temsil eden anahtar kelime grubu hangisidir?", "choices": ["Kelime, bağlam, anlam", "Ulaşım, bilet, yolculuk", "Yarış, derece, kupa"], "answer": "Kelime, bağlam, anlam", "explanation": "Metnin odağında kelimeleri bağlam ve anlamlarıyla toplamak bulunur."}, {"id": "6-1-okuma-1-7", "prompt": "“Kaybolmayan Kelimeler” metnine göre: Defterin sonuna neden boş sayfalar eklenmiştir?", "choices": ["Afişin ölçüsünü büyütmek için", "Öğretmenin imzasını çoğaltmak için", "Yeni kullanımları kaydetmeye devam edebilmek için"], "answer": "Yeni kullanımları kaydetmeye devam edebilmek için", "explanation": "Son bölümde yeni bir kullanım duyuldukça çalışmanın sürebileceği belirtilir."}, {"id": "6-1-okuma-1-8", "prompt": "“Kaybolmayan Kelimeler” metnine göre: Kayıt paylaşmak istemeyenlerin örnekleri nasıl aktarılabilir?", "choices": ["Adları değiştirilerek her durumda sesli", "Yazıyla", "İzinsiz ses kaydıyla"], "answer": "Yazıyla", "explanation": "Zeynep, ses paylaşımı istemeyenlerin örneklerinin yazılı aktarılabileceğini belirtir."}]}'::jsonb),
(6,'6-1-okuma-2',5,'{"id": "6-1-okuma-2", "title": "Bir Kelimenin Yolculuğunu İzlemek", "theme": "Dilimizin Zenginliği", "kind": "reading", "body": {"text": "Bir kelimenin anlamını öğrenmek için sözlüğe bakmak iyi bir başlangıçtır. Fakat sözlükteki ilk açıklamayı her cümleye yerleştirmek doğru sonuç vermeyebilir. Çünkü kelimeler, birlikte kullanıldıkları başka kelimelerle ve anlatılan durumla ilişki kurar. “İnce bir ip” sözünde ölçü bildiren ince, “ince bir düşünce” sözünde aynı görevi yapmaz. İkinci örnekte kişinin başkasını gözeten davranışı öne çıkar. Bu ayrımı anlamak için kelimenin çevresindeki anlatımı da okumak gerekir.\nDil atölyesinde hazırlanacak küçük bir kelime dosyası, bu ilişkileri görmeyi kolaylaştırabilir. Dosyanın ilk bölümüne kelime ve duyulduğu cümle yazılır. İkinci bölümde kelimenin anlamıyla ilgili bir tahmin yapılır. Üçüncü bölümde ise bu tahmin uygun bir sözlük veya güvenilir başka bir kaynakla kontrol edilir. Tahmin yanlış çıkarsa ilk not silinmek zorunda değildir. Yanına düzeltme eklemek, düşüncenin nasıl değiştiğini gösterir.\nKaynak seçerken yalnızca sayfanın renkli görünmesine veya arama sonuçlarında üst sırada çıkmasına güvenilmez. Kelimeyi açıklayan kurumun kim olduğu, örneklerin bulunup bulunmadığı ve bilginin ne zaman kontrol edildiği incelenebilir. Birbirinden kopyalanmış beş sayfa, birbirinden bağımsız beş kanıt sayılmaz. Kaynağı belli olmayan bir açıklama, araştırmanın sonu yerine yeni bir kontrolün başlangıcı olabilir.\nKelimelerin anlam ilişkileri de dosyaya eklenebilir. Yakın anlamlı iki söz her yerde birbirinin yerine geçmeyebilir. Örneğin bir cümlede birbirine yaklaşan ifadeler, başka bir cümlede farklı bir duygu oluşturabilir. Bu nedenle kelime kartlarına yalnızca eşleştirmeler değil, özgün örnekler de yazmak yararlıdır. Örneği okuyan bir arkadaş, ne kastedildiğini açıklayabiliyorsa anlatımın açıklığı konusunda ipucu elde edilir.\nBöyle bir çalışma, mümkün olduğunca çok kelimeyi bir günde biriktirme yarışı değildir. Önemli olan seçilen kelimeleri anlamları, bağlamları ve kullanım incelikleriyle tanımaktır. Dosya zaman zaman yeniden açılır; yeni bir örnek bulunduğunda eski açıklama geliştirilir. Bir kelimenin yolculuğunu izlemek, dilin yaşayan ve değişen yönünü fark etmeyi sağlar. Öğrenci böylece hem okurken daha dikkatli sorular sorabilir hem de yazarken anlatmak istediği düşünceye uygun sözleri seçebilir. Son sayfaya konacak küçük bir kontrol listesi bu alışkanlığı destekler. Listede “Cümleyi kaydettim mi?”, “Tahminimi sınadım mı?” ve “Kendi örneğimi yazdım mı?” soruları bulunabilir. Her kutunun doldurulması çalışmanın sonsuza kadar tamamlandığını değil, o günkü incelemenin hangi adımlarının yapıldığını gösterir.", "type": "bilgilendirici"}, "questions": [{"id": "6-1-okuma-2-1", "prompt": "“Bir Kelimenin Yolculuğunu İzlemek” metnine göre: Metinde ince kelimesi niçin iki cümlede kullanılmıştır?", "choices": ["Bir yazım yanlışını göstermek için", "Bağlama göre anlamın değişebildiğini göstermek için", "İki ipin kalınlığını karşılaştırmak için"], "answer": "Bağlama göre anlamın değişebildiğini göstermek için", "explanation": "İp ve düşünce örneklerinde aynı kelimenin farklı anlamları gösterilir."}, {"id": "6-1-okuma-2-2", "prompt": "“Bir Kelimenin Yolculuğunu İzlemek” metnine göre: Kelime dosyasının ilk bölümüne ne yazılır?", "choices": ["Kelime ve duyulduğu cümle", "Yalnızca sözlüğün fiyatı", "Dosyanın toplam sayfa sayısı"], "answer": "Kelime ve duyulduğu cümle", "explanation": "Dosya düzeninde ilk adım kelimeyle kullanım cümlesini kaydetmektir."}, {"id": "6-1-okuma-2-3", "prompt": "“Bir Kelimenin Yolculuğunu İzlemek” metnine göre: Yanlış çıkan tahmin için hangi işlem önerilir?", "choices": ["Bütün dosyayı atmak", "Tahmini doğru kabul etmek", "Yanına düzeltme eklemek"], "answer": "Yanına düzeltme eklemek", "explanation": "İlk notun yanına düzeltme eklenmesi düşüncedeki değişimi görünür kılar."}, {"id": "6-1-okuma-2-4", "prompt": "“Bir Kelimenin Yolculuğunu İzlemek” metnine göre: Metne göre kaynak seçerken hangisi tek başına yeterli değildir?", "choices": ["Örneklerin kontrol edilmesi", "Sayfanın renkli görünmesi", "Bilgiyi sunan kurumun incelenmesi"], "answer": "Sayfanın renkli görünmesi", "explanation": "Görsel çekicilik bilgi güvenilirliğini tek başına göstermez."}, {"id": "6-1-okuma-2-5", "prompt": "“Bir Kelimenin Yolculuğunu İzlemek” metnine göre: Birbirinden kopyalanmış sayfalar için ne söylenir?", "choices": ["Bağımsız kanıtlar sayılmazlar", "Her biri ayrı bir deneydir", "Her durumda sözlükten üstündürler"], "answer": "Bağımsız kanıtlar sayılmazlar", "explanation": "Aynı açıklamanın kopyaları bağımsız doğrulama sağlamaz."}, {"id": "6-1-okuma-2-6", "prompt": "“Bir Kelimenin Yolculuğunu İzlemek” metnine göre: Bağlam burada hangi anlama gelir?", "choices": ["Dosyanın dış kapağı", "Kaynağın baskı maliyeti", "Kelimenin yer aldığı anlatım çevresi"], "answer": "Kelimenin yer aldığı anlatım çevresi", "explanation": "İlk paragraf kelimeyi çevresindeki sözlerle birlikte ele alır."}, {"id": "6-1-okuma-2-7", "prompt": "“Bir Kelimenin Yolculuğunu İzlemek” metnine göre: Metnin anahtar kelimeleri hangileridir?", "choices": ["Bilet, durak, yolcu", "Kelime, bağlam, kaynak", "Yağış, bulut, rüzgâr"], "answer": "Kelime, bağlam, kaynak", "explanation": "Metin, kelimeyi bağlamıyla ve kaynak kontrolüyle inceleme üzerinde durur."}, {"id": "6-1-okuma-2-8", "prompt": "“Bir Kelimenin Yolculuğunu İzlemek” metnine göre: Kontrol listesinde hangisi bulunabilir?", "choices": ["Kendi örneğimi yazdım mı?", "En pahalı defteri aldım mı?", "Bütün kelimeleri bir günde bitirdim mi?"], "answer": "Kendi örneğimi yazdım mı?", "explanation": "Son paragraftaki liste özgün örnek yazma adımını içerir."}]}'::jsonb),
(6,'6-1-6-1-de-da',6,'{"id": "6-1-6-1-de-da", "title": "Bağlaç de ve bulunma eki", "theme": "Dilimizin Zenginliği", "kind": "lesson", "body": {"html": "<p>Bağlaç olan de, da kendinden önceki kelimeden ayrı yazılır ve d ile başlar. Bulunma durumunu bildiren -de eki kelimeye bitişir; ses uyumuna göre -da, -te, -ta biçimleri olabilir. Yalnızca cümleden çıkarma denemesiyle karar vermek yerine kullanımın işlevine bak. Ek yer veya durum bildirirken bağlaç çoğu zaman katılma anlamı katar. Özel adın bulunma eki kesmeyle ayrılır; özel addan sonraki bağlaç ise yine ayrı yazılır.</p><ul><li>Ben de bir kelime önerdim.</li><li>Sözlük masada duruyor.</li><li>Ankara’da bir atölyeye katıldık.</li></ul>", "examples": ["Ben de bir kelime önerdim.", "Sözlük masada duruyor.", "Ankara’da bir atölyeye katıldık."], "code": "T.Y.6.21"}, "questions": [{"id": "6-1-de-da-1", "prompt": "Katılma anlamı veren bağlaç hangi cümlede doğru yazılmıştır?", "choices": ["Defteri bende inceledim.", "Defteri ben te inceledim.", "Defteri ben de inceledim."], "answer": "Defteri ben de inceledim.", "explanation": "Burada de, benim de katıldığımı bildirir ve ayrı yazılır."}, {"id": "6-1-de-da-2", "prompt": "Yer bildiren ek hangi cümlede doğru yazılmıştır?", "choices": ["Kalem kutu ta duruyor.", "Kalem kutuda duruyor.", "Kalem kutu da duruyor."], "answer": "Kalem kutuda duruyor.", "explanation": "Kutuda kelimesindeki -da bulunma ekidir ve bitişik yazılır."}, {"id": "6-1-de-da-3", "prompt": "Kitap kelimesine bulunma eki hangi cümlede doğru getirilmiştir?", "choices": ["Örnek kitapta var.", "Örnek kitap da var.", "Örnek kitap ta var."], "answer": "Örnek kitapta var.", "explanation": "Kitapta kelimesi yer bildirir; ek sert ünsüzden sonra -ta olur."}, {"id": "6-1-de-da-4", "prompt": "Özel ada gelen bulunma eki hangi seçenekte doğrudur?", "choices": ["İzmir de bir derleme yapıldı.", "İzmirde bir derleme yapıldı.", "İzmir’de bir derleme yapıldı."], "answer": "İzmir’de bir derleme yapıldı.", "explanation": "Yer bildiren ek özel ada kesmeyle bağlanır."}, {"id": "6-1-de-da-5", "prompt": "Benzer bir katılımı anlatan doğru cümle hangisidir?", "choices": ["Arda’da öykü yazdı.", "Arda da öykü yazdı.", "Ardada öykü yazdı."], "answer": "Arda da öykü yazdı.", "explanation": "Da burada bulunma eki değil, katılma anlamlı bağlaçtır."}, {"id": "6-1-de-da-6", "prompt": "İki farklı işlevin birlikte doğru yazıldığı cümle hangisidir?", "choices": ["Rafta da bir sözlük var.", "Raf ta da bir sözlük var.", "Rafda da bir sözlük var."], "answer": "Rafta da bir sözlük var.", "explanation": "Rafta bulunma eki bitişiktir; ardından gelen da bağlacı ayrıdır."}, {"id": "6-1-de-da-7", "prompt": "Sokak kelimesinin yer bildiren biçimi hangisinde doğrudur?", "choices": ["Sokak da bir şenlik vardı.", "Sokak ta bir şenlik vardı.", "Sokakta bir şenlik vardı."], "answer": "Sokakta bir şenlik vardı.", "explanation": "Sokakta yer anlamı taşıyan -ta ekini bitişik alır."}, {"id": "6-1-de-da-8", "prompt": "Bağlacın sertleşmediğini gösteren doğru kullanım hangisidir?", "choices": ["Sözlükde masadaydı.", "Sözlük de masadaydı.", "Sözlük te masadaydı."], "answer": "Sözlük de masadaydı.", "explanation": "Bağlaç de ayrı yazılır ve önceki sert sese uyarak te olmaz."}, {"id": "6-1-de-da-9", "prompt": "Sınıf kelimesinin bulunma eki hangi seçenekte doğrudur?", "choices": ["Sınıfta sessizce okuduk.", "Sınıf da sessizce okuduk.", "Sınıf ta sessizce okuduk."], "answer": "Sınıfta sessizce okuduk.", "explanation": "Sınıfta yer bildirir; ek f ünsüzünden sonra -ta biçimindedir."}, {"id": "6-1-de-da-10", "prompt": "Katılma ve yer işlevleri hangi cümlede doğru gösterilmiştir?", "choices": ["Ece’de müze de çalıştı.", "Ecede müzede çalıştı.", "Ece de müzede çalıştı."], "answer": "Ece de müzede çalıştı.", "explanation": "Ece de katılma, müzede ise yer bildirir; yazımları farklıdır."}]}'::jsonb),
(6,'6-1-6-1-ki',7,'{"id": "6-1-6-1-ki", "title": "Bağlaç ki ve ek olan ki", "theme": "Dilimizin Zenginliği", "kind": "lesson", "body": {"html": "<p>Bağlaç olan ki, cümleler arasında ilişki kurar ve ayrı yazılır. Ek olan -ki ise aitlik veya yer-zaman ilişkisi kurarak kelimeye bitişir. Masadaki örneğinde bir şeyin nerede bulunduğu belirtilir; benimki örneğinde bir adın yerini tutar. Çünkü, belki, sanki gibi kalıplaşmış kelimelerin yazımı ayrıca öğrenilir. Bütün ki seslerini tek bir kuralla ayırmaya çalışma; cümlede yaptığı işi incele.</p><ul><li>Anladım ki sözün anlamı değişmiş.</li><li>Masadaki kartı aldım.</li><li>Benimki daha kısa bir metin.</li></ul>", "examples": ["Anladım ki sözün anlamı değişmiş.", "Masadaki kartı aldım.", "Benimki daha kısa bir metin."], "code": "T.Y.6.21"}, "questions": [{"id": "6-1-ki-1", "prompt": "Cümleleri bağlayan ki hangi seçenekte doğru yazılmıştır?", "choices": ["Duydumki sergi açılmış.", "Duydum-ki sergi açılmış.", "Duydum ki sergi açılmış."], "answer": "Duydum ki sergi açılmış.", "explanation": "Ki cümleler arasında bağ kurar ve ayrı yazılır."}, {"id": "6-1-ki-2", "prompt": "Yer ilişkisi kuran ek hangi cümlede doğrudur?", "choices": ["Raf taki defteri uzattı.", "Raftaki defteri uzattı.", "Rafta ki defteri uzattı."], "answer": "Raftaki defteri uzattı.", "explanation": "Raftaki kelimesindeki -ki ektir ve bitişik yazılır."}, {"id": "6-1-ki-3", "prompt": "Bir adın yerini tutan ek hangi seçenekte doğru yazılmıştır?", "choices": ["Seninki masanın üstünde.", "Senin ki masanın üstünde.", "Senin-ki masanın üstünde."], "answer": "Seninki masanın üstünde.", "explanation": "Seninki bir adın yerini tutar; -ki bitişik yazılır."}, {"id": "6-1-ki-4", "prompt": "Kalıcı kelime yazımı hangi seçenekte doğrudur?", "choices": ["Bel ki yarın görüşürüz.", "Bel-ki yarın görüşürüz.", "Belki yarın görüşürüz."], "answer": "Belki yarın görüşürüz.", "explanation": "Belki kalıplaşmış bir kelimedir; ayrı yazılmaz."}, {"id": "6-1-ki-5", "prompt": "Zaman ilişkisi kuran ek hangi cümlede doğru yazılmıştır?", "choices": ["Yarın-ki toplantıya hazırlanıyoruz.", "Yarınki toplantıya hazırlanıyoruz.", "Yarın ki toplantıya hazırlanıyoruz."], "answer": "Yarınki toplantıya hazırlanıyoruz.", "explanation": "Yarınki kelimesindeki -ki bitişik yazılan ektir."}, {"id": "6-1-ki-6", "prompt": "Bağlaç kullanımının doğru yazımı hangisidir?", "choices": ["Öyle dikkatli dinledi ki ayrıntıyı kaçırmadı.", "Öyle dikkatli dinlediki ayrıntıyı kaçırmadı.", "Öyle dikkatli dinledi-ki ayrıntıyı kaçırmadı."], "answer": "Öyle dikkatli dinledi ki ayrıntıyı kaçırmadı.", "explanation": "Ki iki yargı arasında ilişki kurduğu için ayrı yazılır."}, {"id": "6-1-ki-7", "prompt": "Bugün kelimesiyle kurulan doğru yazım hangisidir?", "choices": ["Bugün ki notları dosyaladık.", "Bugün-ki notları dosyaladık.", "Bugünkü notları dosyaladık."], "answer": "Bugünkü notları dosyaladık.", "explanation": "Bugünkü kelimesinde ek bitişir ve ü biçimini alır."}, {"id": "6-1-ki-8", "prompt": "Kalıplaşmış sebep bağlacının doğru yazımı hangisidir?", "choices": ["Gelmiyorum çün-ki işim var.", "Gelmiyorum çünkü işim var.", "Gelmiyorum çün ki işim var."], "answer": "Gelmiyorum çünkü işim var.", "explanation": "Çünkü bir bütün olarak yazılır."}, {"id": "6-1-ki-9", "prompt": "Dolap kelimesiyle yer ilişkisi kuran doğru biçim hangisidir?", "choices": ["Dolaptaki sözlük yeniydi.", "Dolapta ki sözlük yeniydi.", "Dolap taki sözlük yeniydi."], "answer": "Dolaptaki sözlük yeniydi.", "explanation": "Dolaptaki sözü -ki ekini bitişik alır."}, {"id": "6-1-ki-10", "prompt": "Ek ve bağlaç hangi cümlede birlikte doğru yazılmıştır?", "choices": ["Benim ki öyle kısaydıki hemen okundu.", "Benimki öyle kısaydıki hemen okundu.", "Benimki öyle kısaydı ki hemen okundu."], "answer": "Benimki öyle kısaydı ki hemen okundu.", "explanation": "Benimki ek alır; yargıları ilişkilendiren ki ise ayrı yazılır."}]}'::jsonb),
(6,'6-1-6-1-soru-eki',8,'{"id": "6-1-6-1-soru-eki", "title": "Soru eki mı, mi, mu, mü", "theme": "Dilimizin Zenginliği", "kind": "lesson", "body": {"html": "<p>Soru eki mı, mi, mu, mü kendinden önceki kelimeden ayrı yazılır. Ardından gelen kişi veya zaman ekleri bu eke bitişir. Soru eki yalnız cümlenin sonuna gelmez; sorunun odağındaki unsurdan sonra da kullanılabilir. Bazı kullanımlarda soru anlamı yerine pekiştirme ya da koşula yakın anlam taşır; bu durum ayrı yazılmasını değiştirmez. Ses uyumunu ve ekten sonraki eklerin yazımını birlikte kontrol et.</p><ul><li>Bu kelimeyi duydun mu?</li><li>Sen de gelir misin?</li><li>Güzel mi güzel bir anlatımdı.</li></ul>", "examples": ["Bu kelimeyi duydun mu?", "Sen de gelir misin?", "Güzel mi güzel bir anlatımdı."], "code": "T.Y.6.21"}, "questions": [{"id": "6-1-soru-eki-1", "prompt": "Soru ekinin doğru yazıldığı cümle hangisidir?", "choices": ["Bu sözü duydunmu?", "Bu sözü duydun-mu?", "Bu sözü duydun mu?"], "answer": "Bu sözü duydun mu?", "explanation": "Mu kendinden önceki kelimeden ayrı yazılır."}, {"id": "6-1-soru-eki-2", "prompt": "Kişi ekinin soru ekine doğru bağlandığı seçenek hangisidir?", "choices": ["Bize katılırmısın?", "Bize katılır mısın?", "Bize katılır mı sın?"], "answer": "Bize katılır mısın?", "explanation": "Soru eki ayrı başlar; kişi eki ona bitişir."}, {"id": "6-1-soru-eki-3", "prompt": "Özneyi soru odağı yapan doğru cümle hangisidir?", "choices": ["Bu notu Ece mi yazdı?", "Bu notu Ecemi yazdı?", "Bu notu Ece-mi yazdı?"], "answer": "Bu notu Ece mi yazdı?", "explanation": "Mi, Ece kelimesinden sonra ayrı yazılarak özneyi sorar."}, {"id": "6-1-soru-eki-4", "prompt": "Yere yönelik sorunun doğru yazımı hangisidir?", "choices": ["Toplantı buradamı yapılacak?", "Toplantı burada-mı yapılacak?", "Toplantı burada mı yapılacak?"], "answer": "Toplantı burada mı yapılacak?", "explanation": "Mı yer bildiren burada sözünden ayrı yazılır."}, {"id": "6-1-soru-eki-5", "prompt": "Çoğul kişi ekli doğru soru hangisidir?", "choices": ["Hazırmısınız?", "Hazır mısınız?", "Hazır mı sınız?"], "answer": "Hazır mısınız?", "explanation": "Mısınız kendi içinde bitişik, önceki kelimeden ayrı yazılır."}, {"id": "6-1-soru-eki-6", "prompt": "Geçmiş zaman ekiyle soru hangi seçenekte doğrudur?", "choices": ["Bu açıklama doğru muydu?", "Bu açıklama doğrumuydu?", "Bu açıklama doğru mu ydu?"], "answer": "Bu açıklama doğru muydu?", "explanation": "Mu ayrı yazılır; kendisinden sonraki ekler ona bitişir."}, {"id": "6-1-soru-eki-7", "prompt": "Pekiştirme anlamında soru eki hangi cümlede doğru yazılmıştır?", "choices": ["Uzunmu uzun bir metindi.", "Uzun-mu uzun bir metindi.", "Uzun mu uzun bir metindi."], "answer": "Uzun mu uzun bir metindi.", "explanation": "Soru anlamı bulunmasa da mu ayrı yazılır."}, {"id": "6-1-soru-eki-8", "prompt": "İkinci çoğul kişiye yönelen doğru soru hangisidir?", "choices": ["Yarın gelir mi siniz?", "Yarın gelir misiniz?", "Yarın gelirmisiniz?"], "answer": "Yarın gelir misiniz?", "explanation": "Mi önceki kelimeden ayrı, siniz kişi ekiyle bitişik yazılır."}, {"id": "6-1-soru-eki-9", "prompt": "Soru ekinin ünlü uyumuna uygun yazımı hangisidir?", "choices": ["Bu sözcük yeni mi?", "Bu sözcük yeni mı?", "Bu sözcük yeni mu?"], "answer": "Bu sözcük yeni mi?", "explanation": "Yeni kelimesinin son ünlüsüne göre mi biçimi seçilir."}, {"id": "6-1-soru-eki-10", "prompt": "İki ayrı dil unsurunun doğru yazıldığı soru hangisidir?", "choices": ["Sende dinledinmi?", "Sen de dinledinmi?", "Sen de dinledin mi?"], "answer": "Sen de dinledin mi?", "explanation": "Katılma bağlacı de ve soru eki mi ayrı yazılır."}]}'::jsonb),
(6,'6-1-6-1-virgul-bolum-1',9,'{"id": "6-1-6-1-virgul-bolum-1", "title": "Virgülün cümledeki işlevleri · 1", "theme": "Dilimizin Zenginliği", "kind": "lesson", "body": {"html": "<p>Virgül, cümledeki anlam ilişkilerini görmeye yardım eder. Özne olarak kullanılan bu, şu, o sözlerinden sonra anlam karışıklığını önlemek için gelebilir. Birbirine bağlanan sıralı cümleleri ayırabilir; evet, hayır, peki gibi sözleri sonraki cümleden ayırabilir. Her nefes alınan yere virgül koymak doğru değildir. Özellikle özne olmayan her bu sözünün arkasına otomatik olarak virgül getirilmez. Önce cümlenin yapısını ve işaretin görevini düşün.</p><ul><li>O, örnekleri dikkatle seçti.</li><li>Kapı açıldı, öğrenciler içeri girdi.</li><li>Evet, bu metni okudum.</li></ul>", "examples": ["O, örnekleri dikkatle seçti.", "Kapı açıldı, öğrenciler içeri girdi.", "Evet, bu metni okudum."], "code": "T.Y.6.21"}, "questions": [{"id": "6-1-virgul-1", "prompt": "O, panodaki notu okudu. cümlesindeki virgülün görevi nedir?", "choices": ["Bir tarih belirtmek", "Kelimeyi hecelerine ayırmak", "Özne olan zamiri sonraki sözlerden ayırmak"], "answer": "Özne olan zamiri sonraki sözlerden ayırmak", "explanation": "O özne görevinde kullanılan bir zamirdir."}, {"id": "6-1-virgul-2", "prompt": "Pencere açıldı, perde hareket etti. cümlesinde virgül neyi ayırır?", "choices": ["Bir kitabın adını", "Sıralı cümleleri", "Bir kelimenin eklerini"], "answer": "Sıralı cümleleri", "explanation": "Açıldı ve hareket etti yüklemleriyle kurulan iki cümle ayrılmıştır."}, {"id": "6-1-virgul-3", "prompt": "Hayır, bu bilgiyi henüz doğrulamadım. cümlesinde virgülün görevi nedir?", "choices": ["Ret bildiren sözü sonraki cümleden ayırmak", "Kesirli sayı göstermek", "Satır sonundaki kelimeyi bölmek"], "answer": "Ret bildiren sözü sonraki cümleden ayırmak", "explanation": "Hayır ret bildirir ve devamındaki cümleden virgülle ayrılır."}, {"id": "6-1-virgul-4", "prompt": "Evet, kaynağı kontrol ettim. cümlesinde virgül neyi belirtir?", "choices": ["Bir alıntının kaynakçasını", "Bir saat bilgisini", "Kabul bildiren sözün sınırını"], "answer": "Kabul bildiren sözün sınırını", "explanation": "Evet kabul bildirir; virgül bu sözü sonraki cümleden ayırır."}, {"id": "6-1-virgul-5", "prompt": "Peki, önce sen anlat. cümlesinde virgülün işlevi nedir?", "choices": ["Bir başlığı kısaltmak", "Kabul veya geçiş bildiren sözü ayırmak", "Özel ada ek bağlamak"], "answer": "Kabul veya geçiş bildiren sözü ayırmak", "explanation": "Peki sözü cümlenin devamından virgülle ayrılmıştır."}, {"id": "6-1-virgul-6", "prompt": "Bu, dikkatle hazırlanmış bir dosya. cümlesinde virgül neden kullanılmıştır?", "choices": ["Bu zamirini ardından gelen sözlerden ayırmak", "Her bu kelimesinden sonra zorunlu olduğu için", "Dosya kelimesini kısaltmak için"], "answer": "Bu zamirini ardından gelen sözlerden ayırmak", "explanation": "Bu tek başına bir adın yerini tutarak özne olmuştur."}, {"id": "6-1-virgul-7", "prompt": "Bu dosya bugün geldi. cümlesinde bu sözünden hemen sonra virgül niçin gerekmez?", "choices": ["Bu sözü hiçbir cümlede virgül alamaz", "Cümlede zaman sözü bulunduğu için", "Bu, dosya adını belirtiyor; tek başına özne zamiri değil"], "answer": "Bu, dosya adını belirtiyor; tek başına özne zamiri değil", "explanation": "Bu dosya bir ad grubudur; araya gereksiz virgül getirilmez."}]}'::jsonb),
(6,'6-1-6-1-virgul-bolum-2',10,'{"id": "6-1-6-1-virgul-bolum-2", "title": "Virgülün cümledeki işlevleri · 2", "theme": "Dilimizin Zenginliği", "kind": "lesson", "body": {"html": "<p>Virgül, cümledeki anlam ilişkilerini görmeye yardım eder. Özne olarak kullanılan bu, şu, o sözlerinden sonra anlam karışıklığını önlemek için gelebilir. Birbirine bağlanan sıralı cümleleri ayırabilir; evet, hayır, peki gibi sözleri sonraki cümleden ayırabilir. Her nefes alınan yere virgül koymak doğru değildir. Özellikle özne olmayan her bu sözünün arkasına otomatik olarak virgül getirilmez. Önce cümlenin yapısını ve işaretin görevini düşün.</p><ul><li>O, örnekleri dikkatle seçti.</li><li>Kapı açıldı, öğrenciler içeri girdi.</li><li>Evet, bu metni okudum.</li></ul>", "examples": ["O, örnekleri dikkatle seçti.", "Kapı açıldı, öğrenciler içeri girdi.", "Evet, bu metni okudum."], "code": "T.Y.6.21"}, "questions": [{"id": "6-1-virgul-8", "prompt": "Yazı bitti, kontrol başladı. cümlesindeki virgülün görevi nedir?", "choices": ["Bir kişiye ek getirmek", "İki yargıyı birbirinden ayırmak", "Bir sözcüğün kökünü göstermek"], "answer": "İki yargıyı birbirinden ayırmak", "explanation": "Bitti ve başladı ayrı yargılardır; sıralı cümleler virgülle ayrılır."}, {"id": "6-1-virgul-9", "prompt": "Şu, aradığımız örnek olabilir. cümlesindeki virgül hangi kullanıma örnektir?", "choices": ["Özne olarak kullanılan zamiri ayırma", "Hitap edilen kişiyi belirtme", "Parantez içi bilgi ekleme"], "answer": "Özne olarak kullanılan zamiri ayırma", "explanation": "Şu bir adın yerini tutar ve ardından virgül gelir."}, {"id": "6-1-virgul-10", "prompt": "Hadi, bir örnek daha deneyelim. cümlesinde virgül neyi ayırır?", "choices": ["Alfabetik sıra numarasını", "İki özel adı", "Teşvik bildiren sözü"], "answer": "Teşvik bildiren sözü", "explanation": "Hadi teşvik bildirir; ardından gelen cümleden virgülle ayrılır."}, {"id": "6-1-virgul-11", "prompt": "Şimdi başlayalım, dedi öğretmen. cümlesinde virgül neyi ayırır?", "choices": ["Bir tarih aralığını", "Tırnak içinde olmayan alıntı cümlesini", "Kelimenin yapım ekini"], "answer": "Tırnak içinde olmayan alıntı cümlesini", "explanation": "Tırnak içinde verilmeyen alıntı söz, dedi ifadesinden virgülle ayrılır."}, {"id": "6-1-virgul-12", "prompt": "— Notları ben getiririm, dedi Ece. satırında virgül neyi ayırır?", "choices": ["Konuşma çizgisinden sonraki alıntı cümlesini", "Özel adın çekim ekini", "Bir saat bilgisini"], "answer": "Konuşma çizgisinden sonraki alıntı cümlesini", "explanation": "Konuşma çizgisiyle verilen alıntı söz, bildirme ifadesinden virgülle ayrılır."}, {"id": "6-1-virgul-13", "prompt": "Duru arkadaşlarına dönerek, — Bir daha deneyelim, dedi. aktarımında dönerek sözünden sonraki virgülün görevi nedir?", "choices": ["Her fiilimsi sözünden sonra zorunlu işaret koymak", "Konuşmayı soruya çevirmek", "Edebî anlatıda konuşma bölümünden önceki ifadeyi ayırmak"], "answer": "Edebî anlatıda konuşma bölümünden önceki ifadeyi ayırmak", "explanation": "Bu virgül, edebî anlatıdaki konuşma bölümünü hazırlayan ifadeyi ayırır; genel bir fiilimsi kuralı değildir."}]}'::jsonb),
(6,'6-1-6-1-baglam',11,'{"id": "6-1-6-1-baglam", "title": "Bağlama uygun söz varlığı", "theme": "Dilimizin Zenginliği", "kind": "lesson", "body": {"html": "<p>Yakın anlamlı kelimeler her cümlede aynı etkiyi oluşturmaz. Yazıda seçtiğin söz, anlatmak istediğin duruma uymalıdır. Deyimler ve kalıp sözler de yalnız süs olsun diye eklenmez; anlamı doğru karşılamaları gerekir. Önce neyi anlatacağını belirle, sonra sözün bağlamdaki anlamını kontrol et. Yeni öğrendiğin kelimeyi özgün bir cümlede kullanmak ve cümleyi bir arkadaşına açıklatmak, uygunluğu gözden geçirmene yardım eder.</p><ul><li>Yeni bir fikir aklıma geldi.</li><li>Konuyu aydınlatan bir örnek sundu.</li><li>Haber onu çok sevindirdi.</li></ul>", "examples": ["Yeni bir fikir aklıma geldi.", "Konuyu aydınlatan bir örnek sundu.", "Haber onu çok sevindirdi."], "code": "T.Y.6.18"}, "questions": [{"id": "6-1-baglam-1", "prompt": "Bir konuya dikkatle yönelmeyi anlatmak için hangi deyim uygundur?", "choices": ["Burnu havada olmak", "Kulak vermek", "Etekleri zil çalmak"], "answer": "Kulak vermek", "explanation": "Kulak vermek dikkatle dinlemek anlamında kullanılır."}, {"id": "6-1-baglam-2", "prompt": "Çok sevinmeyi anlatan deyim hangisidir?", "choices": ["Etekleri zil çalmak", "Ağzını bıçak açmamak", "Burnundan solumak"], "answer": "Etekleri zil çalmak", "explanation": "Etekleri zil çalmak güçlü sevinci karşılar."}, {"id": "6-1-baglam-3", "prompt": "Bir sorunun açıklığa kavuşmasını anlatan cümle hangisidir?", "choices": ["Bu örnek pencereyi kapattı.", "Bu örnek kitabı ağırlaştırdı.", "Bu örnek konuyu aydınlattı."], "answer": "Bu örnek konuyu aydınlattı.", "explanation": "Aydınlatmak mecaz anlamıyla anlaşılır kılmayı anlatır."}, {"id": "6-1-baglam-4", "prompt": "Yaptığı işe titizlik gösteren biri için hangi söz uygundur?", "choices": ["Umursamaz", "Özenli", "Savruk"], "answer": "Özenli", "explanation": "Özenli, işini dikkat ve titizlikle yapan kişiyi niteler."}, {"id": "6-1-baglam-5", "prompt": "Kaynakları denetlemeden kesin konuşmayan birinin yazısı nasıl nitelenir?", "choices": ["Temkinli", "Gelişigüzel", "Savruk"], "answer": "Temkinli", "explanation": "Temkinli anlatım, yeterli dayanak olmadan kesinlik kurmaktan kaçınır."}, {"id": "6-1-baglam-6", "prompt": "Bir fikri ayrıntılı biçimde açıklamak için hangi fiil daha uygundur?", "choices": ["Saklamak", "Dağıtmak", "Açımlamak"], "answer": "Açımlamak", "explanation": "Açımlamak, anlamı veya düşünceyi açıklayıp belirginleştirmektir."}, {"id": "6-1-baglam-7", "prompt": "Arkadaşının başarısını kutlarken hangi kalıp söz uygundur?", "choices": ["Başın sağ olsun.", "Tebrik ederim.", "Geçmiş olsun."], "answer": "Tebrik ederim.", "explanation": "Tebrik ederim başarı veya sevindirici gelişme karşısında kullanılır."}, {"id": "6-1-baglam-8", "prompt": "Birinin sunduğu yardıma karşı hangi ifade bağlama uygundur?", "choices": ["Teşekkür ederim.", "Güle güle.", "Afiyet olsun."], "answer": "Teşekkür ederim.", "explanation": "Yardım karşısında teşekkür etmek uygun bir kalıp söz kullanımıdır."}, {"id": "6-1-baglam-9", "prompt": "Yazının anlaşılmasını kolaylaştıran özellik hangisidir?", "choices": ["Belirsizlik", "Çelişki", "Açıklık"], "answer": "Açıklık", "explanation": "Açıklık, anlatımın okur tarafından anlaşılır olmasını karşılar."}, {"id": "6-1-baglam-10", "prompt": "Düşüncelerin birbiriyle uyumlu ilerlemesini anlatan kelime hangisidir?", "choices": ["Gürültü", "Tutarlılık", "Rastlantı"], "answer": "Tutarlılık", "explanation": "Tutarlılık, yazıdaki düşüncelerin birbirini boşa çıkarmadan ilerlemesidir."}]}'::jsonb),
(6,'6-1-dinleme',12,'{"id": "6-1-dinleme", "title": "Kelime Kartının Arkası", "theme": "Dilimizin Zenginliği", "kind": "listening", "body": {"text": "Dil atölyesinde bugün kartların yalnız önünü değil, arkasını da dolduracağız. Ön tarafa seçtiğiniz kelimeyi yazın. Arkaya kelimeyi duyduğunuz cümleyi ve bağlamdan çıkardığınız anlamı ekleyin. Ardından tahmininizi bir sözlükle kontrol edin. Kartta kişinin özel bilgileri bulunmasın. Bir ses kaydı paylaşacaksanız önce izin alın. Son adımda kelimeyi kendi cümlenizde kullanın. Kartı arkadaşınız okuduğunda anlamı açıklayabiliyor mu, birlikte kontrol edin. Yanlış tahmin yaptıysanız ilk notu saklayıp yanına düzeltme koyabilirsiniz. Bugünkü amacımız kart sayısını artırmak değil, kelimeleri kullanım çevreleriyle tanımaktır."}, "questions": [{"id": "6-1-dinleme-1", "prompt": "“Kelime Kartının Arkası” dinleme metnine göre: Kartın önüne ne yazılır?", "choices": ["Kişinin özel adresi", "Yalnız kartın fiyatı", "Seçilen kelime"], "answer": "Seçilen kelime", "explanation": "Yönergede ön tarafa seçilen kelimenin yazılması istenir."}, {"id": "6-1-dinleme-2", "prompt": "“Kelime Kartının Arkası” dinleme metnine göre: Tahmin neyle kontrol edilir?", "choices": ["Arkadaş sayısıyla", "Sözlükle", "Kartın rengiyle"], "answer": "Sözlükle", "explanation": "Metin anlam tahmininin sözlük yardımıyla kontrol edilmesini söyler."}, {"id": "6-1-dinleme-3", "prompt": "“Kelime Kartının Arkası” dinleme metnine göre: Anahtar kelime grubu hangisidir?", "choices": ["Kelime, bağlam, anlam", "Ulaşım, durak, bilet", "Yağış, sıcaklık, rüzgâr"], "answer": "Kelime, bağlam, anlam", "explanation": "Etkinlik kelimelerin kullanım çevresi ve anlamları üzerinedir."}, {"id": "6-1-dinleme-4", "prompt": "“Kelime Kartının Arkası” dinleme metnine göre: Kart sayısı yerine neye önem verilir?", "choices": ["En kalın kartonu almaya", "Bütün kayıtları izinsiz yayımlamaya", "Kelimeleri kullanımlarıyla tanımaya"], "answer": "Kelimeleri kullanımlarıyla tanımaya", "explanation": "Son cümlede hedefin sayı değil, kullanım çevresini tanımak olduğu belirtilir."}]}'::jsonb),
(6,'6-2-soz-1',13,'{"id": "6-2-soz-1", "title": "Söz varlığı · 1", "theme": "Bağımsızlık Yolu", "kind": "words", "body": [{"kelime": "bağımsızlık", "anlam": "Bir topluluğun kendi kararlarını kendisinin verebilmesi", "ornek": "Serginin konusu bağımsızlık mücadelesiydi.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "egemenlik", "anlam": "Yönetme ve karar verme yetkisi", "ornek": "Sınıf meclisinde egemenlik kavramını tartıştık.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "cumhuriyet", "anlam": "Yönetim yetkisinin milletin seçtiği temsilciler aracılığıyla kullanıldığı yönetim biçimi", "ornek": "Cumhuriyet üzerine bir okuma yaptık.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "dayanışma", "anlam": "Bir amaç veya güçlük karşısında birbirine destek olma", "ornek": "Mahalledeki dayanışma herkesi cesaretlendirdi.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "fedakârlık", "anlam": "Bir amaç için kendi isteğinden veya rahatından vazgeçme", "ornek": "Gönüllüler zamanlarından fedakârlık etti.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "kararlılık", "anlam": "Bir kararın arkasında durup çalışmayı sürdürme", "ornek": "Ekibin kararlılığı hazırlıklara yansıdı.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "sorumluluk", "anlam": "Üstlenilen işi yerine getirme yükümlülüğü", "ornek": "Belgeleri koruma sorumluluğu bana verildi.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "emanet", "anlam": "Korunması veya sonradan geri verilmesi için bırakılan şey", "ornek": "Defter bize bir emanet olarak bırakıldı.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "cephe", "anlam": "Bir savaşta karşıt güçlerin karşılaştığı bölge", "ornek": "Anlatının bir bölümü cephe gerisinde geçiyor.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "seferberlik", "anlam": "Bir ihtiyacı karşılamak için bütün imkânlarla birlikte harekete geçme", "ornek": "Kitap onarımı için seferberlik başlattık.", "tip": "kelime", "cikti": "T.O.6.21"}], "questions": [{"id": "6-2-