(6,'6-2-soz-3',15,'{"id": "6-2-soz-3", "title": "Söz varlığı · 3", "theme": "Bağımsızlık Yolu", "kind": "words", "body": [{"kelime": "birlik", "anlam": "Aynı amaç çevresinde birleşme durumu", "ornek": "Birlik içinde hazırlıkları tamamladık.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "ulaştırmak", "anlam": "Bir şeyi gitmesi gereken yere götürmek veya göndermek", "ornek": "Kutuları depoya ulaştırdık.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "korumak", "anlam": "Zarar görmesini veya kaybolmasını önlemek", "ornek": "Eski fotoğrafları ışıktan korumak gerekiyordu.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "hatırat", "anlam": "Bir kişinin yaşadıklarını sonradan anlattığı eser", "ornek": "Hatıratın ne zaman yazıldığını araştırdım.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "bellek", "anlam": "Yaşananları ve öğrenilenleri saklama yetisi", "ornek": "Müze toplumsal belleğe katkı sağlıyor.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "restorasyon", "anlam": "Bir eseri özgün özelliklerini gözeterek onarma işi", "ornek": "Binadaki restorasyon uzmanlarca yürütüldü.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "özgürlük", "anlam": "Başkalarının haklarını gözeterek seçim yapabilme durumu", "ornek": "Özgürlük ile sorumluluğu birlikte konuştuk.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "uzlaşma", "anlam": "Farklı görüşlerin ortak bir çözümde buluşması", "ornek": "Sergi düzeninde uzlaşma sağlandı.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "katılım", "anlam": "Bir çalışmada veya kararda yer alma", "ornek": "Gönüllü katılım için duyuru hazırladık.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "güven", "anlam": "Birine veya bir şeye duyulan inanma duygusu", "ornek": "Açık bilgi paylaşımı güven oluşturdu.", "tip": "kelime", "cikti": "T.O.6.21"}], "questions": [{"id": "6-2-kelime-20", "prompt": "“birlik” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Aynı amaç çevresinde birleşme durumu", "Bir topluluğun kendi kararlarını kendisinin verebilmesi", "Yönetme ve karar verme yetkisi", "Yönetim yetkisinin milletin seçtiği temsilciler aracılığıyla kullanıldığı yönetim biçimi"], "answer": "Aynı amaç çevresinde birleşme durumu", "explanation": "Birlik içinde hazırlıkları tamamladık."}, {"id": "6-2-kelime-21", "prompt": "“ulaştırmak” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir şeyi gitmesi gereken yere götürmek veya göndermek", "Yönetme ve karar verme yetkisi", "Yönetim yetkisinin milletin seçtiği temsilciler aracılığıyla kullanıldığı yönetim biçimi", "Bir amaç veya güçlük karşısında birbirine destek olma"], "answer": "Bir şeyi gitmesi gereken yere götürmek veya göndermek", "explanation": "Kutuları depoya ulaştırdık."}, {"id": "6-2-kelime-22", "prompt": "“korumak” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Zarar görmesini veya kaybolmasını önlemek", "Yönetim yetkisinin milletin seçtiği temsilciler aracılığıyla kullanıldığı yönetim biçimi", "Bir amaç veya güçlük karşısında birbirine destek olma", "Bir amaç için kendi isteğinden veya rahatından vazgeçme"], "answer": "Zarar görmesini veya kaybolmasını önlemek", "explanation": "Eski fotoğrafları ışıktan korumak gerekiyordu."}, {"id": "6-2-kelime-23", "prompt": "“hatırat” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir kişinin yaşadıklarını sonradan anlattığı eser", "Bir amaç veya güçlük karşısında birbirine destek olma", "Bir amaç için kendi isteğinden veya rahatından vazgeçme", "Bir kararın arkasında durup çalışmayı sürdürme"], "answer": "Bir kişinin yaşadıklarını sonradan anlattığı eser", "explanation": "Hatıratın ne zaman yazıldığını araştırdım."}, {"id": "6-2-kelime-24", "prompt": "“bellek” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Yaşananları ve öğrenilenleri saklama yetisi", "Bir amaç için kendi isteğinden veya rahatından vazgeçme", "Bir kararın arkasında durup çalışmayı sürdürme", "Üstlenilen işi yerine getirme yükümlülüğü"], "answer": "Yaşananları ve öğrenilenleri saklama yetisi", "explanation": "Müze toplumsal belleğe katkı sağlıyor."}, {"id": "6-2-kelime-25", "prompt": "“restorasyon” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir eseri özgün özelliklerini gözeterek onarma işi", "Bir kararın arkasında durup çalışmayı sürdürme", "Üstlenilen işi yerine getirme yükümlülüğü", "Korunması veya sonradan geri verilmesi için bırakılan şey"], "answer": "Bir eseri özgün özelliklerini gözeterek onarma işi", "explanation": "Binadaki restorasyon uzmanlarca yürütüldü."}, {"id": "6-2-kelime-26", "prompt": "“özgürlük” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Başkalarının haklarını gözeterek seçim yapabilme durumu", "Üstlenilen işi yerine getirme yükümlülüğü", "Korunması veya sonradan geri verilmesi için bırakılan şey", "Bir savaşta karşıt güçlerin karşılaştığı bölge"], "answer": "Başkalarının haklarını gözeterek seçim yapabilme durumu", "explanation": "Özgürlük ile sorumluluğu birlikte konuştuk."}, {"id": "6-2-kelime-27", "prompt": "“uzlaşma” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Farklı görüşlerin ortak bir çözümde buluşması", "Korunması veya sonradan geri verilmesi için bırakılan şey", "Bir savaşta karşıt güçlerin karşılaştığı bölge", "Bir ihtiyacı karşılamak için bütün imkânlarla birlikte harekete geçme"], "answer": "Farklı görüşlerin ortak bir çözümde buluşması", "explanation": "Sergi düzeninde uzlaşma sağlandı."}, {"id": "6-2-kelime-28", "prompt": "“katılım” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir çalışmada veya kararda yer alma", "Bir savaşta karşıt güçlerin karşılaştığı bölge", "Bir ihtiyacı karşılamak için bütün imkânlarla birlikte harekete geçme", "Bir başkasının yararı için kendi çıkarından vazgeçme"], "answer": "Bir çalışmada veya kararda yer alma", "explanation": "Gönüllü katılım için duyuru hazırladık."}, {"id": "6-2-kelime-29", "prompt": "“güven” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Birine veya bir şeye duyulan inanma duygusu", "Bir ihtiyacı karşılamak için bütün imkânlarla birlikte harekete geçme", "Bir başkasının yararı için kendi çıkarından vazgeçme", "Bir topluluğun yaşadığı ve bağlılık duyduğu ülke"], "answer": "Birine veya bir şeye duyulan inanma duygusu", "explanation": "Açık bilgi paylaşımı güven oluşturdu."}]}'::jsonb),
(6,'6-2-okuma-1',16,'{"id": "6-2-okuma-1", "title": "Sandığın Yanındaki Not", "theme": "Bağımsızlık Yolu", "kind": "reading", "body": {"text": "Okulun bodrumundaki küçük sandık açıldığında öğrenciler bir hazine bulduklarını sandılar. İçinden altın veya değerli taş çıkmadı. Birkaç eski fotoğraf, kenarı yıpranmış bir defter ve tarihinin son rakamı silinmiş bir mektup vardı. Sınıf, bağımsızlık konulu sergileri için bu eşyaları inceleyecekti. Görevli öğretmen, nesneleri koruyucu örtünün üzerine koydu. Önce bakmalarını, dokunmaları gerekirse kendisine haber vermelerini istedi.\nEfe, mektubun bir savaş kahramanına ait olduğunu hemen ilan etti. Ona göre eski yazı ve sararmış kâğıt bunu kanıtlıyordu. Duru ise aynı sonuca ulaşmadı. Bir nesnenin eski olması, sahibinin kimliğini göstermezdi. Öğretmen bu itirazı önemsedi. İki öğrenciden de düşüncelerini destekleyen bilgileri ve henüz bilmediklerini ayrı ayrı yazmalarını istedi. Efe''nin listesinde sandığın bulunduğu yer vardı; mektubun yazarı ise yoktu.\nDefterde bazı malzemelerin adları ve yanlarında sayılar bulunuyordu. Bir sayfada kumaş, başka bir sayfada yiyecek listelenmişti. Öğrenciler önce bunu sıradan bir alışveriş defteri sandı. Sonra sayfalar arasındaki notu gördüler: Malzemeler ortak bir depoya teslim edilmişti. Yine de deponun ne zaman ve hangi amaçla kullanıldığını bilmiyorlardı. Defterin bütün sayfalarını tarih sırasına koymadan yorum yapmamaya karar verdiler.\nErtesi gün okul arşivinin sorumlusu onlara eski kayıtları gösterdi. Sandığın yıllar önce düzenlenen bir anma etkinliği için bağışlandığı anlaşıldı. Ancak bağış kaydında eşyaların ilk sahipleri belirtilmemişti. Öğrenciler, ulaşamadıkları bilgiyi kesin bir hikâyeyle doldurmadı. Sergi etiketine nesnelerin nereden geldiğini bildiklerini, daha eski geçmişlerini ise araştırdıklarını yazdılar. Efe başlangıçtaki iddiasını kaldırmayı kabul etti.\nSerginin açılışında en çok soru, gösterişli başlığın altında duran küçük not için soruldu. Notta “Birlikte çalışmanın izleri var; kimin hangi görevi yaptığı henüz kesin değil.” yazıyordu. Duru ziyaretçilere bağımsızlık mücadelesini anlamanın yalnız ünlü isimleri sıralamakla sınırlı olmadığını anlattı. İnsanların ortak bir amaç için üstlendikleri işleri de araştırmak gerekiyordu. Efe ise boş bırakılan bir bilginin, yanlış bir kesinlikten daha dürüst olabileceğini ekledi. Sandık artık onlara altın sakladığı için değerli görünmüyordu. Korunmayı, soru sormayı ve kanıta dayanarak konuşmayı öğreten bir çalışma başlatmıştı. Sınıf sergi kapandıktan sonra da araştırma notlarını sakladı. Yeni bir belge bulunursa etiketleri yeniden yazabileceklerdi. Bu yüzden son sayfaya büyük harflerle “Araştırma sürüyor.” notunu düştüler.", "type": "oykuleyici"}, "questions": [{"id": "6-2-okuma-1-1", "prompt": "“Sandığın Yanındaki Not” metnine göre: Efe ile Duru''nun ilk yorumları nasıl farklıdır?", "choices": ["Duru mektubu okumadan yok etmek ister", "Efe kesin konuşur, Duru kanıtın yeterli olmadığını düşünür", "İkisi de mektubun yazarını bilir"], "answer": "Efe kesin konuşur, Duru kanıtın yeterli olmadığını düşünür", "explanation": "Efe eski görünüşü yeterli bulurken Duru sahibin bilinmediğini hatırlatır."}, {"id": "6-2-okuma-1-2", "prompt": "“Sandığın Yanındaki Not” metnine göre: Öğretmenin bilgileri iki listeye ayırtması hangi amaca hizmet eder?", "choices": ["Bilinenle varsayılanı ayırmaya", "Öğrencileri hız yarışına sokmaya", "Belgelerin fiyatını belirlemeye"], "answer": "Bilinenle varsayılanı ayırmaya", "explanation": "Destekleyen bilgiler ve bilinmeyenler ayrı yazılarak kesinlik sınırları görünür olur."}, {"id": "6-2-okuma-1-3", "prompt": "“Sandığın Yanındaki Not” metnine göre: Defterdeki malzeme listeleri hangi gruba girer?", "choices": ["Kesinleşmiş sözlü tanıklıklar", "Sergi için üretilmiş oyuncaklar", "İncelenecek yazılı kayıtlar"], "answer": "İncelenecek yazılı kayıtlar", "explanation": "Defter sayfaları yazılı kayıt niteliğindedir; sözlü tanıklık değildir."}, {"id": "6-2-okuma-1-4", "prompt": "“Sandığın Yanındaki Not” metnine göre: Ortak depoya teslim notundan hangi sonuç çıkarılabilir?", "choices": ["Mektubun kesinlikle aynı gün yazıldığı", "Malzemelerin bir yere birlikte toplandığı", "Depodaki bütün kişilerin adlarının bilindiği"], "answer": "Malzemelerin bir yere birlikte toplandığı", "explanation": "Teslim notu toplama işini gösterir, kişileri veya mektubun tarihini kanıtlamaz."}, {"id": "6-2-okuma-1-5", "prompt": "“Sandığın Yanındaki Not” metnine göre: Efe''nin iddiasını kaldırması neyi gösterir?", "choices": ["Yeni bilgi karşısında görüşünü düzeltebildiğini", "Araştırmaya hiç katılmadığını", "Bütün belgelerin sahte olduğunu"], "answer": "Yeni bilgi karşısında görüşünü düzeltebildiğini", "explanation": "Efe, kanıt eksikliği ortaya çıktığında ilk yargısını değiştirir."}, {"id": "6-2-okuma-1-6", "prompt": "“Sandığın Yanındaki Not” metnine göre: Eski kelimesinin metindeki kullanımı hangisidir?", "choices": ["Çalışmayan elektronik araç", "Önemsiz ve değersiz", "Uzun zaman önceye ait"], "answer": "Uzun zaman önceye ait", "explanation": "Fotoğraf ve belgeler için kullanılan eski, zaman bakımından önceye ait olmayı belirtir."}, {"id": "6-2-okuma-1-7", "prompt": "“Sandığın Yanındaki Not” metnine göre: Metnin en uygun özeti hangisidir?", "choices": ["Öğrenciler bütün soruların cevabını ilk gün bulur", "Öğrenciler belgeleri inceleyip kesin olmayan bilgileri açıkça belirten bir sergi hazırlar", "Öğrenciler sandıktan çıkan altınları paylaşır"], "answer": "Öğrenciler belgeleri inceleyip kesin olmayan bilgileri açıkça belirten bir sergi hazırlar", "explanation": "Olayların bütünü araştırma sürecini ve dürüst sergi etiketini anlatır."}, {"id": "6-2-okuma-1-8", "prompt": "“Sandığın Yanındaki Not” metnine göre: Son notun araştırma sürüyor olması neyi düşündürür?", "choices": ["Yeni kanıtların açıklamaları değiştirebileceğini", "Serginin hiç açılmadığını", "Belgelerin artık korunmayacağını"], "answer": "Yeni kanıtların açıklamaları değiştirebileceğini", "explanation": "Öğrenciler yeni belge bulunursa etiketleri güncellemek üzere notları saklar."}]}'::jsonb),
(6,'6-2-okuma-2',17,'{"id": "6-2-okuma-2", "title": "Bir Serginin İki Taslağı", "theme": "Bağımsızlık Yolu", "kind": "reading", "body": {"text": "Bağımsızlık konulu bir okul sergisi hazırlayan iki grup, aynı belge kopyalarını kullanarak farklı taslaklar oluşturdu. İlk grup serginin girişine büyük bir zaman çizelgesi yerleştirdi. Her olayın yanına kısa bir açıklama koydu. İkinci grup ise sergiyi insanların üstlendiği işlere göre düzenledi. Haber ulaştırma, yiyecek hazırlama ve malzeme taşıma gibi başlıkların altında belgelerden seçilmiş örnekler sundu. İki taslak da aynı konuyu işliyor, fakat ziyaretçinin izleyeceği yolu farklı kuruyordu.\nZaman çizelgesinin güçlü yanı, olayların önce ve sonra ilişkisini görünür kılmasıydı. Ziyaretçi bir kararın hangi gelişmeden önce alındığını kolayca izleyebilirdi. Ancak çizelgede çok sayıda tarih bulunduğunda açıklamalar küçülüyor, bazı öğrenciler okurken zorlanıyordu. Grubun çözümü, daha az olay seçmek ve ayrıntıları isteyenlerin okuyabileceği ayrı kartlara taşımak oldu. Böylece tarih sırası korunurken ilk bakışta görülen bilgi azaldı.\nİşlere göre düzenlenen taslak, ortak emeğin farklı yönlerini göstermede başarılıydı. Bir ziyaretçi aynı dönemde birden çok görevin birlikte yürütüldüğünü fark edebiliyordu. Buna karşılık belgelerin zaman ilişkisi her bölümde açık değildi. Aynı başlık altında yer alan iki kaydın farklı yıllara ait olduğu gözden kaçabiliyordu. Bu grup da kartların üstüne tarih bilgisini eklemeye karar verdi. Tarihi bilinmeyen örnekler, biliniyormuş gibi bir sıraya yerleştirilmedi.\nGruplar taslakları karşılaştırırken yalnız hangisinin daha güzel göründüğünü sormadı. Bilginin doğruluğu, okunabilirlik, kaynakların belirtilmesi ve farklı ziyaretçilerin sergiyi takip edebilmesi için bir ölçüt listesi hazırladı. Ardından her ölçüt için somut bir örnek aradı. “Bu daha iyi.” demek yerine “Bu başlık belgeyle açıklamayı ilişkilendirmeyi kolaylaştırıyor.” gibi gerekçeli cümleler kurmaya çalıştılar.\nSon taslak, iki yaklaşımın bazı özelliklerini birleştirdi. Girişte kısa bir zaman çizelgesi, içeride ise ortak görevleri anlatan bölümler yer aldı. Bu sonuç, her konuda bütün önerileri birleştirmek gerektiği anlamına gelmiyordu. Burada karar, serginin amacı ve eldeki belgelerin özellikleri düşünülerek verilmişti. Çalışma öğrencilerin karşılaştırmanın bir kazanan seçme yarışından daha kapsamlı olabileceğini görmesini sağladı. Benzerlikler kadar ayrılıkları da göstermek, uygun bir düzen kurmalarına yardım etmişti. Açılıştan sonra gelen sorular bir deftere yazıldı. Böylece taslağın gerçekten anlaşılır olup olmadığı yalnız hazırlayanların görüşüne bırakılmadı; ziyaretçilerin deneyimleri de sonraki düzenlemeye katkı verdi.", "type": "bilgilendirici"}, "questions": [{"id": "6-2-okuma-2-1", "prompt": "“Bir Serginin İki Taslağı” metnine göre: İki taslağın ortak yanı hangisidir?", "choices": ["Aynı konu ve belge kopyalarını kullanmaları", "İkisinde de tarih bilgisinin bulunmaması", "İkisinin de yalnız fotoğraf göstermesi"], "answer": "Aynı konu ve belge kopyalarını kullanmaları", "explanation": "Giriş paragrafı iki grubun aynı belgelerle aynı konuyu işlediğini belirtir."}, {"id": "6-2-okuma-2-2", "prompt": "“Bir Serginin İki Taslağı” metnine göre: İlk taslak ile ikincisi hangi yönden ayrılır?", "choices": ["Biri bağımsızlığı, diğeri sporu anlatır", "Biri belge kullanır, diğeri hiçbir kaynak kullanmaz", "Biri zamanı, diğeri üstlenilen işleri temel alır"], "answer": "Biri zamanı, diğeri üstlenilen işleri temel alır", "explanation": "Taslakların düzenleme ilkeleri zaman sırası ve görev gruplarıdır."}, {"id": "6-2-okuma-2-3", "prompt": "“Bir Serginin İki Taslağı” metnine göre: Küçük yazı sorununa verilen çözüm nedir?", "choices": ["Ziyaretçileri sergiden çıkarmak", "Ayrıntıları ayrı kartlara taşımak", "Bütün tarihleri tahmin etmek"], "answer": "Ayrıntıları ayrı kartlara taşımak", "explanation": "İlk grup daha az olay seçip ayrıntıları ayrı kartlarda sunar."}, {"id": "6-2-okuma-2-4", "prompt": "“Bir Serginin İki Taslağı” metnine göre: Tarihi bilinmeyen örneklerin sıraya zorla konmaması neyi gözetir?", "choices": ["Bilginin belirsizliğini dürüstçe göstermeyi", "Her kartı aynı renge boyamayı", "Sergide hiç açıklama olmamasını"], "answer": "Bilginin belirsizliğini dürüstçe göstermeyi", "explanation": "Bilinmeyen tarihi uydurmamak, doğruluk ilkesine hizmet eder."}, {"id": "6-2-okuma-2-5", "prompt": "“Bir Serginin İki Taslağı” metnine göre: Okunabilirlik ve kaynak belirtme hangi başlıkta sınıflandırılabilir?", "choices": ["Belge sahiplerinin adları", "Taşıma araçları", "Değerlendirme ölçütleri"], "answer": "Değerlendirme ölçütleri", "explanation": "Gruplar bu özellikleri taslakları değerlendirecek ölçütler olarak belirler."}, {"id": "6-2-okuma-2-6", "prompt": "“Bir Serginin İki Taslağı” metnine göre: Taslak kelimesi burada ne anlama gelir?", "choices": ["Serginin satış geliri", "Henüz geliştirilebilen ilk düzenleme", "Kesinleşmiş tarihî belge"], "answer": "Henüz geliştirilebilen ilk düzenleme", "explanation": "Metin taslakların sorunlar görülerek değiştirildiğini anlatır."}, {"id": "6-2-okuma-2-7", "prompt": "“Bir Serginin İki Taslağı” metnine göre: Metnin en uygun kısa özeti hangisidir?", "choices": ["İki sergi düzeni ölçütlerle karşılaştırılır ve amaca uygun yeni düzen oluşturulur", "Bir grup hiçbir belgeye bakmadan yarışmayı kazanır", "Ziyaretçiler tarihleri ezberlemekle görevlendirilir"], "answer": "İki sergi düzeni ölçütlerle karşılaştırılır ve amaca uygun yeni düzen oluşturulur", "explanation": "Özet, iki yaklaşımın incelenmesini ve gerekçeli son taslağı kapsar."}, {"id": "6-2-okuma-2-8", "prompt": "“Bir Serginin İki Taslağı” metnine göre: Ziyaretçi sorularının saklanmasının işlevi nedir?", "choices": ["Belgelerin kaynağını gizlemek", "Taslakların değişmesini önlemek", "Düzeni sonraki çalışmalar için geliştirmek"], "answer": "Düzeni sonraki çalışmalar için geliştirmek", "explanation": "Sorular, serginin anlaşılmasına dair yeni bilgi sağlar."}]}'::jsonb),
(6,'6-2-6-2-kok',18,'{"id": "6-2-6-2-kok", "title": "Kelimenin kökünü bulma", "theme": "Bağımsızlık Yolu", "kind": "lesson", "body": {"html": "<p>Kök, bir kelimenin anlamlı en küçük temel bölümüdür. Kökü bulurken yalnız harfleri kısaltmak yetmez; kelime ile kalan bölüm arasında anlam ilişkisi de aranır. Balık kelimesindeki bal harfleri ayrı bir kelime oluştursa da iki kelime arasında bu tür bir kök ilişkisi yoktur. Kelimeler ek alırken ses değişiklikleri yaşayabilir. Buradaki örneklerde önce açık ve düzenli yapıları incele; sonucu cümlenin anlamıyla kontrol et.</p><ul><li>Kitaplık kelimesinin kökü kitaptır.</li><li>Gözlük kelimesinin kökü gözdür.</li><li>Balık kelimesinin kökü balık olarak alınır.</li></ul>", "examples": ["Kitaplık kelimesinin kökü kitaptır.", "Gözlük kelimesinin kökü gözdür.", "Balık kelimesinin kökü balık olarak alınır."], "code": "T.Y.6.3"}, "questions": [{"id": "6-2-kok-1", "prompt": "Kitaplığın kapısını kapattım. cümlesinde kitaplık kelimesinin kökü nedir?", "choices": ["Kitaplık", "Kitaplığın", "Kitap"], "answer": "Kitap", "explanation": "Kitap temel anlamı taşır; -lık yeni bir ad oluşturan ektir."}, {"id": "6-2-kok-2", "prompt": "Gözlüğünü masaya bıraktı. cümlesindeki gözlük kelimesinin kökü nedir?", "choices": ["Gözlüğü", "Göz", "Gözlük"], "answer": "Göz", "explanation": "Gözlük, göz adından türemiştir; kök gözdür."}, {"id": "6-2-kok-3", "prompt": "Başlık okunaklıydı. cümlesinde başlık kelimesinin kökü nedir?", "choices": ["Baş", "Başlık", "Başlı"], "answer": "Baş", "explanation": "Başlık kelimesi baş kökü ile anlam ilişkisini korur."}, {"id": "6-2-kok-4", "prompt": "Tuzlu yiyecekleri ayırdık. cümlesinde tuzlu kelimesinin kökü nedir?", "choices": ["Tuzlu", "Tu", "Tuz"], "answer": "Tuz", "explanation": "Tuz anlamlı köktür; -lu nitelik bildiren kelime türetir."}, {"id": "6-2-kok-5", "prompt": "Yolcu pencereden baktı. cümlesinde yolcu kelimesinin kökü nedir?", "choices": ["Yolc", "Yol", "Yolcu"], "answer": "Yol", "explanation": "Yolcu, yol köküne gelen -cu ekiyle oluşur."}, {"id": "6-2-kok-6", "prompt": "Gözlemci not aldı. cümlesinde gözlemci kelimesinin en küçük kökü nedir?", "choices": ["Göz", "Gözlem", "Gözlemci"], "answer": "Göz", "explanation": "Gözlemci kelimesinde göz temel kök, diğer bölümler türetme sürecinin parçalarıdır."}, {"id": "6-2-kok-7", "prompt": "Çiçekçi dükkânını açtı. cümlesinde çiçekçi kelimesinin kökü nedir?", "choices": ["Çiçekçi", "Çiç", "Çiçek"], "answer": "Çiçek", "explanation": "Çiçek anlamlı temel bölümdür; çiç bu anlamı taşıyan kök değildir."}, {"id": "6-2-kok-8", "prompt": "Bilgi kartı hazırlandı. cümlesinde bilgi kelimesinin kökü nedir?", "choices": ["Bi", "Bil-", "Bilgi"], "answer": "Bil-", "explanation": "Bilgi kelimesi bilmek fiiliyle anlam ilişkisi taşır; kök bil- biçimindedir."}, {"id": "6-2-kok-9", "prompt": "Sevgi sözcüğünü açıkladık. cümlesinde sevgi kelimesinin kökü nedir?", "choices": ["Sev-", "Sevgi", "Se"], "answer": "Sev-", "explanation": "Sevgi, sevmek fiilinden türetilir; sev- köktür."}, {"id": "6-2-kok-10", "prompt": "Balık sözcüğünü köküne ayırırken hangi açıklama doğrudur?", "choices": ["Kök mutlaka baldır çünkü ilk üç harfi aynıdır", "Kök yalnız ba sesidir", "Kök balıktır; bal ile anlam ilişkisi kurulmaz"], "answer": "Kök balıktır; bal ile anlam ilişkisi kurulmaz", "explanation": "Harf benzerliği yeterli değildir; balık ile bal arasında türetme ilişkisi yoktur."}]}'::jsonb),
(6,'6-2-6-2-ek',19,'{"id": "6-2-6-2-ek", "title": "Yapım ve çekim ekinin işlevi", "theme": "Bağımsızlık Yolu", "kind": "lesson", "body": {"html": "<p>Ekler kelimede farklı işler yapar. Yapım eki yeni bir kelime oluşturur; çekim eki kelimeyi cümlede sayı, durum, kişi gibi ilişkilerle kullanmayı sağlar. Kitapçı yeni bir kavramken kitaplar aynı adın çoğul biçimidir. Bazı kelimeler her iki tür eki birlikte alır. Eklerin uzun listesini ezberlemek yerine önce önceki ve sonraki anlamı karşılaştır. Yeni bir kelime mi oluştu, yoksa kelime cümlede başka bir ilişkiye mi girdi?</p><ul><li>Kitap → kitapçı: yeni kelime.</li><li>Kitap → kitaplar: çoğul biçim.</li><li>Kitapçılar: yapım ve çekim eki birlikte.</li></ul>", "examples": ["Kitap → kitapçı: yeni kelime.", "Kitap → kitaplar: çoğul biçim.", "Kitapçılar: yapım ve çekim eki birlikte."], "code": "T.Y.6.3"}, "questions": [{"id": "6-2-ek-1", "prompt": "Kitaplar kelimesindeki -lar ekinin görevi nedir?", "choices": ["Yeni bir meslek adı türetmek", "Olumsuz fiil yapmak", "Çoğulluk bildirmek"], "answer": "Çoğulluk bildirmek", "explanation": "Kitaplar aynı adın çoğul biçimidir; -lar çekim ekidir."}, {"id": "6-2-ek-2", "prompt": "Kitapçı kelimesindeki -çı ekinin görevi nedir?", "choices": ["Soru bildirmek", "Yeni bir kelime türetmek", "Yer bildirmek"], "answer": "Yeni bir kelime türetmek", "explanation": "Kitapçı yeni bir kavramdır; -çı yapım ekidir."}, {"id": "6-2-ek-3", "prompt": "Evde kelimesindeki -de nasıl bir işlev görür?", "choices": ["Bulunma ilişkisi kurar", "Yeni bir eşya adı yapar", "Karşılaştırma yapar"], "answer": "Bulunma ilişkisi kurar", "explanation": "Evde biçiminde -de kelimeyi yer ilişkisiyle kullanır; çekim ekidir."}, {"id": "6-2-ek-4", "prompt": "Gözlük kelimesindeki -lük için hangisi doğrudur?", "choices": ["Yalnız çoğulluk bildirir", "Yalnız bulunma bildirir", "Yeni bir varlık adı oluşturur"], "answer": "Yeni bir varlık adı oluşturur", "explanation": "Gözden gözlük sözü türemiştir; -lük yapım ekidir."}, {"id": "6-2-ek-5", "prompt": "Tuzsuz kelimesindeki -suz ne yapar?", "choices": ["Kişi uyumu sağlar", "Yokluk niteliği taşıyan yeni bir kelime oluşturur", "Tuz adını çoğul yapar"], "answer": "Yokluk niteliği taşıyan yeni bir kelime oluşturur", "explanation": "Tuzsuz yeni bir niteleme sözüdür; -suz yapım ekidir."}, {"id": "6-2-ek-6", "prompt": "Yollar kelimesinde hangi açıklama doğrudur?", "choices": ["Yol adı çoğul kullanılmıştır", "Yeni bir meslek adı oluşmuştur", "Fiile zaman eki gelmiştir"], "answer": "Yol adı çoğul kullanılmıştır", "explanation": "Yollar biçiminde -lar çoğulluk bildiren çekim ekidir."}, {"id": "6-2-ek-7", "prompt": "Evlerimiz kelimesindeki ekler nasıl değerlendirilir?", "choices": ["Her ikisi de yeni meslek adı yapar", "Kelime hiç ek almamıştır", "Çoğul ve iyelik ilişkisi kuran çekim ekleridir"], "answer": "Çoğul ve iyelik ilişkisi kuran çekim ekleridir", "explanation": "Evlerimizde -ler çoğul, -imiz iyelik bildirir; yeni kavram türetilmez."}, {"id": "6-2-ek-8", "prompt": "Çiçekçi kelimesi için hangi açıklama uygundur?", "choices": ["Soru anlamı oluşmuştur", "Çiçek adından yeni bir kelime türemiştir", "Çiçek yalnız çoğul olmuştur"], "answer": "Çiçek adından yeni bir kelime türemiştir", "explanation": "Çiçekçi sözü çiçekten farklı bir kavram adlandırır."}, {"id": "6-2-ek-9", "prompt": "Yolcular kelimesinde eklerin sırası nasıldır?", "choices": ["Önce yapım, sonra çoğul çekim eki", "Önce soru, sonra zaman eki", "Yalnız iki bulunma eki"], "answer": "Önce yapım, sonra çoğul çekim eki", "explanation": "Yol-cu-lar yapısında -cu türetir, -lar çoğulluk bildirir."}, {"id": "6-2-ek-10", "prompt": "Kalemim kelimesindeki -im ekinin işlevi nedir?", "choices": ["Yeni bir araç adı yapmak", "Kelimeyi olumsuz yapmak", "İyelik ilişkisi kurmak"], "answer": "İyelik ilişkisi kurmak", "explanation": "Kalemim benim kalemim anlamıyla iyelik bildirir; ek çekim ekidir."}]}'::jsonb),
(6,'6-2-6-2-karsilastirma',20,'{"id": "6-2-6-2-karsilastirma", "title": "Karşılaştırma bildiren dil yapıları", "theme": "Bağımsızlık Yolu", "kind": "lesson", "body": {"html": "<p>Karşılaştırma, iki veya daha fazla varlığın ortak ve ayrılan yönlerini belirli bir ölçüte göre anlatır. Daha, en, kadar, ise gibi yapılar bu ilişkiyi kurabilir. Karşılaştırılan şeylerin aynı özelliğini dikkate almak gerekir. Bir metnin uzunluğu ile diğerinin rengi aynı ölçüt değildir. Daha iyi gibi genel yargıları mümkünse okunaklılık veya kaynak açıklığı gibi somut bir ölçütle tamamla; gerekçenin ne olduğunu dinleyici görebilsin.</p><ul><li>Bu etiket ötekinden daha okunaklı.</li><li>İki taslak aynı ölçüde kısa.</li><li>İlk metin tarihleri, ikincisi ise görevleri öne çıkarıyor.</li></ul>", "examples": ["Bu etiket ötekinden daha okunaklı.", "İki taslak aynı ölçüde kısa.", "İlk metin tarihleri, ikincisi ise görevleri öne çıkarıyor."], "code": "T.K.6.12"}, "questions": [{"id": "6-2-karsilastirma-1", "prompt": "Hangi cümle uzunluk bakımından karşılaştırma yapar?", "choices": ["İlk metin dün yazıldı.", "İlk metin masada duruyor.", "İlk metin ikinciden daha kısa."], "answer": "İlk metin ikinciden daha kısa.", "explanation": "Daha kısa sözü iki metni aynı uzunluk ölçütüyle karşılaştırır."}, {"id": "6-2-karsilastirma-2", "prompt": "Hangi cümle eşitlik bildirir?", "choices": ["Öteki afiş en okunaklı olanı.", "İki afiş de aynı ölçüde okunaklı.", "Bu afiş daha okunaklı."], "answer": "İki afiş de aynı ölçüde okunaklı.", "explanation": "Aynı ölçüde ifadesi iki afişin niteliğini eşit düzeyde gösterir."}, {"id": "6-2-karsilastirma-3", "prompt": "İlk kayıt kısa, ikinci kayıt ise ayrıntılı. cümlesinde ise ne yapar?", "choices": ["İki kaydın farklı niteliğini belirginleştirir", "Bir tarih verir", "Bir kişiye seslenir"], "answer": "İki kaydın farklı niteliğini belirginleştirir", "explanation": "İse iki bölümün karşılaştırılarak ayrılmasına yardım eder."}, {"id": "6-2-karsilastirma-4", "prompt": "Hangi değerlendirme somut bir ölçüt içerir?", "choices": ["Bu yazı her bakımdan mükemmel.", "Bu yazı çok güzel işte.", "Bu yazı daha büyük harfleriyle uzaktan daha kolay okunuyor."], "answer": "Bu yazı daha büyük harfleriyle uzaktan daha kolay okunuyor.", "explanation": "Harf boyu ve uzaktan okunma, değerlendirilebilir bir ölçüt sunar."}, {"id": "6-2-karsilastirma-5", "prompt": "Aynı raftaki üç dosyanın en incesi budur. cümlesinde en ne bildirir?", "choices": ["Bir sebep ilişkisini", "Belirtilen grup içinde üstünlük derecesi", "Her dosyanın eşitliğini"], "answer": "Belirtilen grup içinde üstünlük derecesi", "explanation": "En incesi üç dosya içinde bir özelliğin en yüksek derecesini belirtir."}, {"id": "6-2-karsilastirma-6", "prompt": "Hangi cümle karşılaştırma içermez?", "choices": ["Sergi cuma günü açıldı.", "Bu sergi öncekinden daha kapsamlı.", "Bu sergi öteki kadar uzun sürdü."], "answer": "Sergi cuma günü açıldı.", "explanation": "Cuma günü açıldı sözü bir zaman bilgisi verir; iki unsur karşılaştırılmaz."}, {"id": "6-2-karsilastirma-7", "prompt": "Bu belge öteki kadar eski değil. cümlesindeki ilişki nedir?", "choices": ["İkisinin aynı tarihte yazıldığını kanıtlama", "İkisinin de kaybolduğunu bildirme", "Yaş bakımından eşit olmadıklarını bildirme"], "answer": "Yaş bakımından eşit olmadıklarını bildirme", "explanation": "Kadar ve değil yapısı aynı eskilik düzeyini reddeder."}, {"id": "6-2-karsilastirma-8", "prompt": "Aynı özellik üzerinden kurulan karşılaştırma hangisidir?", "choices": ["Bu kutu ötekinden daha kapı.", "Bu kutu ötekinden daha ağır.", "Bu kutu ötekinden daha salı."], "answer": "Bu kutu ötekinden daha ağır.", "explanation": "Ağırlık iki kutu için ortak ve karşılaştırılabilir bir özelliktir."}, {"id": "6-2-karsilastirma-9", "prompt": "Önceki açıklama uzundu; bu ise daha kısa. cümlesinin işlevi nedir?", "choices": ["İki açıklamayı uzunluk yönünden ayırmak", "İki olay arasında neden kurmak", "Bir koşul ileri sürmek"], "answer": "İki açıklamayı uzunluk yönünden ayırmak", "explanation": "Uzun ve kısa sözleri ortak bir ölçüte göre karşıtlık kurar."}, {"id": "6-2-karsilastirma-10", "prompt": "Daha adil bir görev dağılımı yaptık. sözünü hangi ek bilgi somutlaştırır?", "choices": ["Panonun rengini değiştirdik.", "Kapıyı açık bıraktık.", "Görev süreleri arasındaki farkı azalttık."], "answer": "Görev süreleri arasındaki farkı azalttık.", "explanation": "Süre farkının azaltılması adalet yargısının dayanağını açıklar."}]}'::jsonb),
(6,'6-2-dinleme',21,'{"id": "6-2-dinleme", "title": "İki Sergi Ekibi", "theme": "Bağımsızlık Yolu", "kind": "listening", "body": {"text": "Birinci ekip okul sergisindeki olayları tarih sırasına koydu. İkinci ekip aynı belgeleri üstlenilen görevlere göre ayırdı. İlk ekip zaman ilişkisini göstermede, ikinci ekip ortak emeği görünür kılmada güçlüydü. Ancak iki düzenin de eksikleri vardı. İlkinde yazılar küçülmüş, ikincisinde tarihler gözden kaçmıştı. Ekipler birbirini yenmek yerine amaçlarına hangi düzenin daha uygun olduğunu konuştular. Sonuçta girişe kısa bir zaman çizelgesi, iç bölüme görev başlıkları koydular. Tarihi bilinmeyen belgeleri tahminle sıralamadılar. Bu kararı açıklayan küçük bir not da eklediler."}, "questions": [{"id": "6-2-dinleme-1", "prompt": "“İki Sergi Ekibi” dinleme metnine göre: İki ekibin ortak yönü nedir?", "choices": ["Hiç kaynak kullanmamaları", "Aynı belgeleri kullanmaları", "Aynı eksiksiz düzeni seçmeleri"], "answer": "Aynı belgeleri kullanmaları", "explanation": "Metinde belgelerin aynı, düzenleme yollarının farklı olduğu anlatılır."}, {"id": "6-2-dinleme-2", "prompt": "“İki Sergi Ekibi” dinleme metnine göre: Zaman çizelgesinin güçlü yanı nedir?", "choices": ["Önce ve sonra ilişkisini göstermesi", "Her kişinin özel bilgisini açıklaması", "Tarihleri görünmez yapması"], "answer": "Önce ve sonra ilişkisini göstermesi", "explanation": "Zaman sırası olaylar arasındaki kronolojik ilişkiyi belirginleştirir."}, {"id": "6-2-dinleme-3", "prompt": "“İki Sergi Ekibi” dinleme metnine göre: Görev başlıkları neyi görünür kılar?", "choices": ["Belgelerin satış fiyatını", "Ziyaretçilerin yaşını", "Ortak emeğin farklı yönlerini"], "answer": "Ortak emeğin farklı yönlerini", "explanation": "Görev temelli düzen insanların üstlendikleri katkıları öne çıkarır."}, {"id": "6-2-dinleme-4", "prompt": "“İki Sergi Ekibi” dinleme metnine göre: Bilinmeyen tarihleri uydurmamaları nasıl yorumlanır?", "choices": ["Bütün belgeleri yanlış saydıkları", "Belirsizliği dürüstçe gösterdikleri", "Araştırmayı gereksiz buldukları"], "answer": "Belirsizliği dürüstçe gösterdikleri", "explanation": "Bilmediklerini kesin bilgiye dönüştürmeden notla açıklamışlardır."}]}'::jsonb),
(6,'6-3-soz-1',22,'{"id": "6-3-soz-1", "title": "Söz varlığı · 1", "theme": "Farklı Dünyalar", "kind": "words", "body": [{"kelime": "kültür", "anlam": "Bir topluluğun ürettiği ve aktardığı maddi ve manevi değerler bütünü", "ornek": "Kültür köşesinde farklı anlatılar vardı.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "çeşitlilik", "anlam": "Birbirinden farklı özelliklerin bir arada bulunması", "ornek": "Dil çeşitliliğini bir zenginlik olarak gördük.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "coğrafya", "anlam": "Bir yerin doğal ve beşerî özellikleri", "ornek": "Coğrafya evlerin yapısını etkileyebilir.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "iklim", "anlam": "Bir yerde uzun yıllar boyunca gözlenen hava koşullarının genel durumu", "ornek": "İklim üzerine güvenilir kaynaklar okuduk.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "mimari", "anlam": "Yapı tasarlama ve yapma sanatı", "ornek": "Mimari örnekleri malzemelerine göre karşılaştırdık.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "gelenek", "anlam": "Bir toplulukta kuşaktan kuşağa aktarılan uygulama", "ornek": "Gelenek zaman içinde değişebilir.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "gözlem", "anlam": "Bir durumu dikkatle inceleyip bilgi toplama", "ornek": "Gözlem ile tahmini ayrı sütunlara yazdım.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "önyargı", "anlam": "Yeterli bilgi edinmeden verilen peşin hüküm", "ornek": "Tek örnekten genelleme yapmak önyargıyı besleyebilir.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "merak", "anlam": "Bir şeyi öğrenme ve anlama isteği", "ornek": "Merak bizi yeni sorulara yöneltti.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "empati", "anlam": "Başkasının duygu ve düşüncesini anlamaya çalışma", "ornek": "Empati kurmak için önce dinledik.", "tip": "kelime", "cikti": "T.O.6.21"}], "questions": [{"id": "6-3-kelime-0", "prompt": "“kültür” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir topluluğun ürettiği ve aktardığı maddi ve manevi değerler bütünü", "Birbirinden farklı özelliklerin bir arada bulunması", "Bir yerin doğal ve beşerî özellikleri", "Bir yerde uzun yıllar boyunca gözlenen hava koşullarının genel durumu"], "answer": "Bir topluluğun ürettiği ve aktardığı maddi ve manevi değerler bütünü", "explanation": "Kültür köşesinde farklı anlatılar vardı."}, {"id": "6-3-kelime-1", "prompt": "“çeşitlilik” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Birbirinden farklı özelliklerin bir arada bulunması", "Bir yerin doğal ve beşerî özellikleri", "Bir yerde uzun yıllar boyunca gözlenen hava koşullarının genel durumu", "Yapı tasarlama ve yapma sanatı"], "answer": "Birbirinden farklı özelliklerin bir arada bulunması", "explanation": "Dil çeşitliliğini bir zenginlik olarak gördük."}, {"id": "6-3-kelime-2", "prompt": "“coğrafya” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir yerin doğal ve beşerî özellikleri", "Bir yerde uzun yıllar boyunca gözlenen hava koşullarının genel durumu", "Yapı tasarlama ve yapma sanatı", "Bir toplulukta kuşaktan kuşağa aktarılan uygulama"], "answer": "Bir yerin doğal ve beşerî özellikleri", "explanation": "Coğrafya evlerin yapısını etkileyebilir."}, {"id": "6-3-kelime-3", "prompt": "“iklim” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir yerde uzun yıllar boyunca gözlenen hava koşullarının genel durumu", "Yapı tasarlama ve yapma sanatı", "Bir toplulukta kuşaktan kuşağa aktarılan uygulama", "Bir durumu dikkatle inceleyip bilgi toplama"], "answer": "Bir yerde uzun yıllar boyunca gözlenen hava koşullarının genel durumu", "explanation": "İklim üzerine güvenilir kaynaklar okuduk."}, {"id": "6-3-kelime-4", "prompt": "“mimari” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Yapı tasarlama ve yapma sanatı", "Bir toplulukta kuşaktan kuşağa aktarılan uygulama", "Bir durumu dikkatle inceleyip bilgi toplama", "Yeterli bilgi edinmeden verilen peşin hüküm"], "answer": "Yapı tasarlama ve yapma sanatı", "explanation": "Mimari örnekleri malzemelerine göre karşılaştırdık."}, {"id": "6-3-kelime-5", "prompt": "“gelenek” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir toplulukta kuşaktan kuşağa aktarılan uygulama", "Bir durumu dikkatle inceleyip bilgi toplama", "Yeterli bilgi edinmeden verilen peşin hüküm", "Bir şeyi öğrenme ve anlama isteği"], "answer": "Bir toplulukta kuşaktan kuşağa aktarılan uygulama", "explanation": "Gelenek zaman içinde değişebilir."}, {"id": "6-3-kelime-6", "prompt": "“gözlem” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir durumu dikkatle inceleyip bilgi toplama", "Yeterli bilgi edinmeden verilen peşin hüküm", "Bir şeyi öğrenme ve anlama isteği", "Başkasının duygu ve düşüncesini anlamaya çalışma"], "answer": "Bir durumu dikkatle inceleyip bilgi toplama", "explanation": "Gözlem ile tahmini ayrı sütunlara yazdım."}, {"id": "6-3-kelime-7", "prompt": "“önyargı” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Yeterli bilgi edinmeden verilen peşin hüküm", "Bir şeyi öğrenme ve anlama isteği", "Başkasının duygu ve düşüncesini anlamaya çalışma", "Bir dildeki anlatımı başka bir dile aktarma"], "answer": "Yeterli bilgi edinmeden verilen peşin hüküm", "explanation": "Tek örnekten genelleme yapmak önyargıyı besleyebilir."}, {"id": "6-3-kelime-8", "prompt": "“merak” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir şeyi öğrenme ve anlama isteği", "Başkasının duygu ve düşüncesini anlamaya çalışma", "Bir dildeki anlatımı başka bir dile aktarma", "Belirli özellikleriyle ayrılan çevre veya bölge"], "answer": "Bir şeyi öğrenme ve anlama isteği", "explanation": "Merak bizi yeni sorulara yöneltti."}, {"id": "6-3-kelime-9", "prompt": "“empati” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Başkasının duygu ve düşüncesini anlamaya çalışma", "Bir dildeki anlatımı başka bir dile aktarma", "Belirli özellikleriyle ayrılan çevre veya bölge", "İnsanların yaşadıkları yeri değiştirmesi"], "answer": "Başkasının duygu ve düşüncesini anlamaya çalışma", "explanation": "Empati kurmak için önce dinledik."}]}'::jsonb),
(6,'6-3-soz-2',23,'{"id": "6-3-soz-2", "title": "Söz varlığı · 2", "theme": "Farklı Dünyalar", "kind": "words", "body": [{"kelime": "çeviri", "anlam": "Bir dildeki anlatımı başka bir dile aktarma", "ornek": "Çeviri sırasında kelimelerin bağlamına baktık.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "yöre", "anlam": "Belirli özellikleriyle ayrılan çevre veya bölge", "ornek": "Yöre halkının anlatılarını izinle dinledik.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "göç", "anlam": "İnsanların yaşadıkları yeri değiştirmesi", "ornek": "Öyküde göç sonrası yeni arkadaşlıklar anlatılıyordu.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "konuk", "anlam": "Bir yere ziyarete gelen kişi", "ornek": "Konuk öğrenciler sorularımızı yanıtladı.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "karşılaştırma", "anlam": "Benzerlik ve ayrılıkları inceleme işi", "ornek": "Karşılaştırma tablosunda iki okul vardı.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "benzerlik", "anlam": "Birbirine benzeme durumu", "ornek": "Oyunların kurallarında benzerlik bulduk.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "ayrım", "anlam": "İki şey arasındaki fark", "ornek": "Gözlemle yorum arasındaki ayrımı konuştuk.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "uyum", "anlam": "Farklı unsurların birlikte işleyebilmesi", "ornek": "Yeni kurallar uyum sağlamamızı kolaylaştırdı.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "ileti", "anlam": "Birinden başkasına iletilen haber veya düşünce", "ornek": "İletinin anlamı çeviride değişmişti.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "işaret", "anlam": "Bir anlamı göstermek için kullanılan belirti", "ornek": "İşaretin her yerde aynı anlama gelmediğini öğrendik.", "tip": "kelime", "cikti": "T.O.6.21"}], "questions": [{"id": "6-3-kelime-10", "prompt": "“çeviri” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir dildeki anlatımı başka bir dile aktarma", "Belirli özellikleriyle ayrılan çevre veya bölge", "İnsanların yaşadıkları yeri değiştirmesi", "Bir yere ziyarete gelen kişi"], "answer": "Bir dildeki anlatımı başka bir dile aktarma", "explanation": "Çeviri sırasında kelimelerin bağlamına baktık."}, {"id": "6-3-kelime-11", "prompt": "“yöre” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Belirli özellikleriyle ayrılan çevre veya bölge", "İnsanların yaşadıkları yeri değiştirmesi", "Bir yere ziyarete gelen kişi", "Benzerlik ve ayrılıkları inceleme işi"], "answer": "Belirli özellikleriyle ayrılan çevre veya bölge", "explanation": "Yöre halkının anlatılarını izinle dinledik."}, {"id": "6-3-kelime-12", "prompt": "“göç” sözcüğünün bu temadaki anlamı nedir?", "choices": ["İnsanların yaşadıkları yeri değiştirmesi", "Bir yere ziyarete gelen kişi", "Benzerlik ve ayrılıkları inceleme işi", "Birbirine benzeme durumu"], "answer": "İnsanların yaşadıkları yeri değiştirmesi", "explanation": "Öyküde göç sonrası yeni arkadaşlıklar anlatılıyordu."}, {"id": "6-3-kelime-13", "prompt": "“konuk” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir yere ziyarete gelen kişi", "Benzerlik ve ayrılıkları inceleme işi", "Birbirine benzeme durumu", "İki şey arasındaki fark"], "answer": "Bir yere ziyarete gelen kişi", "explanation": "Konuk öğrenciler sorularımızı yanıtladı."}, {"id": "6-3-kelime-14", "prompt": "“karşılaştırma” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Benzerlik ve ayrılıkları inceleme işi", "Birbirine benzeme durumu", "İki şey arasındaki fark", "Farklı unsurların birlikte işleyebilmesi"], "answer": "Benzerlik ve ayrılıkları inceleme işi", "explanation": "Karşılaştırma tablosunda iki okul vardı."}, {"id": "6-3-kelime-15", "prompt": "“benzerlik” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Birbirine benzeme durumu", "İki şey arasındaki fark", "Farklı unsurların birlikte işleyebilmesi", "Birinden başkasına iletilen haber veya düşünce"], "answer": "Birbirine benzeme durumu", "explanation": "Oyunların kurallarında benzerlik bulduk."}, {"id": "6-3-kelime-16", "prompt": "“ayrım” sözcüğünün bu temadaki anlamı nedir?", "choices": ["İki şey arasındaki fark", "Farklı unsurların birlikte işleyebilmesi", "Birinden başkasına iletilen haber veya düşünce", "Bir anlamı göstermek için kullanılan belirti"], "answer": "İki şey arasındaki fark", "explanation": "Gözlemle yorum arasındaki ayrımı konuştuk."}, {"id": "6-3-kelime-17", "prompt": "“uyum” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Farklı unsurların birlikte işleyebilmesi", "Birinden başkasına iletilen haber veya düşünce", "Bir anlamı göstermek için kullanılan belirti", "Bir olayı ele alma ve değerlendirme biçimi"], "answer": "Farklı unsurların birlikte işleyebilmesi", "explanation": "Yeni kurallar uyum sağlamamızı kolaylaştırdı."}, {"id": "6-3-kelime-18", "prompt": "“ileti” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Birinden başkasına iletilen haber veya düşünce", "Bir anlamı göstermek için kullanılan belirti", "Bir olayı ele alma ve değerlendirme biçimi", "Bir şeyde değişikliğe yol açmak"], "answer": "Birinden başkasına iletilen haber veya düşünce", "explanation": "İletinin anlamı çeviride değişmişti."}, {"id": "6-3-kelime-19", "prompt": "“işaret” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir anlamı göstermek için kullanılan belirti", "Bir olayı ele alma ve değerlendirme biçimi", "Bir şeyde değişikliğe yol açmak", "Bir şeyi yeni koşullara uygun duruma getirmek"], "answer": "Bir anlamı göstermek için kullanılan belirti", "explanation": "İşaretin her yerde aynı anlama gelmediğini öğrendik."}]}'::jsonb),
(6,'6-3-soz-3',24,'{"id": "6-3-soz-3", "title": "Söz varlığı · 3", "theme": "Farklı Dünyalar", "kind": "words", "body": [{"kelime": "bakış açısı", "anlam": "Bir olayı ele alma ve değerlendirme biçimi", "ornek": "Metni başka bir bakış açısıyla yeniden okuduk.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "etkilemek", "anlam": "Bir şeyde değişikliğe yol açmak", "ornek": "Yağış ev tasarımını etkileyebilir.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "uyarlamak", "anlam": "Bir şeyi yeni koşullara uygun duruma getirmek", "ornek": "Oyunu küçük alana uyarladık.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "araştırma", "anlam": "Bir soruya cevap bulmak için planlı bilgi arama işi", "ornek": "Araştırma sorumuzu önce daralttık.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "izlenim", "anlam": "Bir karşılaşmanın zihinde bıraktığı genel etki", "ornek": "İlk izlenim her zaman yeterli bilgi vermez.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "sunum", "anlam": "Bir konuyu dinleyiciye düzenli biçimde aktarma", "ornek": "Sunum boyunca kaynaklarımızı gösterdik.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "harita", "anlam": "Bir alanın belirli ölçü ve işaretlerle düzlemde gösterimi", "ornek": "Harita ülkelerin yerlerini bulmamıza yardım etti.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "mesafe", "anlam": "İki nokta arasındaki uzaklık", "ornek": "Mesafe arkadaşlığımıza engel olmadı.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "ortam", "anlam": "Bir olayın gerçekleştiği koşulların ve çevrenin bütünü", "ornek": "Öğrenme ortamını birlikte düzenledik.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "hoşgörü", "anlam": "Farklı görüşlere saygı gösterme tutumu", "ornek": "Hoşgörü soru sormamızı kolaylaştırdı.", "tip": "kelime", "cikti": "T.O.6.21"}], "questions": [{"id": "6-3-kelime-20", "prompt": "“bakış açısı” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir olayı ele alma ve değerlendirme biçimi", "Bir topluluğun ürettiği ve aktardığı maddi ve manevi değerler bütünü", "Birbirinden farklı özelliklerin bir arada bulunması", "Bir yerin doğal ve beşerî özellikleri"], "answer": "Bir olayı ele alma ve değerlendirme biçimi", "explanation": "Metni başka bir bakış açısıyla yeniden okuduk."}, {"id": "6-3-kelime-21", "prompt": "“etkilemek” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir şeyde değişikliğe yol açmak", "Birbirinden farklı özelliklerin bir arada bulunması", "Bir yerin doğal ve beşerî özellikleri", "Bir yerde uzun yıllar boyunca gözlenen hava koşullarının genel durumu"], "answer": "Bir şeyde değişikliğe yol açmak", "explanation": "Yağış ev tasarımını etkileyebilir."}, {"id": "6-3-kelime-22", "prompt": "“uyarlamak” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir şeyi yeni koşullara uygun duruma getirmek", "Bir yerin doğal ve beşerî özellikleri", "Bir yerde uzun yıllar boyunca gözlenen hava koşullarının genel durumu", "Yapı tasarlama ve yapma sanatı"], "answer": "Bir şeyi yeni koşullara uygun duruma getirmek", "explanation": "Oyunu küçük alana uyarladık."}, {"id": "6-3-kelime-23", "prompt": "“araştırma” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir soruya cevap bulmak için planlı bilgi arama işi", "Bir yerde uzun yıllar boyunca gözlenen hava koşullarının genel durumu", "Yapı tasarlama ve yapma sanatı", "Bir toplulukta kuşaktan kuşağa aktarılan uygulama"], "answer": "Bir soruya cevap bulmak için planlı bilgi arama işi", "explanation": "Araştırma sorumuzu önce daralttık."}, {"id": "6-3-kelime-24", "prompt": "“izlenim” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir karşılaşmanın zihinde bıraktığı genel etki", "Yapı tasarlama ve yapma sanatı", "Bir toplulukta kuşaktan kuşağa aktarılan uygulama", "Bir durumu dikkatle inceleyip bilgi toplama"], "answer": "Bir karşılaşmanın zihinde bıraktığı genel etki", "explanation": "İlk izlenim her zaman yeterli bilgi vermez."}, {"id": "6-3-kelime-25", "prompt": "“sunum” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir konuyu dinleyiciye düzenli biçimde aktarma", "Bir toplulukta kuşaktan kuşağa aktarılan uygulama", "Bir durumu dikkatle inceleyip bilgi toplama", "Yeterli bilgi edinmeden verilen peşin hüküm"], "answer": "Bir konuyu dinleyiciye düzenli biçimde aktarma", "explanation": "Sunum boyunca kaynaklarımızı gösterdik."}, {"id": "6-3-kelime-26", "prompt": "“harita” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir alanın belirli ölçü ve işaretlerle düzlemde gösterimi", "Bir durumu dikkatle inceleyip bilgi toplama", "Yeterli bilgi edinmeden verilen peşin hüküm", "Bir şeyi öğrenme ve anlama isteği"], "answer": "Bir alanın belirli ölçü ve işaretlerle düzlemde gösterimi", "explanation": "Harita ülkelerin yerlerini bulmamıza yardım etti."}, {"id": "6-3-kelime-27", "prompt": "“mesafe” sözcüğünün bu temadaki anlamı nedir?", "choices": ["İki nokta arasındaki uzaklık", "Yeterli bilgi edinmeden verilen peşin hüküm", "Bir şeyi öğrenme ve anlama isteği", "Başkasının duygu ve düşüncesini anlamaya çalışma"], "answer": "İki nokta arasındaki uzaklık", "explanation": "Mesafe arkadaşlığımıza engel olmadı."}, {"id": "6-3-kelime-28", "prompt": "“ortam” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir olayın gerçekleştiği koşulların ve çevrenin bütünü", "Bir şeyi öğrenme ve anlama isteği", "Başkasının duygu ve düşüncesini anlamaya çalışma", "Bir dildeki anlatımı başka bir dile aktarma"], "answer": "Bir olayın gerçekleştiği koşulların ve çevrenin bütünü", "explanation": "Öğrenme ortamını birlikte düzenledik."}, {"id": "6-3-kelime-29", "prompt": "“hoşgörü” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Farklı görüşlere saygı gösterme tutumu", "Başkasının duygu ve düşüncesini anlamaya çalışma", "Bir dildeki anlatımı başka bir dile aktarma", "Belirli özellikleriyle ayrılan çevre veya bölge"], "answer": "Farklı görüşlere saygı gösterme tutumu", "explanation": "Hoşgörü soru sormamızı kolaylaştırdı."}]}'::jsonb),
(6,'6-3-okuma-1',25,'{"id": "6-3-okuma-1", "title": "Aynı Oyunun Başka Kuralı", "theme": "Farklı Dünyalar", "kind": "reading", "body": {"text": "Okulun çevrim içi buluşmasında Deniz, başka bir şehirde yaşayan yaşıtı Lina ile tanıştı. İkisi de teneffüste aynı taş oyununu oynadıklarını söyleyince sevindiler. Deniz oyunun kurallarını anlatmaya başladı. Ona göre oyuncu çizgiye basarsa sırasını hemen kaybederdi. Lina ise kendi grubunda çizgiye bir kez basan oyuncuya yeniden deneme hakkı verildiğini söyledi. Deniz şaşırdı; yıllardır bildiği bir oyunun başka türlü oynanabileceğini hiç düşünmemişti.\nİlk anda Lina''nın kuralı yanlış öğrendiğini söylemek istedi. Fakat öğretmenin buluşmadan önce verdiği notu hatırladı: Önce açıklama iste, sonra karşılaştır. Deniz bu kez oyuncuların nerede oynadığını sordu. Lina, okul bahçelerindeki alanın küçük olduğunu ve oyuna yeni başlayan çok arkadaşları bulunduğunu anlattı. Yeniden deneme hakkını, herkes oyuna alışabilsin diye eklemişlerdi. Deniz''in okulunda ise oyun alanı daha genişti ve aynı grup uzun süredir birlikte oynuyordu.\nİki öğrenci kuralları yan yana yazdı. Oyunun başlama biçimi ve taşın atılacağı yer aynıydı. Sıra kaybetme koşulu farklıydı. Deniz, bütün çocukların kendi okulundaki gibi oynadığını varsaydığını fark etti. Lina da kendi kuralının her yerde daha iyi işleyeceğini savunmadı. Bir kuralın uygunluğu, oyunun amacına ve oyuncuların ihtiyaçlarına göre değişebilirdi. Bunu görmek için birinin yanlış olduğunu ilan etmeleri gerekmiyordu.\nBuluşmanın sonunda ortak bir deneme yapmaya karar verdiler. Her grup diğerinin kuralıyla bir tur oynayacak, sonra katılanların görüşlerini toplayacaktı. Öğretmen sonuçları yalnız kazananların puanlarına göre değerlendirmemelerini önerdi. Oyuna katılmak kolay mıydı, bekleme süresi uzamış mıydı, yeni başlayanlar kendilerini nasıl hissetmişti? Bu sorulara kısa notlarla cevap verdiler. Tek bir kişinin görüşünü bütün gruba mal etmediler.\nDeniz ertesi hafta yazdığı mektupta başka bir kuralı öğrenmenin kendi oyununu değersizleştirmediğini anlattı. Aksine, eskiden hiç sorgulamadığı bir alışkanlığı açıklamasını sağlamıştı. Lina''nın gönderdiği notta da benzer bir düşünce vardı: Ortak yönleri bulmak arkadaşlığı başlatmış, farklılıkları merak etmek konuşmayı sürdürmüştü. İki arkadaş artık yeni bir ayrıntıyla karşılaştıklarında hemen bir genelleme yapmak yerine nerede ve niçin kullanıldığını soruyordu. Oyun onların gözünde yalnızca taş atıp çizgiye basmamaktan oluşmuyordu. Başka birinin deneyimini dinlemek ve ortak bir karar denemek için de bir alan açıyordu. Son buluşmada hazırladıkları küçük tabloya en alta şu soruyu eklediler: “Başka hangi kural mümkün?” Bu soruya tek bir doğru cevap aramıyorlardı.", "type": "oykuleyici"}, "questions": [{"id": "6-3-okuma-1-1", "prompt": "“Aynı Oyunun Başka Kuralı” metnine göre: Deniz''in ilk yargısının değişmesini en iyi açıklayan düşünce hangisidir?", "choices": ["Bir uygulamayı değerlendirmek için koşullarını öğrenmek gerekir", "Bütün okullar aynı kuralla oynamalıdır", "Uzakta yaşayanların deneyimleri önemsizdir"], "answer": "Bir uygulamayı değerlendirmek için koşullarını öğrenmek gerekir", "explanation": "Alan ve oyuncu ihtiyaçları öğrenilince farklı kuralın gerekçesi anlaşılır."}, {"id": "6-3-okuma-1-2", "prompt": "“Aynı Oyunun Başka Kuralı” metnine göre: Metne uygun bir başlık alternatifi hangisidir?", "choices": ["Kayıp Taşın Sırrı", "Tek Bir Okulun Tarihi", "Kuralların Ardındaki İhtiyaçlar"], "answer": "Kuralların Ardındaki İhtiyaçlar", "explanation": "Öykünün odağı farklı kuralları doğuran koşulları anlamaktır."}, {"id": "6-3-okuma-1-3", "prompt": "“Aynı Oyunun Başka Kuralı” metnine göre: Metinde hangi düşünceyi geliştirme yolu belirgindir?", "choices": ["Ünlü bir kişinin sözünü kanıt gösterme", "İki uygulamayı karşılaştırma", "Sayısal deney sonuçları sunma"], "answer": "İki uygulamayı karşılaştırma", "explanation": "Aynı oyunun benzer ve farklı kuralları karşılaştırılır."}, {"id": "6-3-okuma-1-4", "prompt": "“Aynı Oyunun Başka Kuralı” metnine göre: Aksine sözü anlatıma nasıl katkıda bulunur?", "choices": ["Önceki olasılığın tersini vurgular", "Olayın kesin tarihini bildirir", "Konuşan kişinin adını verir"], "answer": "Önceki olasılığın tersini vurgular", "explanation": "Deniz''in oyununun değersizleşmesi beklentisine karşı, anlamının gelişmesi anlatılır."}, {"id": "6-3-okuma-1-5", "prompt": "“Aynı Oyunun Başka Kuralı” metnine göre: Oyun alanlarının farklı olması hangi görüşü destekler?", "choices": ["Her fark mutlaka bir hatadır", "Geniş alanlarda oyun oynanamaz", "Aynı etkinlik farklı koşullara uyarlanabilir"], "answer": "Aynı etkinlik farklı koşullara uyarlanabilir", "explanation": "İki okulun koşulları kuralların neden farklılaşabildiğini açıklar."}, {"id": "6-3-okuma-1-6", "prompt": "“Aynı Oyunun Başka Kuralı” metnine göre: Öğretmenin yalnız puana bakılmamasını istemesi ne sağlar?", "choices": ["Kazananların görüşünün tek ölçüt olmasını", "Katılım deneyiminin de değerlendirilmesini", "Oyunda hiç kural kalmamasını"], "answer": "Katılım deneyiminin de değerlendirilmesini", "explanation": "Bekleme süresi ve yeni başlayanların duyguları da ele alınır."}, {"id": "6-3-okuma-1-7", "prompt": "“Aynı Oyunun Başka Kuralı” metnine göre: Metnin temel iletisi hangisidir?", "choices": ["Farklılıkları anlamak için merakla soru sormak gerekir", "Arkadaşlık için bütün alışkanlıklar aynı olmalıdır", "İlk izlenim her zaman kesin bilgidir"], "answer": "Farklılıkları anlamak için merakla soru sormak gerekir", "explanation": "Öğrenciler yargı yerine açıklama ve karşılaştırmayla birbirlerini anlar."}, {"id": "6-3-okuma-1-8", "prompt": "“Aynı Oyunun Başka Kuralı” metnine göre: Başka hangi kural mümkün sorusu okuyucuyu neye yöneltir?", "choices": ["Oyunu tamamen bırakmaya", "Her şeyi ezberlemeye", "Alternatifleri düşünmeye"], "answer": "Alternatifleri düşünmeye", "explanation": "Son soru tek çözüm dayatmadan başka düzenlemelere alan açar."}]}'::jsonb),
(6,'6-3-okuma-2',26,'{"id": "6-3-okuma-2", "title": "Evleri Anlatırken", "theme": "Farklı Dünyalar", "kind": "reading", "body": {"text": "Bir evin fotoğrafına bakarak o evde yaşayanların bütün alışkanlıklarını öğrenebilir miyiz? Fotoğraf, yapının rengi ve biçimi hakkında bazı bilgiler verir. Fakat ailelerin günlük hayatını, tercihlerini ve düşüncelerini bütünüyle göstermez. Bu yüzden farklı yerlerdeki evleri araştırırken gördüğümüz özelliklerle yaptığımız yorumları ayırmak yararlıdır. “Çatısı eğimli.” demek ile “Burada yaşayan herkes aynı hayatı sürer.” demek aynı türden bir bilgi değildir.\nEvlerin tasarımını etkileyebilecek pek çok unsur vardır. Yağış, sıcaklık, elde bulunan malzeme, ekonomik imkânlar ve zaman içinde değişen ihtiyaçlar bunlardan bazılarıdır. Örneğin iki yapının aynı malzemeyi kullanması, bütün özelliklerinin aynı olduğu anlamına gelmez. Bir yapı sonradan onarılmış, diğeri yeni yapılmış olabilir. Bir fotoğrafın çekildiği tarih bilinmiyorsa o görüntünün güncel durumu yansıttığı da varsayılamaz. Araştırmacı, açıklamasının sınırlarını görünür tutmalıdır.\nBir karşılaştırma tablosu hazırlayan öğrenciler, sütunları önce ülke adlarına göre düzenleyebilir. Ancak tek bir evi bir ülkenin bütün evlerinin örneği gibi sunmamak gerekir. Daha dikkatli bir başlık, yapının bulunduğu yerle birlikte incelenen örneğin adını da belirtir. Böylece okuyucu, önündeki bilgilerin sınırlı sayıda örnekten geldiğini anlar. Başlıkta kullanılan küçük bir ayrıntı, büyük bir genellemeyi önleyebilir.\nAraştırmada birden fazla kaynak türüne yer vermek de yararlıdır. Yapının ölçülerini gösteren çizim, dış görünüşünü anlatan fotoğraf ve kullanımını açıklayan görüşme farklı sorulara cevap verir. Görüşme yapılacaksa kişinin paylaşmak istediği bilgilerle yetinilir. Özel adres, aile bilgisi veya görüntü paylaşmaya zorlamak, öğrenme amacı için gerekli değildir. Örnekler açık kaynaklı veya izinli materyallerden seçilebilir.\nÇalışmanın sonunda öğrenciler yalnız benzer ve farklı özellikleri sıralamaz. Hangi açıklamanın gözleme, hangisinin kaynak bilgisine, hangisinin henüz sınanmamış tahmine dayandığını da işaretler. Bu yaklaşım, başka kültürleri tek bir görüntüyle tanımlama alışkanlığını azaltabilir. Evler araştırmanın başlangıç noktasıdır; insanların çeşitliliği ise bir tabloya bütünüyle sığmaz. İyi bir sunum bu sınırı saklamak yerine okura gösterir. Son sayfaya yeni sorular eklemek çalışmayı zayıflatmaz. Örneğin “Aynı sokaktaki başka yapılar nasıl?” sorusu araştırmayı genişletebilir. Öğrenciler böylece öğrendiklerini kesin ve değişmez bir son söz olarak sunmak yerine, dayanağı bilinen ve geliştirilebilen bir açıklama kurmayı öğrenir. Birbirlerinin tablolarını incelerken de eksikleri küçümsemek yerine hangi kaynağın yararlı olabileceğini önerebilirler.", "type": "bilgilendirici"}, "questions": [{"id": "6-3-okuma-2-1", "prompt": "“Evleri Anlatırken” metnine göre: İlk paragraftaki soru hangi işlevi görür?", "choices": ["Bir evin satış fiyatını açıklar", "Yazarın kesin cevabını gizler", "Okuyucuyu bilginin sınırlarını düşünmeye çağırır"], "answer": "Okuyucuyu bilginin sınırlarını düşünmeye çağırır", "explanation": "Fotoğrafın neyi gösterip neyi gösteremediği üzerine düşünme başlatılır."}, {"id": "6-3-okuma-2-2", "prompt": "“Evleri Anlatırken” metnine göre: Metinde kullanılan düşünceyi geliştirme yolu hangisidir?", "choices": ["Kesin nüfus sayılarıyla kanıtlama", "Eğimli çatı cümlesiyle örnekleme", "Yazar adı vererek tanık gösterme"], "answer": "Eğimli çatı cümlesiyle örnekleme", "explanation": "Somut gözlem cümlesi, gözlem ile genelleme ayrımına örnek olur."}, {"id": "6-3-okuma-2-3", "prompt": "“Evleri Anlatırken” metnine göre: Tek bir evin bütün ülkeyi temsil etmesi neden sorunludur?", "choices": ["Sınırlı örnekten geniş genelleme yapılmış olur", "Ev fotoğrafları hiçbir bilgi vermez", "Bütün ülkelerde evler bütünüyle aynıdır"], "answer": "Sınırlı örnekten geniş genelleme yapılmış olur", "explanation": "Metin örnek sayısının ve kapsamın açıkça belirtilmesini önerir."}, {"id": "6-3-okuma-2-4", "prompt": "“Evleri Anlatırken” metnine göre: Bir kaynakta fotoğrafın tarihinin bulunmaması neyi sınırlar?", "choices": ["Fotoğrafın renklerini görmeyi", "Yapının bir dış yüzünün bulunduğunu anlamayı", "Görüntünün güncelliğini değerlendirmeyi"], "answer": "Görüntünün güncelliğini değerlendirmeyi", "explanation": "Tarih bilinmeden bugünkü görünüşe ilişkin kesin yargı kurulamaz."}, {"id": "6-3-okuma-2-5", "prompt": "“Evleri Anlatırken” metnine göre: Çizim, fotoğraf ve görüşmenin birlikte kullanılması nasıl yorumlanır?", "choices": ["Görüşmeler ölçü çizimlerinin aynısıdır", "Farklı sorular için farklı kaynaklara başvurulur", "Aynı bilgi gereksizce çoğaltılır"], "answer": "Farklı sorular için farklı kaynaklara başvurulur", "explanation": "Kaynak türleri ölçü, görünüş ve kullanım gibi farklı boyutlara cevap verir."}, {"id": "6-3-okuma-2-6", "prompt": "“Evleri Anlatırken” metnine göre: Son sayfaya yeni sorular eklemenin anlamı nedir?", "choices": ["Bilginin geliştirilebilir olduğunu kabul etmek", "Çalışmanın tamamen değersiz olduğunu söylemek", "İlk kaynakları gizlemeye çalışmak"], "answer": "Bilginin geliştirilebilir olduğunu kabul etmek", "explanation": "Metin yeni soruların araştırmayı genişletebileceğini vurgular."}, {"id": "6-3-okuma-2-7", "prompt": "“Evleri Anlatırken” metnine göre: Metnin vermek istediği temel düşünce hangisidir?", "choices": ["Bir fotoğraf bir toplum hakkında her şeyi söyler", "Araştırmada yalnız ilk bulunan kaynak kullanılmalıdır", "Kültürel örnekleri kapsamı ve dayanağı açık biçimde incelemek gerekir"], "answer": "Kültürel örnekleri kapsamı ve dayanağı açık biçimde incelemek gerekir", "explanation": "Metnin bütün bölümleri sınırları bilinen ve doğrulanan açıklamayı destekler."}, {"id": "6-3-okuma-2-8", "prompt": "“Evleri Anlatırken” metnine göre: Aşağıdaki önerilerden hangisi yazarın yaklaşımına uygundur?", "choices": ["Görüşülen kişiden özel adresini mutlaka istemek", "Tablodaki tahminleri gözlemlerden ayrı işaretlemek", "Bilinmeyen bilgileri kesinmiş gibi tamamlamak"], "answer": "Tablodaki tahminleri gözlemlerden ayrı işaretlemek", "explanation": "Son bölümde gözlem, kaynak bilgisi ve tahmin ayrımı açıkça önerilir."}]}'::jsonb),
(6,'6-3-6-3-iki-nokta',27,'{"id": "6-3-6-3-iki-nokta", "title": "Açıklama, örnek ve konuşmada iki nokta", "theme": "Farklı Dünyalar", "kind": "lesson", "body": {"html": "<p>İki nokta, ardından örnek veya açıklama verileceğini gösterebilir. Karşılıklı konuşmalarda konuşan kişinin adından sonra da kullanılır. Her listeden önce otomatik olarak iki nokta gelmez; önceki sözün sonraki bölümü tanıtıp tanıtmadığına bakılır. Tam cümle biçimindeki açıklama büyük harfle, yalnız örnekler sıralanıyorsa özel ad olmayan ilk örnek küçük harfle başlayabilir. Noktalama seçiminde yalnız ses duraklamasını değil, anlam ilişkisini gözet.</p><ul><li>Üç malzeme seçtik: kâğıt, ip, boya.</li><li>Sonuç açıktı: Plan değişmeliydi.</li><li>Deniz: Hangi oyunu oynuyorsunuz?</li></ul>", "examples": ["Üç malzeme seçtik: kâğıt, ip, boya.", "Sonuç açıktı: Plan değişmeliydi.", "Deniz: Hangi oyunu oynuyorsunuz?"], "code": "T.Y.6.21"}, "questions": [{"id": "6-3-iki-nokta-1", "prompt": "Örnek vermek için uygun işaret hangisidir? İki araç kullandık ... makas ve cetvel.", "choices": ["Soru işareti", "Kesme işareti", "İki nokta"], "answer": "İki nokta", "explanation": "Sonraki sözler önceki cümlede tanıtılan araçlara örnek verir."}, {"id": "6-3-iki-nokta-2", "prompt": "Konuşmacı adından sonra hangi işaret kullanılır? Lina ... Yeniden deneyelim.", "choices": ["Kesme işareti", "İki nokta", "Eğik çizgi"], "answer": "İki nokta", "explanation": "Karşılıklı konuşmada kişi adından sonra iki nokta gelir."}, {"id": "6-3-iki-nokta-3", "prompt": "Açıklama ilişkisi hangi cümlede iki noktayla doğru gösterilmiştir?", "choices": ["Kararımız açıktı: Birlikte deneyecektik.", "Kararımız: açıktı birlikte deneyecektik.", "Kararımız açıktı birlikte: deneyecektik."], "answer": "Kararımız açıktı: Birlikte deneyecektik.", "explanation": "İkinci cümle kararın ne olduğunu açıkladığı için iki nokta ilk yargıdan sonra gelir."}, {"id": "6-3-iki-nokta-4", "prompt": "Örneklerin doğru gösterildiği cümle hangisidir?", "choices": ["Bazı: oyunlar seçildi seksek saklambaç körebe.", "Bazı oyunlar: seçildi seksek saklambaç körebe.", "Bazı oyunlar seçildi: seksek, saklambaç, körebe."], "answer": "Bazı oyunlar seçildi: seksek, saklambaç, körebe.", "explanation": "İlk cümle tamamlandıktan sonra örnek listesi iki noktayla tanıtılır."}, {"id": "6-3-iki-nokta-5", "prompt": "Metinde iki noktadan sonra tam cümle başlıyorsa ilk harf nasıl olur?", "choices": ["Mutlaka sayı olur", "Büyük yazılır", "Her durumda küçük yazılır"], "answer": "Büyük yazılır", "explanation": "Tam cümle niteliğindeki açıklama büyük harfle başlar."}, {"id": "6-3-iki-nokta-6", "prompt": "Kültür köşesinde şunlar vardı: harita, fotoğraf ve kartlar. cümlesinde iki noktanın görevi nedir?", "choices": ["Sonrasında örnekleri göstermek", "Bir ek ayırmak", "İki dizeyi ayırmak"], "answer": "Sonrasında örnekleri göstermek", "explanation": "Şunlar sözü ardından gelecek örnek listesini hazırlar."}, {"id": "6-3-iki-nokta-7", "prompt": "Sebebi belliydi: Kaynaklar kontrol edilmemişti. cümlesindeki iki noktanın işlevi nedir?", "choices": ["Alıntının sahibine ek getirmek", "Bir kelimeyi bölmek", "Önceki yargının açıklamasını başlatmak"], "answer": "Önceki yargının açıklamasını başlatmak", "explanation": "İkinci cümle sebebin ne olduğunu açıklar."}, {"id": "6-3-iki-nokta-8", "prompt": "Doğru konuşma satırı hangisidir?", "choices": ["Ada/ Önce soralım.", "Ada: Önce soralım.", "Ada; Önce soralım."], "answer": "Ada: Önce soralım.", "explanation": "Konuşan kişinin adından sonra iki nokta kullanılır."}, {"id": "6-3-iki-nokta-9", "prompt": "Hangi cümlede iki nokta açıklamadan önce doğru yerde kullanılmıştır?", "choices": ["Bir ihtiyacımız vardı: Daha geniş bir alan.", "Bir: ihtiyacımız vardı daha geniş bir alan.", "Bir ihtiyacımız: vardı daha geniş bir alan."], "answer": "Bir ihtiyacımız vardı: Daha geniş bir alan.", "explanation": "İhtiyacın ne olduğu, tamamlanan ilk yargıdan sonra açıklanır."}, {"id": "6-3-iki-nokta-10", "prompt": "Yanlış yerleştirilmiş iki nokta hangi sorunu doğurur?", "choices": ["Her cümleyi otomatik olarak soru yapar", "Bütün özel adları küçük harfe çevirir", "Birlikte okunması gereken sözleri gereksiz yere ayırabilir"], "answer": "Birlikte okunması gereken sözleri gereksiz yere ayırabilir", "explanation": "İki nokta anlam ilişkisini göstermeli, söz gruplarını keyfî biçimde parçalamamalıdır."}]}'::jsonb),
(6,'6-3-6-3-zitlik',28,'{"id": "6-3-6-3-zitlik", "title": "Zıtlık bildiren sözler", "theme": "Farklı Dünyalar", "kind": "lesson", "body": {"html": "<p>Zıtlık bildiren ama, fakat, ancak, hâlbuki ve aksine gibi sözler iki düşünce arasında beklenmeyen bir ayrılık kurabilir. Bir sözün görevi her kullanımında aynı değildir. Ancak bazen karşıtlık, bazen yalnız anlamı taşır. Anlatımdaki ilişkiyi belirlemek için kelimeyi tek başına etiketlemek yerine iki yargıyı birlikte oku. Karşıtlık kurarken hangi düşüncenin sınırlandığını veya değiştiğini açıkça göster.</p><ul><li>Evler benziyor ama malzemeleri farklı.</li><li>Uzakta yaşıyor; buna rağmen düzenli görüşüyoruz.</li><li>Beklediğim gibi değildi; aksine çok sakindi.</li></ul>", "examples": ["Evler benziyor ama malzemeleri farklı.", "Uzakta yaşıyor; buna rağmen düzenli görüşüyoruz.", "Beklediğim gibi değildi; aksine çok sakindi."], "code": "T.Y.6.1"}, "questions": [{"id": "6-3-zitlik-1", "prompt": "Yağmur vardı ama gezi sürdü. cümlesinde ama ne bildirir?", "choices": ["Bir eşyanın adını", "Kesin bir neden", "Beklentiye karşıt bir sonuç"], "answer": "Beklentiye karşıt bir sonuç", "explanation": "Yağmurun geziyi durdurma beklentisine karşı sürmesi anlatılır."}, {"id": "6-3-zitlik-2", "prompt": "Aksine sözü hangi ilişkide uygundur?", "choices": ["Kapıyı açtı; aksine kapı açıldı.", "Sessiz sanmıştım; aksine oldukça hareketliydi.", "Saat erkendi; aksine sabah sekizdi."], "answer": "Sessiz sanmıştım; aksine oldukça hareketliydi.", "explanation": "Sessiz ve hareketli nitelikleri önceki düşüncenin tersine işaret eder."}, {"id": "6-3-zitlik-3", "prompt": "Hangi cümlede ancak karşıtlık bildirir?", "choices": ["İstiyordum ancak zamanım yoktu.", "Ancak iki kart kaldı.", "Bu kutuyu ancak üç kişi taşır."], "answer": "İstiyordum ancak zamanım yoktu.", "explanation": "İstemeye rağmen zamanın olmaması düşünceler arasında karşıtlık kurar."}, {"id": "6-3-zitlik-4", "prompt": "Hangi cümlede hâlbuki önceki yargıyla çelişen bir durum getirir?", "choices": ["Sabah oldu; hâlbuki güneş doğdu.", "Kapı açıldı; hâlbuki giriş mümkün oldu.", "Herkes aynı sanıyordu; hâlbuki kurallar değişmişti."], "answer": "Herkes aynı sanıyordu; hâlbuki kurallar değişmişti.", "explanation": "Kuralların değişmesi, aynı oldukları düşüncesine karşıtlık oluşturur."}, {"id": "6-3-zitlik-5", "prompt": "Benzer evlerdi ... kullanım amaçları farklıydı. boşluğuna hangisi uygundur?", "choices": ["Bu yüzden", "Fakat", "Çünkü"], "answer": "Fakat", "explanation": "Benzer görünüş ile farklı kullanım arasında karşıtlık kurulmaktadır."}, {"id": "6-3-zitlik-6", "prompt": "Hangi cümlede karşıtlık yoktur?", "choices": ["Yağdığı için içeri girdik.", "Yağmur yağdı ama dışarıda kaldık.", "Soğuktu fakat üşümedim."], "answer": "Yağdığı için içeri girdik.", "explanation": "İlk cümle neden-sonuç bildirir; diğerlerinde beklentiye karşıtlık vardır."}, {"id": "6-3-zitlik-7", "prompt": "Tam tersine ifadesi neyi vurgular?", "choices": ["İki olayın aynı zamanını", "Bir kelimenin kökünü", "Önceki düşüncenin karşı yönünü"], "answer": "Önceki düşüncenin karşı yönünü", "explanation": "Tam tersine önceki yargının aksi yöndeki düşünceyi başlatır."}, {"id": "6-3-zitlik-8", "prompt": "Uzakta olmasına rağmen buluşmaya geldi. cümlesinin anlamı hangisidir?", "choices": ["Buluşmanın zamanı belirtilmemiştir diye cümle anlamsızdır", "Uzaklık beklentisine karşı katılım gerçekleşmiştir", "Uzaklık katılımın tek nedenidir"], "answer": "Uzaklık beklentisine karşı katılım gerçekleşmiştir", "explanation": "Rağmen sözü engelleyici olabilecek duruma karşı sonucu gösterir."}, {"id": "6-3-zitlik-9", "prompt": "Zıtlık ilişkisini koruyan yeniden yazım hangisidir? Kısaydı fakat açıklayıcıydı.", "choices": ["Kısa olmasına rağmen açıklayıcıydı.", "Kısa olduğu için açıklayıcıydı.", "Kısa olursa açıklayıcı olurdu."], "answer": "Kısa olmasına rağmen açıklayıcıydı.", "explanation": "Rağmen yapısı kısa olma ile açıklayıcı olma arasındaki karşıt beklentiyi korur."}, {"id": "6-3-zitlik-10", "prompt": "Hem ... hem de yapısı her kullanımda zıtlık kurar mı?", "choices": ["Evet; cümleye bakmak gerekmez", "Hayır; hiçbir anlam ilişkisi kuramaz", "Hayır; çoğu kullanımda birlikte bulunmayı da bildirebilir"], "answer": "Hayır; çoğu kullanımda birlikte bulunmayı da bildirebilir", "explanation": "İşlev bağlama bağlıdır; bir söz kalıbı otomatik olarak tek etiketle değerlendirilmez."}]}'::jsonb),
(6,'6-3-6-3-sebep',29,'{"id": "6-3-6-3-sebep", "title": "Sebep bildiren dil yapıları", "theme": "Farklı Dünyalar", "kind": "lesson", "body": {"html": "<p>Sebep bildiren yapılar bir olayın niçin gerçekleştiğini açıklar. Çünkü, bu nedenle, -dığı için ve yüzünden gibi ifadeler bu ilişkiyi kurabilir. Amaç ise henüz ulaşılmak istenen sonuçtur; her için sözü aynı işlevde değildir. Yağmur yağdığı için beklemek sebep, ıslanmamak için beklemek amaç bildirir. Yazarken ilişkinin yönünü kontrol et; gerekçeyi sonuçla karıştırma.</p><ul><li>Yol kapalı olduğu için bekledik.</li><li>Kaynak eksikti; bu nedenle yeniden araştırdık.</li><li>Yağmur yüzünden oyun ertelendi.</li></ul>", "examples": ["Yol kapalı olduğu için bekledik.", "Kaynak eksikti; bu nedenle yeniden araştırdık.", "Yağmur yüzünden oyun ertelendi."], "code": "T.Y.6.1"}, "questions": [{"id": "6-3-sebep-1", "prompt": "Cümlede neden hangisidir? Yol kapandığı için geç kaldık.", "choices": ["Yolun kapanması", "Geç kalmamız", "Yarın yola çıkmamız"], "answer": "Yolun kapanması", "explanation": "Geç kalma sonucunu doğuran durum yolun kapanmasıdır."}, {"id": "6-3-sebep-2", "prompt": "Sebep bildiren bağlaç hangisidir?", "choices": ["Fakat", "Ya da", "Çünkü"], "answer": "Çünkü", "explanation": "Çünkü ardından önceki yargının gerekçesini getirir."}, {"id": "6-3-sebep-3", "prompt": "Kaynak eksikti; bu nedenle araştırma sürdü. cümlesinde sonuç nedir?", "choices": ["Kaynağın renkli olması", "Araştırmanın sürmesi", "Kaynağın eksik olması"], "answer": "Araştırmanın sürmesi", "explanation": "Bu nedenle sonrasındaki yargı, önceki durumun sonucudur."}, {"id": "6-3-sebep-4", "prompt": "Hangi cümle sebep ilişkisi kurar?", "choices": ["Çatı aktığı için sınıf değiştirildi.", "Sınıfı görmek için geldik.", "Yeni sınıf daha genişti."], "answer": "Çatı aktığı için sınıf değiştirildi.", "explanation": "Akma durumu, sınıf değiştirmenin gerçekleşmiş nedenidir."}, {"id": "6-3-sebep-5", "prompt": "Yüzünden sözü hangi cümlede neden bildirir?", "choices": ["Kapının yüzünü boyadık.", "Yüzünden bir gülümseme geçti.", "Gürültü yüzünden duyamadık."], "answer": "Gürültü yüzünden duyamadık.", "explanation": "Gürültü, duyamama sonucunun nedeni olarak gösterilir."}, {"id": "6-3-sebep-6", "prompt": "Eksik bilgi karar vermemizi zorlaştırdı. cümlesinin sebep ilişkili eş değeri hangisidir?", "choices": ["Karar verirsek bilgi eksilir.", "Bilgi eksik olduğu için karar vermekte zorlandık.", "Karar vermek için bilgiyi eksilttik."], "answer": "Bilgi eksik olduğu için karar vermekte zorlandık.", "explanation": "İlk seçenekte aynı neden ve sonuç ilişkisi korunur."}, {"id": "6-3-sebep-7", "prompt": "Hangi ifade sonuçtan sonra gerekçeyi açıklar?", "choices": ["Bekledik çünkü kapı kilitliydi.", "Kapı kilitliydi ama beklemedik.", "Beklersek kapı açılır."], "answer": "Bekledik çünkü kapı kilitliydi.", "explanation": "Çünkü sözü bekleme kararının sebebini ardından verir."}, {"id": "6-3-sebep-8", "prompt": "İçeri girdik ... yağmur başlamıştı. boşluğuna hangisi uygundur?", "choices": ["Rağmen", "Veya", "Çünkü"], "answer": "Çünkü", "explanation": "İkinci yargı içeri girmenin gerekçesini açıkladığı için çünkü uygundur."}, {"id": "6-3-sebep-9", "prompt": "Soğuk nedeniyle etkinlik ertelendi. cümlesinde nedeniyle nasıl işlev görür?", "choices": ["Konuşmacının adını gösterir", "Sebep ilişkisi kurar", "Karşılaştırma derecesi bildirir"], "answer": "Sebep ilişkisi kurar", "explanation": "Soğuk, ertelemenin gerekçesi olarak belirtilmiştir."}, {"id": "6-3-sebep-10", "prompt": "Sebep ile amacı doğru ayıran açıklama hangisidir?", "choices": ["Yorgun olduğu için durdu neden; dinlenmek için durdu amaç bildirir", "İki cümle de her durumda yalnız zaman bildirir", "İlk cümle amaç, ikincisi geçmişteki neden bildirir"], "answer": "Yorgun olduğu için durdu neden; dinlenmek için durdu amaç bildirir", "explanation": "Yorgunluk var olan neden, dinlenmek ise hedeflenen sonuçtur."}]}'::jsonb),
(6,'6-3-dinleme',30,'{"id": "6-3-dinleme", "title": "Ortak Oyunun Notları", "theme": "Farklı Dünyalar", "kind": "listening", "body": {"text": "Çevrim içi buluşmada iki okul aynı oyunun farklı kurallarını anlattı. Birinde yeni başlayanlara ikinci deneme hakkı tanınıyor, diğerinde oyuncu ilk hatada sırasını bırakıyordu. Öğrenciler bir kuralı yanlış ilan etmek yerine gerekçelerini sordu. Küçük bahçe ve yeni oyuncular, ikinci deneme hakkının neden tercih edildiğini açıklıyordu. İki grup, diğer kuralı da deneyip görüş toplamaya karar verdi. Yalnız kazananların değil, bekleyenlerin ve yeni başlayanların da deneyimleri kaydedilecekti. Bu seçim, değerlendirmede katılımın da önemli görüldüğünü düşündürüyordu. Bir öğrencinin sözü bütün grubun değişmez fikri sayılmayacaktı."}, "questions": [{"id": "6-3-dinleme-1", "prompt": "“Ortak Oyunun Notları” dinleme metnine göre: Kurallar hangi yönden farklıdır?", "choices": ["İlk hatadan sonra verilen hak bakımından", "Oyunun her iki yerde de yasak olması bakımından", "Her iki okulun aynı genişlikte olması bakımından"], "answer": "İlk hatadan sonra verilen hak bakımından", "explanation": "Bir grupta ikinci deneme vardır; diğerinde sıra bırakılır."}, {"id": "6-3-dinleme-2", "prompt": "“Ortak Oyunun Notları” dinleme metnine göre: Katılımın önemsendiği hangi seçimden çıkarılır?", "choices": ["Yalnız kazananların puanının yazılmasından", "Hiç görüş alınmamasından", "Yeni başlayan ve bekleyenlerin görüşlerinin de alınmasından"], "answer": "Yeni başlayan ve bekleyenlerin görüşlerinin de alınmasından", "explanation": "Farklı katılımcıların deneyimlerinin kaydı kapsamlı değerlendirmeye işaret eder."}, {"id": "6-3-dinleme-3", "prompt": "“Ortak Oyunun Notları” dinleme metnine göre: Tek kişinin sözünün herkese mal edilmemesi neyi gözetir?", "choices": ["Kuralların hiç değişmeyeceğini", "Grup içindeki farklı görüşleri", "Her okulun aynı olduğunu"], "answer": "Grup içindeki farklı görüşleri", "explanation": "Bir bireyin görüşü grubun bütün üyelerinin görüşünü kanıtlamaz."}, {"id": "6-3-dinleme-4", "prompt": "“Ortak Oyunun Notları” dinleme metnine göre: Dinlenenin özünü koruyan özet hangisidir?", "choices": ["İki grup farklı kuralları gerekçeleriyle inceleyip denemeyi planlar", "Bir okul diğer bütün oyunları yasaklar", "Öğrenciler yalnız kazananın sözünü dinler"], "answer": "İki grup farklı kuralları gerekçeleriyle inceleyip denemeyi planlar", "explanation": "Özet, farkları anlama ve farklı katılımcılarla deneme planını kapsar."}]}'::jsonb),
(6,'6-4-soz-1',31,'{"id": "6-4-soz-1", "title": "Söz varlığı · 1", "theme": "İletişim ve Sosyal İlişkiler", "kind": "words", "body": [{"kelime": "iletişim", "anlam": "Duygu ve düşüncelerin karşılıklı aktarılması", "ornek": "İletişim için ortak bir zaman belirledik.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "anlaşmazlık", "anlam": "Bir konuda farklı düşünüp uyuşamama durumu", "ornek": "Anlaşmazlığı konuşarak çözmeye çalıştık.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "uzlaşmak", "anlam": "Farklı istekleri ortak bir çözümde buluşturmak", "ornek": "İki grup çalışma saatinde uzlaştı.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "dinleyici", "anlam": "Bir konuşmayı veya sesi dinleyen kişi", "ornek": "Dinleyici soru sormak için sırasını bekledi.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "konuşmacı", "anlam": "Bir topluluğa konuşan kişi", "ornek": "Konuşmacı son cümlesini yeniden açıkladı.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "sıra", "anlam": "Bir işte veya dizilişte izlenecek yer", "ornek": "Söz sırası gelince önerimi sundum.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "üslup", "anlam": "Bir anlatımın kendine özgü söyleyiş biçimi", "ornek": "İletinin üslubu daha nazik hâle getirildi.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "açıklık", "anlam": "Bir anlatımın kolay anlaşılır olma özelliği", "ornek": "Duyurunun açıklığını kontrol ettik.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "nezaket", "anlam": "Başkalarını gözeten incelikli davranış", "ornek": "Nezaket görüş ayrılığında da sürmelidir.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "eleştiri", "anlam": "Bir işin güçlü ve geliştirilebilir yanlarını gerekçeleriyle inceleme", "ornek": "Eleştiri kişiliğe değil çalışmaya yönelikti.", "tip": "kelime", "cikti": "T.O.6.21"}], "questions": [{"id": "6-4-kelime-0", "prompt": "“iletişim” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Duygu ve düşüncelerin karşılıklı aktarılması", "Bir konuda farklı düşünüp uyuşamama durumu", "Farklı istekleri ortak bir çözümde buluşturmak", "Bir konuşmayı veya sesi dinleyen kişi"], "answer": "Duygu ve düşüncelerin karşılıklı aktarılması", "explanation": "İletişim için ortak bir zaman belirledik."}, {"id": "6-4-kelime-1", "prompt": "“anlaşmazlık” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir konuda farklı düşünüp uyuşamama durumu", "Farklı istekleri ortak bir çözümde buluşturmak", "Bir konuşmayı veya sesi dinleyen kişi", "Bir topluluğa konuşan kişi"], "answer": "Bir konuda farklı düşünüp uyuşamama durumu", "explanation": "Anlaşmazlığı konuşarak çözmeye çalıştık."}, {"id": "6-4-kelime-2", "prompt": "“uzlaşmak” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Farklı istekleri ortak bir çözümde buluşturmak", "Bir konuşmayı veya sesi dinleyen kişi", "Bir topluluğa konuşan kişi", "Bir işte veya dizilişte izlenecek yer"], "answer": "Farklı istekleri ortak bir çözümde buluşturmak", "explanation": "İki grup çalışma saatinde uzlaştı."}, {"id": "6-4-kelime-3", "prompt": "“dinleyici” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir konuşmayı veya sesi dinleyen kişi", "Bir topluluğa konuşan kişi", "Bir işte veya dizilişte izlenecek yer", "Bir anlatımın kendine özgü söyleyiş biçimi"], "answer": "Bir konuşmayı veya sesi dinleyen kişi", "explanation": "Dinleyici soru sormak için sırasını bekledi."}, {"id": "6-4-kelime-4", "prompt": "“konuşmacı” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir topluluğa konuşan kişi", "Bir işte veya dizilişte izlenecek yer", "Bir anlatımın kendine özgü söyleyiş biçimi", "Bir anlatımın kolay anlaşılır olma özelliği"], "answer": "Bir topluluğa konuşan kişi", "explanation": "Konuşmacı son cümlesini yeniden açıkladı."}, {"id": "6-4-kelime-5", "prompt": "“sıra” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir işte veya dizilişte izlenecek yer", "Bir anlatımın kendine özgü söyleyiş biçimi", "Bir anlatımın kolay anlaşılır olma özelliği", "Başkalarını gözeten incelikli davranış"], "answer": "Bir işte veya dizilişte izlenecek yer", "explanation": "Söz sırası gelince önerimi sundum."}, {"id": "6-4-kelime-6", "prompt": "“üslup” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir anlatımın kendine özgü söyleyiş biçimi", "Bir anlatımın kolay anlaşılır olma özelliği", "Başkalarını gözeten incelikli davranış", "Bir işin güçlü ve geliştirilebilir yanlarını gerekçeleriyle inceleme"], "answer": "Bir anlatımın kendine özgü söyleyiş biçimi", "explanation": "İletinin üslubu daha nazik hâle getirildi."}, {"id": "6-4-kelime-7", "prompt": "“açıklık” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir anlatımın kolay anlaşılır olma özelliği", "Başkalarını gözeten incelikli davranış", "Bir işin güçlü ve geliştirilebilir yanlarını gerekçeleriyle inceleme", "Bir işin nasıl yapılabileceğine ilişkin düşünce"], "answer": "Bir anlatımın kolay anlaşılır olma özelliği", "explanation": "Duyurunun açıklığını kontrol ettik."}, {"id": "6-4-kelime-8", "prompt": "“nezaket” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Başkalarını gözeten incelikli davranış", "Bir işin güçlü ve geliştirilebilir yanlarını gerekçeleriyle inceleme", "Bir işin nasıl yapılabileceğine ilişkin düşünce", "Bir görüşü veya işi uygun bulma"], "answer": "Başkalarını gözeten incelikli davranış", "explanation": "Nezaket görüş ayrılığında da sürmelidir."}, {"id": "6-4-kelime-9", "prompt": "“eleştiri” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir işin güçlü ve geliştirilebilir yanlarını gerekçeleriyle inceleme", "Bir işin nasıl yapılabileceğine ilişkin düşünce", "Bir görüşü veya işi uygun bulma", "Bir davranışı özgür iradeyle kabul etme"], "answer": "Bir işin güçlü ve geliştirilebilir yanlarını gerekçeleriyle inceleme", "explanation": "Eleştiri kişiliğe değil çalışmaya yönelikti."}]}'::jsonb),
