(6,'6-5-soz-3',42,'{"id": "6-5-soz-3", "title": "Söz varlığı · 3", "theme": "Bilim ve Teknoloji", "kind": "words", "body": [{"kelime": "otomasyon", "anlam": "Bir işin belirlenen kurallarla kendiliğinden yürütülmesi", "ornek": "Sulama otomasyonu tasarladık.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "hata payı", "anlam": "Bir ölçümde beklenebilen belirsizlik aralığı", "ornek": "Hata payını grafiğin altına yazdık.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "çözüm", "anlam": "Bir sorunu gidermek için bulunan yol", "ornek": "Çözüm küçük bir denemeyle sınandı.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "onarım", "anlam": "Bozulan bir şeyi yeniden işler hâle getirme", "ornek": "Onarım atölyesinde güvenlik kurallarını izledik.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "erişilebilirlik", "anlam": "Bir ürünün farklı ihtiyaçları olan kişilerce kullanılabilmesi", "ornek": "Düğmelerin erişilebilirliğini değerlendirdik.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "çıktı", "anlam": "Bir işlem veya sistem sonunda elde edilen ürün", "ornek": "Programın çıktısı her zaman doğru olmayabilir.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "girdi", "anlam": "Bir sisteme işlenmek üzere verilen bilgi", "ornek": "Eksik girdi sonucu değiştirdi.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "güvenilirlik", "anlam": "Bir bilginin veya aracın tutarlı ve dayanaklı olma niteliği", "ornek": "Kaynağın güvenilirliğini değerlendirdik.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "yenilik", "anlam": "Daha önceki uygulamaya yeni bir özellik ekleyen değişim", "ornek": "Yenilik küçük bir ihtiyaçtan doğdu.", "tip": "kelime", "cikti": "T.O.6.21"}, {"kelime": "uygulama", "anlam": "Bir düşüncenin işleme dönüştürülmesi", "ornek": "Uygulama sırasında planı değiştirdik.", "tip": "kelime", "cikti": "T.O.6.21"}], "questions": [{"id": "6-5-kelime-20", "prompt": "“otomasyon” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir işin belirlenen kurall