(7,'7-2-soz-3',12,'{"id": "7-2-soz-3", "title": "Söz varlığı · 3", "theme": "Bir Hilal Uğruna", "kind": "words", "body": [{"kelime": "birlik", "anlam": "Aynı amaç çevresinde birleşme durumu", "ornek": "Birlik içinde hazırlıkları tamamladık.", "tip": "kelime", "cikti": "T.O.7.21"}, {"kelime": "ulaştırmak", "anlam": "Bir şeyi gitmesi gereken yere götürmek veya göndermek", "ornek": "Kutuları depoya ulaştırdık.", "tip": "kelime", "cikti": "T.O.7.21"}, {"kelime": "korumak", "anlam": "Zarar görmesini veya kaybolmasını önlemek", "ornek": "Eski fotoğrafları ışıktan korumak gerekiyordu.", "tip": "kelime", "cikti": "T.O.7.21"}, {"kelime": "hatırat", "anlam": "Bir kişinin yaşadıklarını sonradan anlattığı eser", "ornek": "Hatıratın ne zaman yazıldığını araştırdım.", "tip": "kelime", "cikti": "T.O.7.21"}, {"kelime": "bellek", "anlam": "Yaşananları ve öğrenilenleri saklama yetisi", "ornek": "Müze toplumsal belleğe katkı sağlıyor.", "tip": "kelime", "cikti": "T.O.7.21"}, {"kelime": "restorasyon", "anlam": "Bir eseri özgün özelliklerini gözeterek onarma işi", "ornek": "Binadaki restorasyon uzmanlarca yürütüldü.", "tip": "kelime", "cikti": "T.O.7.21"}, {"kelime": "özgürlük", "anlam": "Başkalarının haklarını gözeterek seçim yapabilme durumu", "ornek": "Özgürlük ile sorumluluğu birlikte konuştuk.", "tip": "kelime", "cikti": "T.O.7.21"}, {"kelime": "uzlaşma", "anlam": "Farklı görüşlerin ortak bir çözümde buluşması", "ornek": "Sergi düzeninde uzlaşma sağlandı.", "tip": "kelime", "cikti": "T.O.7.21"}, {"kelime": "katılım", "anlam": "Bir çalışmada veya kararda yer alma", "ornek": "Gönüllü katılım için duyuru hazırladık.", "tip": "kelime", "cikti": "T.O.7.21"}, {"kelime": "güven", "anlam": "Birine veya bir şeye duyulan inanma duygusu", "ornek": "Açık bilgi paylaşımı güven oluşturdu.", "tip": "kelime", "cikti": "T.O.7.21"}], "questions": [{"id": "7-2-kelime-20", "prompt": "“birlik” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Aynı amaç çevresinde birleşme durumu", "Bir topluluğun ken