(8,'8-2-soz-3',14,'{"id": "8-2-soz-3", "title": "Söz varlığı · 3", "theme": "Millî Mücadele ve Atatürk", "kind": "words", "body": [{"kelime": "birlik", "anlam": "Aynı amaç çevresinde birleşme durumu", "ornek": "Birlik içinde hazırlıkları tamamladık.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "ulaştırmak", "anlam": "Bir şeyi gitmesi gereken yere götürmek veya göndermek", "ornek": "Kutuları depoya ulaştırdık.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "korumak", "anlam": "Zarar görmesini veya kaybolmasını önlemek", "ornek": "Eski fotoğrafları ışıktan korumak gerekiyordu.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "hatırat", "anlam": "Bir kişinin yaşadıklarını sonradan anlattığı eser", "ornek": "Hatıratın ne zaman yazıldığını araştırdım.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "bellek", "anlam": "Yaşananları ve öğrenilenleri saklama yetisi", "ornek": "Müze toplumsal belleğe katkı sağlıyor.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "restorasyon", "anlam": "Bir eseri özgün özelliklerini gözeterek onarma işi", "ornek": "Binadaki restorasyon uzmanlarca yürütüldü.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "özgürlük", "anlam": "Başkalarının haklarını gözeterek seçim yapabilme durumu", "ornek": "Özgürlük ile sorumluluğu birlikte konuştuk.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "uzlaşma", "anlam": "Farklı görüşlerin ortak bir çözümde buluşması", "ornek": "Sergi düzeninde uzlaşma sağlandı.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "katılım", "anlam": "Bir çalışmada veya kararda yer alma", "ornek": "Gönüllü katılım için duyuru hazırladık.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "güven", "anlam": "Birine veya bir şeye duyulan inanma duygusu", "ornek": "Açık bilgi paylaşımı güven oluşturdu.", "tip": "kelime", "cikti": "T.8.3.5"}], "questions": [{"id": "8-2-kelime-20", "prompt": "“birlik” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Aynı amaç çevresinde birleşme durumu", "Bir topluluğun kendi kararlarını kendisinin verebilmesi", "Yönetme ve karar verme yetkisi", "Yönetim yetkisinin milletin seçtiği temsilciler aracılığıyla kullanıldığı yönetim biçimi"], "answer": "Aynı amaç çevresinde birleşme durumu", "explanation": "Birlik içinde hazırlıkları tamamladık."}, {"id": "8-2-kelime-21", "prompt": "“ulaştırmak” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir şeyi gitmesi gereken yere götürmek veya göndermek", "Yönetme ve karar verme yetkisi", "Yönetim yetkisinin milletin seçtiği temsilciler aracılığıyla kullanıldığı yönetim biçimi", "Bir amaç veya güçlük karşısında birbirine destek olma"], "answer": "Bir şeyi gitmesi gereken yere götürmek veya göndermek", "explanation": "Kutuları depoya ulaştırdık."}, {"id": "8-2-kelime-22", "prompt": "“korumak” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Zarar görmesini veya kaybolmasını önlemek", "Yönetim yetkisinin milletin seçtiği temsilciler aracılığıyla kullanıldığı yönetim biçimi", "Bir amaç veya güçlük karşısında birbirine destek olma", "Bir amaç için kendi isteğinden veya rahatından vazgeçme"], "answer": "Zarar görmesini veya kaybolmasını önlemek", "explanation": "Eski fotoğrafları ışıktan korumak gerekiyordu."}, {"id": "8-2-kelime-23", "prompt": "“hatırat” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir kişinin yaşadıklarını sonradan anlattığı eser", "Bir amaç veya güçlük karşısında birbirine destek olma", "Bir amaç için kendi isteğinden veya rahatından vazgeçme", "Bir kararın arkasında durup çalışmayı sürdürme"], "answer": "Bir kişinin yaşadıklarını sonradan anlattığı eser", "explanation": "Hatıratın ne zaman yazıldığını araştırdım."}, {"id": "8-2-kelime-24", "prompt": "“bellek” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Yaşananları ve öğrenilenleri saklama yetisi", "Bir amaç için kendi isteğinden veya rahatından vazgeçme", "Bir kararın arkasında durup çalışmayı sürdürme", "Üstlenilen işi yerine getirme yükümlülüğü"], "answer": "Yaşananları ve öğrenilenleri saklama yetisi", "explanation": "Müze toplumsal belleğe katkı sağlıyor."}, {"id": "8-2-kelime-25", "prompt": "“restorasyon” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir eseri özgün özelliklerini gözeterek onarma işi", "Bir kararın arkasında durup çalışmayı sürdürme", "Üstlenilen işi yerine getirme yükümlülüğü", "Korunması veya sonradan geri verilmesi için bırakılan şey"], "answer": "Bir eseri özgün özelliklerini gözeterek onarma işi", "explanation": "Binadaki restorasyon uzmanlarca yürütüldü."}, {"id": "8-2-kelime-26", "prompt": "“özgürlük” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Başkalarının haklarını gözeterek seçim yapabilme durumu", "Üstlenilen işi yerine getirme yükümlülüğü", "Korunması veya sonradan geri verilmesi için bırakılan şey", "Bir savaşta karşıt güçlerin karşılaştığı bölge"], "answer": "Başkalarının haklarını gözeterek seçim yapabilme durumu", "explanation": "Özgürlük ile sorumluluğu birlikte konuştuk."}, {"id": "8-2-kelime-27", "prompt": "“uzlaşma” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Farklı görüşlerin ortak bir çözümde buluşması", "Korunması veya sonradan geri verilmesi için bırakılan şey", "Bir savaşta karşıt güçlerin karşılaştığı bölge", "Bir ihtiyacı karşılamak için bütün imkânlarla birlikte harekete geçme"], "answer": "Farklı görüşlerin ortak bir çözümde buluşması", "explanation": "Sergi düzeninde uzlaşma sağlandı."}, {"id": "8-2-kelime-28", "prompt": "“katılım” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir çalışmada veya kararda yer alma", "Bir savaşta karşıt güçlerin karşılaştığı bölge", "Bir ihtiyacı karşılamak için bütün imkânlarla birlikte harekete geçme", "Bir başkasının yararı için kendi çıkarından vazgeçme"], "answer": "Bir çalışmada veya kararda yer alma", "explanation": "Gönüllü katılım için duyuru hazırladık."}, {"id": "8-2-kelime-29", "prompt": "“güven” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Birine veya bir şeye duyulan inanma duygusu", "Bir ihtiyacı karşılamak için bütün imkânlarla birlikte harekete geçme", "Bir başkasının yararı için kendi çıkarından vazgeçme", "Bir topluluğun yaşadığı ve bağlılık duyduğu ülke"], "answer": "Birine veya bir şeye duyulan inanma duygusu", "explanation": "Açık bilgi paylaşımı güven oluşturdu."}]}'::jsonb),
(8,'8-2-okuma-1',15,'{"id": "8-2-okuma-1", "title": "Panodaki Son İmza", "theme": "Millî Mücadele ve Atatürk", "kind": "reading", "body": {"text": "Cumhuriyet temalı okul çalışmasının panosu neredeyse hazırdı. Öğrenciler bağımsızlık, eğitim ve ortak sorumluluk üzerine özgün metinler yazmış, araştırdıkları bilgilerin kaynaklarını ayrı bir bölümde göstermişti. Panonun altına çalışmayı hazırlayan grubun adı yazılacaktı. Fakat son kontrol sırasında yalnız sahnede konuşacak dört öğrencinin isimlerinin bulunduğu görüldü. Kâğıtları düzenleyen, kaynakları denetleyen ve panoyu erişilebilir yükseklikte yerleştiren arkadaşlarının katkıları görünmüyordu.\nAras bunun önemli olmadığını söyledi. Ziyaretçiler zaten bütün sınıfın çalıştığını anlayabilirdi. İpek ise ilk toplantıyı hatırlattı: Ortak emeği anlatan bir pano hazırlamak istemişlerdi. Hazırlanışındaki emeği görünmez bırakmaları kendi amaçlarıyla çelişiyordu. Konu yalnız herkesin adını büyük harfle yazmak değildi. Hangi katkının değerli sayıldığını düşünmeleri gerekiyordu. Sahneye çıkmayan birinin işi de çalışmanın sonucu için gerekli olabilirdi.\nÖğretmenleri isimleri hemen çoğaltmak yerine görevleri yeniden listelemelerini istedi. Liste uzadıkça pano daha farklı görünmeye başladı. Bir öğrenci küçük harflerin uzaktan okunmadığını fark etmiş, başka biri görsellerin açıklamasını yazmıştı. Konuşma metnindeki doğrulanmamış bir sözü çıkaran arkadaşları da vardı. Hiçbiri ziyaretçinin ilk bakışta göreceği gösterişli görevler değildi. Yine de hepsi bilginin doğru ve anlaşılır sunulmasına katkı sağlamıştı.\nGrup iki çözümü tartıştı. Birincisi herkesin adını rastgele sıralamaktı. İkincisi çalışmayı ortak sınıf ürünü olarak belirtmek, isteyenlerin gönüllü katkı notlarını ayrı dosyada tutmaktı. İsim paylaşımı konusunda okulun kurallarına uyacaklardı; kimse kişisel bilgisini panoya koymaya zorlanmayacaktı. Seçimlerinin gerekçesini de yazdılar. Böylece ortak katkıyı tanımak, bütün ayrıntıları herkesin önünde açıklamakla aynı şey sayılmadı.\nAçılış günü Aras konuşmasını bitirince dinleyicilerin alkışını duydu. Eskiden yalnız kendi performansını düşünebilirdi. Bu kez arkasındaki panoda tek bir öğrencinin zaferi yerine birlikte yapılan işin izlerini gördü. Konuşmada kullandığı açık bir geçiş cümlesini İpek önermişti. Büyük başlığın okunmasını kolaylaştıran boşluğu başka bir arkadaşı ayarlamıştı. Bunları fark etmek kendi emeğini küçültmüyor, çalışmanın nasıl mümkün olduğunu daha doğru görmesini sağlıyordu.\nProgramdan sonra öğrenciler hazırlık dosyasına kısa bir değerlendirme ekledi. Ne öğrendiklerini ve neyi farklı yapacaklarını yazdılar. Millî Mücadele ve Cumhuriyet üzerine konuşmanın yalnız geçmiş olayların adlarını söylemek olmadığını düşündüler. Ortak emek, sorumluluk ve doğru bilgi gibi kavramların bugünkü davranışlarında da karşılığı olabilirdi. Tarihî kişilere yeni sözler atfetmeden, kendi yaşadıkları sınıf deneyimi üzerinden bunu anlatmışlardı. Son imza bir kişinin adı olmadı. “Bu çalışma, farklı görevlerle katkı sunan sınıfımızın ortak ürünüdür.” cümlesi panonun altına yerleşti. İpek cümleyi uzaktan okuyup başını salladı. Bu küçük değişiklik, panonun savunduğu düşünceyle hazırlanış biçimini birbirine biraz daha yaklaştırmıştı.\nDeğerlendirme dosyasına görevlerin yalnız adları değil, birbirleriyle ilişkileri de eklendi. Kaynak kontrolü yapılmadan konuşma metni tamamlanamıyor, okunabilirlik denenmeden pano son biçimini alamıyordu. Öğrenciler bu bağlantıları küçük oklarla gösterdi. Bir işi önce yapmak her zaman daha önemli olmak anlamına gelmiyordu; bazen sonraki görevin başlayabilmesi için gerekliydi. Aras kendi çalışmasının nerede başkasının emeğine dayandığını görünce teşekkürünün daha somut olabileceğini düşündü. Genel bir övgü yerine hangi katkının neyi kolaylaştırdığını söyleyebilirdi. İpek de bunu önemli buldu. Son toplantıda herkes bir arkadaşının görünmeyen katkısını örnekle anlattı ve kayıtlar ortak dosyada saklandı.", "type": "oykuleyici"}, "questions": [{"id": "8-2-okuma-1-1", "prompt": "“Panodaki Son İmza” metnine göre: Başlangıçtaki eksiklik nedir?", "choices": ["Hiç kaynak bulunmaması", "Bütün metinlerin dışarıdan kopyalanması", "Yalnız sahneye çıkacakların katkısının görünmesi"], "answer": "Yalnız sahneye çıkacakların katkısının görünmesi", "explanation": "İlk paragraf görünmeyen hazırlık görevlerinin adlandırılmadığını anlatır."}, {"id": "8-2-okuma-1-2", "prompt": "“Panodaki Son İmza” metnine göre: İpek hangi çelişkiye dikkat çeker?", "choices": ["Tarihlerin alfabetik olmamasına", "Ortak emeği anlatırken bazı emekleri görünmez kılmaya", "Pano ile masa renklerinin ayrılmasına"], "answer": "Ortak emeği anlatırken bazı emekleri görünmez kılmaya", "explanation": "Amaç ile hazırlıkta tanınan katkılar arasında uyumsuzluk vardır."}, {"id": "8-2-okuma-1-3", "prompt": "“Panodaki Son İmza” metnine göre: Görev listesi neyi değiştirir?", "choices": ["Gösterişsiz katkıların da gerekli olduğunun görülmesini", "Sadece konuşma yapanların kalmasını", "Bütün görevlerin iptal edilmesini"], "answer": "Gösterişsiz katkıların da gerekli olduğunun görülmesini", "explanation": "Kaynak kontrolü ve okunabilirlik düzeni gibi işler listede görünür olur."}, {"id": "8-2-okuma-1-4", "prompt": "“Panodaki Son İmza” metnine göre: İsim paylaşımı konusunda ne gözetilir?", "choices": ["Herkesin özel bilgisinin zorunlu açıklanması", "Yalnız en uzun adı olanın yazılması", "Gönüllülük ve okulun kuralları"], "answer": "Gönüllülük ve okulun kuralları", "explanation": "Ortak emeği tanımak kişisel bilgi paylaşımına zorlamayla eşit sayılmaz."}, {"id": "8-2-okuma-1-5", "prompt": "“Panodaki Son İmza” metnine göre: Aras''ın tutumu nasıl değişir?", "choices": ["Konuşmanın gereksiz olduğunu savunur", "Kendi performansıyla birlikte diğer katkıları da fark eder", "Kendi emeğini bütünüyle yok sayar"], "answer": "Kendi performansıyla birlikte diğer katkıları da fark eder", "explanation": "Aras alkıştan sonra ürünün ortak hazırlıkla oluştuğunu düşünür."}, {"id": "8-2-okuma-1-6", "prompt": "“Panodaki Son İmza” metnine göre: Son cümledeki biraz daha sözü neyi anlatır?", "choices": ["Uyumun geliştirilmiş fakat kusursuz ilan edilmemiş olmasını", "Hiç değişiklik yapılmadığını", "Bütün sorunların kesin bittiğini"], "answer": "Uyumun geliştirilmiş fakat kusursuz ilan edilmemiş olmasını", "explanation": "İfade sınırlı ve gerçekçi bir gelişme bildirir."}, {"id": "8-2-okuma-1-7", "prompt": "“Panodaki Son İmza” metnine göre: Metinde tarihî kişiler adına ne yapılmamıştır?", "choices": ["Kendi sınıf deneyimi anlatılmamıştır", "Kaynaklar gösterilmemiştir", "Doğrulanmamış yeni sözler üretilmemiştir"], "answer": "Doğrulanmamış yeni sözler üretilmemiştir", "explanation": "Son bölüm öğrencilerin kendi deneyimlerini anlattığını açıklar."}, {"id": "8-2-okuma-1-8", "prompt": "“Panodaki Son İmza” metnine göre: Ana düşünce hangisidir?", "choices": ["Bir başarı yalnız en görünür kişiye aittir", "Ortaklık söylemi, farklı katkıları tanıyan uygulamayla desteklenmelidir", "Sahne dışında yapılan işler önemsizdir"], "answer": "Ortaklık söylemi, farklı katkıları tanıyan uygulamayla desteklenmelidir", "explanation": "Olaylar amaçla davranışın tutarlılığına ve görünmeyen emeğe odaklanır."}]}'::jsonb),
(8,'8-2-okuma-2',16,'{"id": "8-2-okuma-2", "title": "Ortak Belleği Anlatmak", "theme": "Millî Mücadele ve Atatürk", "kind": "reading", "body": {"text": "Bir toplumun geçmişi hakkında hazırlanan çalışma, yalnız tarih ve isimleri sıralamaktan oluşmaz. Hangi olayların seçildiği, bunların hangi kaynaklarla açıklandığı ve aralarındaki ilişkinin nasıl kurulduğu da anlatımı biçimlendirir. Millî Mücadele ve Atatürk temalı bir okul çalışması bu bakımdan hem araştırma hem iletişim görevidir. Amaç, kaynağı belli bilgiyle düşünmek ve bu bilgiyi doğru kapsamda sunmaktır. Etkileyici bir anlatım kurma isteği, doğrulanmamış ayrıntıları kesinleştirmeye gerekçe olamaz.\nİlk aşamada çalışma sorusu belirlenebilir. Çok geniş bir konu, kısa bir panoda bütün yönleriyle ele alınamaz. Örneğin ortak bir amaca katkı sağlayan farklı görevler üzerinde durulacaksa belgeler bu soruyla ilişkilendirilir. Bir örnek, bütün dönemi tek başına temsil ettiği iddiasıyla sunulmaz. Seçimin neden yapıldığı açıklanır. Böylece okur önündeki çalışmanın sınırını görür; eksik bırakılan her ayrıntıyı yok sayılmış kabul etmek zorunda kalmaz.\nKaynakların türleri de birbirinden ayrılmalıdır. Olay sırasında tutulmuş bir kayıt, yıllar sonra yazılmış bir anı ve güncel bir inceleme aynı koşullarda oluşmaz. Aralarındaki farkları bilmek, birini otomatik olarak doğru ve diğerini yanlış saymak demek değildir. Her kaynak, hangi soruya ne ölçüde cevap verdiği düşünülerek incelenir. Bir kişinin hatırladığı ayrıntı, başka belgelerle karşılaştırılabilir. Kaynakta bulunmayan duygu ve konuşmalar ise araştırmacının kesin bilgisi gibi eklenmez.\nSunumda görsellerin açıklaması da metnin parçasıdır. Bir görselin tarihi veya niteliği biliniyorsa belirtilir. Sonradan yapılmış öğrenci modeli, dönemden kalmış özgün eser diye tanıtılmaz. Harita bir şemaysa tam güzergâhı kesin olarak gösterdiği ileri sürülmez. Görselin güçlü etkisi, onu kendiliğinden kanıt yapmaz. Okurun ne gördüğünü anlayabilmesi için kısa fakat açık bir bilgiye ihtiyacı vardır.\nFarklı kaynaklar arasında ayrılık bulunduğunda bu durum saklanmayabilir. Öğrenciler öğretmenlerinin rehberliğiyle hangi noktaların ortak, hangilerinin henüz tartışmalı olduğunu gösterebilir. Bir belirsizliği açıkça belirtmek, çalışmanın değerini zorunlu olarak azaltmaz. Aksine, bilinenle bilinmeyenin ayrıldığını gösterir. Bu yaklaşım, ortak geçmişi önemsemenin bilgiye özen göstermeyi de gerektirdiğini düşündürür. Saygı, doğrulukla birlikte yürütülebilir.\nSon aşamada ürünün okuyucuyla kurduğu ilişki değerlendirilir. Başlık soruyu yansıtıyor mu, kaynak notları bulunabiliyor mu, yazılar farklı uzaklıklardan okunabiliyor mu? Bunlar araştırmadan bağımsız süsleme soruları değildir. Bilgiye ulaşmanın ve onu anlamanın koşullarıdır. Çalışmanın sonunda kullanılan kaynakların ve alınan kararların kısa bir kaydı saklanabilir. Yeni bir belge bulunduğunda veya açıklama düzeltilmesi gerektiğinde bu kayıt yardımcı olur. Ortak bellek üzerine çalışma böylece değişmez bir anlatıyı ezberlemekten daha geniş bir iş hâline gelir. Öğrenciler hem geçmişe ilişkin bilgiyi hem de bilgi sunarken taşıdıkları sorumluluğu düşünür. Sonuç ürün kadar araştırma yolu da anlam kazanır. Kaynakla konuşmayı öğrenmek, sonraki okuma ve tartışmalarda kullanılabilecek bir alışkanlık bırakır.\nHazırlık dosyasında her alıntının yanına kullanıldığı yer de yazılabilir. Böylece bir bilgi daha sonra düzeltilirse hangi pano veya konuşma bölümünün değişeceği bulunur. Bu düzen yalnız araştırmayı yapan ilk grup için değildir. Sonraki öğrenciler de aynı kaynağı nerede ve neden kullandıklarını izleyebilir. Kaydın çok ayrıntılı olması şart değildir; anlaşılır olması önemlidir. Gereksiz kişisel bilgiler eklenmez. Belgenin kimden geldiği gibi gerekli kayıtlar okulun uygun süreçlerinde tutulur. Sunum için herkese açık dosya ile çalışma notlarının paylaşım kapsamı aynı olmayabilir. Bu ayrım, ortak belleği anlatırken güncel sorumlulukların da sürdüğünü gösterir.", "type": "bilgilendirici"}, "questions": [{"id": "8-2-okuma-2-1", "prompt": "“Ortak Belleği Anlatmak” metnine göre: Bir okul çalışmasında soru belirlemenin işlevi nedir?", "choices": ["Her ayrıntıyı tek panoya sığdırmak", "Kapsamı ve kaynak seçimini yönlendirmek", "Bütün kaynakları gereksiz yapmak"], "answer": "Kapsamı ve kaynak seçimini yönlendirmek", "explanation": "Çalışma sorusu hangi bilgilerin hangi amaçla seçildiğini belirler."}, {"id": "8-2-okuma-2-2", "prompt": "“Ortak Belleği Anlatmak” metnine göre: Bir örneğin sınırlı tutulması neyi önler?", "choices": ["Bütün dönemi temsil ettiği izlenimini", "Okurun kaynağa bakmasını", "Başlığın konuyla ilişkilendirilmesini"], "answer": "Bütün dönemi temsil ettiği izlenimini", "explanation": "Yazar örneğin kapsamının açık tutulmasını önerir."}, {"id": "8-2-okuma-2-3", "prompt": "“Ortak Belleği Anlatmak” metnine göre: Kaynak türlerini ayırmak ne anlama gelmez?", "choices": ["Oluşma koşullarını incelemek", "Soruyla ilişkisini değerlendirmek", "Bir türü otomatik doğru, diğerini yanlış saymak"], "answer": "Bir türü otomatik doğru, diğerini yanlış saymak", "explanation": "Metin kaynakları türüne göre peşinen kesinleştirmeyi reddeder."}, {"id": "8-2-okuma-2-4", "prompt": "“Ortak Belleği Anlatmak” metnine göre: Görselin güçlü etkisi hangi niteliği tek başına sağlamaz?", "choices": ["Bir yorum uyandırmasını", "Kanıt olmasını", "Okurun dikkatini çekmesini"], "answer": "Kanıt olmasını", "explanation": "Duygusal veya görsel etki doğruluk dayanağının yerini tutmaz."}, {"id": "8-2-okuma-2-5", "prompt": "“Ortak Belleği Anlatmak” metnine göre: Belirsizliğin belirtilmesi nasıl yorumlanır?", "choices": ["Bilinenle bilinmeyenin ayrılması", "Her bilginin yanlış ilanı", "Araştırmanın gereksiz oluşu"], "answer": "Bilinenle bilinmeyenin ayrılması", "explanation": "Açıklık çalışmanın bilgi sınırını gösterir."}, {"id": "8-2-okuma-2-6", "prompt": "“Ortak Belleği Anlatmak” metnine göre: Okunabilirlik neden içerikle ilişkilidir?", "choices": ["Yalnız dış görünüşü belirlediği için", "Kaynakların tarihini değiştirdiği için", "Bilgiye ulaşma ve anlamanın koşulu olduğu için"], "answer": "Bilgiye ulaşma ve anlamanın koşulu olduğu için", "explanation": "Bilgi sunulsa da okunamıyorsa iletişim işlevi sınırlanır."}, {"id": "8-2-okuma-2-7", "prompt": "“Ortak Belleği Anlatmak” metnine göre: Karar kaydı ne zaman yararlıdır?", "choices": ["Bütün çalışmayı değişmez kılmak için", "Yeni bilgi veya düzeltme gerektiğinde", "Kaynakları saklamak istendiğinde"], "answer": "Yeni bilgi veya düzeltme gerektiğinde", "explanation": "Kayıt, sonraki incelemelerde önceki kararın dayanağını izletir."}, {"id": "8-2-okuma-2-8", "prompt": "“Ortak Belleği Anlatmak” metnine göre: Ana düşünce hangisidir?", "choices": ["Ortak geçmişi anlatmak kaynak, kapsam ve sunum sorumluluğu ister", "Etkileyici anlatım doğruluk için yeterlidir", "Kaynaklar arasındaki farklar daima gizlenmelidir"], "answer": "Ortak geçmişi anlatmak kaynak, kapsam ve sunum sorumluluğu ister", "explanation": "Bölümler araştırmayla iletişimin birlikte özen istediğini vurgular."}]}'::jsonb),
(8,'8-2-8-2-temel-ogeler',17,'{"id": "8-2-8-2-temel-ogeler", "title": "Yüklem ve özne", "theme": "Millî Mücadele ve Atatürk", "kind": "lesson", "body": {"html": "<p>Yüklem cümlenin temel yargısını taşır; özne bu yargının bildirdiği işi yapan veya durumda bulunan unsurdur. Önce yüklemi belirlemek, sonra ona uygun kim veya ne sorusunu sormak çözümlemeyi kolaylaştırır. Her cümlede açık özne bulunmayabilir. Kişi ekinden anlaşılan gizli özneyle cümlede yazılı özneyi ayır. Bir kelimeyi yalnız başta durduğu için özne sayma.</p><ul><li>Öğrenciler panoyu hazırladı.</li><li>Pano hazırdı.</li><li>Notları topladık: gizli özne biz.</li></ul>", "examples": ["Öğrenciler panoyu hazırladı.", "Pano hazırdı.", "Notları topladık: gizli özne biz."], "code": "T.8.4.18"}, "questions": [{"id": "8-2-temel-ogeler-1", "prompt": "“Öğrenciler panoyu hazırladı. / yüklem” için istenen öge hangisidir?", "choices": ["Panoyu", "Hazırladı", "Öğrenciler"], "answer": "Hazırladı", "explanation": "Temel yargı hazırladı sözünde bulunur."}, {"id": "8-2-temel-ogeler-2", "prompt": "“Öğrenciler panoyu hazırladı. / özne” için istenen öge hangisidir?", "choices": ["Öğrenciler", "Panoyu", "Hazırladı"], "answer": "Öğrenciler", "explanation": "Hazırlayan kim sorusunun cevabı öğrenciler sözüdür."}, {"id": "8-2-temel-ogeler-3", "prompt": "“Pano bugün hazırdı. / yüklem” için istenen öge hangisidir?", "choices": ["Pano", "Bugün", "Hazırdı"], "answer": "Hazırdı", "explanation": "Hazır olma yargısını taşıyan söz hazırdıdır."}, {"id": "8-2-temel-ogeler-4", "prompt": "“Notları birlikte topladık. / gizli özne” için istenen öge hangisidir?", "choices": ["Birlikte", "Biz", "Notlar"], "answer": "Biz", "explanation": "Topladık kişi eki konuşanı içeren çoğul özneyi gösterir."}, {"id": "8-2-temel-ogeler-5", "prompt": "“İpek kaynakları denetledi. / özne” için istenen öge hangisidir?", "choices": ["İpek", "Kaynakları", "Denetledi"], "answer": "İpek", "explanation": "Denetleyen kim sorusu özneyi verir."}, {"id": "8-2-temel-ogeler-6", "prompt": "“Kapının yanında bir kutu vardı. / özne” için istenen öge hangisidir?", "choices": ["Kapının yanında", "Vardı", "Bir kutu"], "answer": "Bir kutu", "explanation": "Var olan ne sorusunun cevabı bir kutudur."}, {"id": "8-2-temel-ogeler-7", "prompt": "“Panoyu Aras düzenledi. / özne” için istenen öge hangisidir?", "choices": ["Düzenledi", "Aras", "Panoyu"], "answer": "Aras", "explanation": "Kelimenin sıradaki yeri değil, yüklemle ilişkisi belirleyicidir."}, {"id": "8-2-temel-ogeler-8", "prompt": "“Sınıfın hazırlığı tamamlandı. / yüklem” için istenen öge hangisidir?", "choices": ["Tamamlandı", "Sınıfın", "Hazırlığı"], "answer": "Tamamlandı", "explanation": "Cümlede temel yargı tamamlandı sözüdür."}, {"id": "8-2-temel-ogeler-9", "prompt": "“Çalışmamız anlamlıydı. / özne” için istenen öge hangisidir?", "choices": ["Anlamlıydı", "Biz", "Çalışmamız"], "answer": "Çalışmamız", "explanation": "Anlamlı olan ne sorusu çalışmamız sözünü verir."}, {"id": "8-2-temel-ogeler-10", "prompt": "“Kaynak notunu unutmadın. / gizli özne” için istenen öge hangisidir?", "choices": ["O", "Sen", "Kaynak notu"], "answer": "Sen", "explanation": "Unutmadın kişi eki ikinci tekil özneyi gösterir."}]}'::jsonb),
(8,'8-2-8-2-yardimci-ogeler',18,'{"id": "8-2-8-2-yardimci-ogeler", "title": "Nesne, yer ve zarf tamlayıcısı", "theme": "Millî Mücadele ve Atatürk", "kind": "lesson", "body": {"html": "<p>Cümlede yardımcı ögeler yüklemin anlamını farklı yönlerden tamamlar. Nesne işten etkilenen unsuru, yer tamlayıcısı yönelme, bulunma veya ayrılma ilişkisini, zarf tamlayıcısı zaman, durum veya sebep gibi katkıları bildirebilir. Soruları cümledeki yükleme yönelt. Bir kelimenin ekini görmek tek başına yeterli değildir; bütün söz grubunun görevini incele.</p><ul><li>Metni okudum: nesne.</li><li>Okula gittim: yer tamlayıcısı.</li><li>Dün geldim: zarf tamlayıcısı.</li></ul>", "examples": ["Metni okudum: nesne.", "Okula gittim: yer tamlayıcısı.", "Dün geldim: zarf tamlayıcısı."], "code": "T.8.4.18"}, "questions": [{"id": "8-2-yardimci-ogeler-1", "prompt": "“Aras metni okudu. / metni” örneğinde belirtilen sözün görevi nedir?", "choices": ["Zarf tamlayıcısı", "Belirtili nesne", "Özne"], "answer": "Belirtili nesne", "explanation": "Neyi okudu sorusuna metni cevabı verilir."}, {"id": "8-2-yardimci-ogeler-2", "prompt": "“İpek okula gitti. / okula” örneğinde belirtilen sözün görevi nedir?", "choices": ["Yer tamlayıcısı", "Belirtili nesne", "Özne"], "answer": "Yer tamlayıcısı", "explanation": "Nereye gitti sorusu yönelme ilişkili ögeyi buldurur."}, {"id": "8-2-yardimci-ogeler-3", "prompt": "“Öğrenciler dün buluştu. / dün” örneğinde belirtilen sözün görevi nedir?", "choices": ["Nesne", "Yüklem", "Zarf tamlayıcısı"], "answer": "Zarf tamlayıcısı", "explanation": "Ne zaman buluştu sorusunun cevabı dün sözüdür."}, {"id": "8-2-yardimci-ogeler-4", "prompt": "“Kutuyu rafa koydu. / rafa” örneğinde belirtilen sözün görevi nedir?", "choices": ["Belirtisiz nesne", "Yer tamlayıcısı", "Özne"], "answer": "Yer tamlayıcısı", "explanation": "Nereye koydu sorusunu rafa karşılar."}, {"id": "8-2-yardimci-ogeler-5", "prompt": "“Kartları dikkatle düzenledi. / dikkatle” örneğinde belirtilen sözün görevi nedir?", "choices": ["Zarf tamlayıcısı", "Belirtili nesne", "Özne"], "answer": "Zarf tamlayıcısı", "explanation": "Nasıl düzenledi sorusu durum bildiren ögeyi verir."}, {"id": "8-2-yardimci-ogeler-6", "prompt": "“Panoya etiket astık. / etiket” örneğinde belirtilen sözün görevi nedir?", "choices": ["Yer tamlayıcısı", "Yüklem", "Belirtisiz nesne"], "answer": "Belirtisiz nesne", "explanation": "Ne astık sorusuna cevap veren etiket belirtisiz nesnedir."}, {"id": "8-2-yardimci-ogeler-7", "prompt": "“Öğretmen sınıftan çıktı. / sınıftan” örneğinde belirtilen sözün görevi nedir?", "choices": ["Zarf-fiil", "Yer tamlayıcısı", "Nesne"], "answer": "Yer tamlayıcısı", "explanation": "Nereden çıktı sorusu ayrılma ilişkili ögeyi gösterir."}, {"id": "8-2-yardimci-ogeler-8", "prompt": "“Öğrenciler bu sabah çalıştı. / bu sabah” örneğinde belirtilen sözün görevi nedir?", "choices": ["Zarf tamlayıcısı", "Belirtili nesne", "Özne"], "answer": "Zarf tamlayıcısı", "explanation": "Zaman bildiren söz grubu bir bütün olarak ögedir."}, {"id": "8-2-yardimci-ogeler-9", "prompt": "“Defne bir açıklama yazdı. / bir açıklama” örneğinde belirtilen sözün görevi nedir?", "choices": ["Yer tamlayıcısı", "Yüklem", "Belirtisiz nesne"], "answer": "Belirtisiz nesne", "explanation": "Ne yazdı sorusu işten etkilenen ad grubunu verir."}, {"id": "8-2-yardimci-ogeler-10", "prompt": "“Kaynakları kütüphanede inceledik. / kütüphanede” örneğinde belirtilen sözün görevi nedir?", "choices": ["Gizli özne", "Yer tamlayıcısı", "Nesne"], "answer": "Yer tamlayıcısı", "explanation": "Nerede inceledik sorusunun cevabı bulunma ilişkili ögedir."}]}'::jsonb),
(8,'8-2-dinleme',19,'{"id": "8-2-dinleme", "title": "Görünmeyen Görevler", "theme": "Millî Mücadele ve Atatürk", "kind": "listening", "body": {"text": "Anma çalışmasının altına yalnız konuşma yapanların adı yazılmıştı. Hazırlık toplantısında kaynak kontrolü ve okunabilirlik düzeni gibi görevlerin de gerekli olduğu hatırlatıldı. Grup ortak ürünü sınıf adına tanıtmaya karar verdi. Kişisel bilgi paylaşımı için okulun uygun kuralları gözetildi. İsteyenlerin katkı notları ayrı dosyada tutuldu. Bir öğrencinin sahnede görünmemesi, çalışmaya katkısı olmadığı anlamına gelmiyordu. Öğrenciler görevlerin birbirine nasıl bağlandığını da kaydetti; sonraki çalışmada bu ilişkilerden yararlanabileceklerdi."}, "questions": [{"id": "8-2-dinleme-1", "prompt": "“Görünmeyen Görevler” dinleme metnine göre: İlk listede kimler vardı?", "choices": ["Bütün hazırlık görevlileri", "Yalnız ziyaretçiler", "Konuşma yapanlar"], "answer": "Konuşma yapanlar", "explanation": "Dinlenen olayın sırası ve açıklamaları “Konuşma yapanlar” cevabını destekler. Diğer seçeneklerdeki ayrıntılar metinde verilen bilgiyle uyuşmaz."}, {"id": "8-2-dinleme-2", "prompt": "“Görünmeyen Görevler” dinleme metnine göre: Hatırlatılan katkılardan biri nedir?", "choices": ["Özel adres toplama", "Kaynak kontrolü", "Bilet satışı"], "answer": "Kaynak kontrolü", "explanation": "Dinlenen olayın sırası ve açıklamaları “Kaynak kontrolü” cevabını destekler. Diğer seçeneklerdeki ayrıntılar metinde verilen bilgiyle uyuşmaz."}, {"id": "8-2-dinleme-3", "prompt": "“Görünmeyen Görevler” dinleme metnine göre: Ortak ürün nasıl tanıtıldı?", "choices": ["Sınıf adına", "Yalnız tek öğrenci adına", "Kaynağı olmayan belge olarak"], "answer": "Sınıf adına", "explanation": "Dinlenen olayın sırası ve açıklamaları “Sınıf adına” cevabını destekler. Diğer seçeneklerdeki ayrıntılar metinde verilen bilgiyle uyuşmaz."}, {"id": "8-2-dinleme-4", "prompt": "“Görünmeyen Görevler” dinleme metnine göre: Dinlenenin ana düşüncesi nedir?", "choices": ["Yalnız sahnede olmak önemlidir", "Her katkı özel bilgi yayımlamayı gerektirir", "Görünür olmayan görevler de ortak ürüne katkı sağlar"], "answer": "Görünür olmayan görevler de ortak ürüne katkı sağlar", "explanation": "Dinlenen olayın sırası ve açıklamaları “Görünür olmayan görevler de ortak ürüne katkı sağlar” cevabını destekler. Diğer seçeneklerdeki ayrıntılar metinde verilen bilgiyle uyuşmaz."}]}'::jsonb),
(8,'8-2-lgs-1',20,'{"id": "8-2-lgs-1", "title": "LGS · 1", "theme": "Millî Mücadele ve Atatürk", "kind": "lgs", "body": null, "questions": [{"id": "8-2-lgs-1", "prompt": "Ortak Emek Panosu için hazırlanan dört çalışma aşağıda verilmiştir.\nanma panosu A: 22 dakika; kaynak notu var; ses gereksinimi yok.\nanma panosu B: 25 dakika; kaynak notu var; ses gereksinimi yok.\nanma panosu C: 20 dakika; kaynak notu yok; ses gereksinimi yok.\nanma panosu D: 21 dakika; kaynak notu var; ses gereksinimi var.\nSeçilecek çalışmada kaynak notu bulunmalı, ses gerekmemeli ve süre 22 dakikayı aşmamalıdır. Üç koşulu birlikte sağlayan hangisidir?", "choices": ["anma panosu A", "anma panosu B", "anma panosu C", "anma panosu D"], "answer": "anma panosu A", "explanation": "anma panosu A üç koşulu sağlar. B süreyi aşar, C kaynak notu içermez, D ses gerektirir."}, {"id": "8-2-lgs-2", "prompt": "Ortak Emek Panosu programında dört işlem farklı sıralarda yapılacaktır: araştırma, kaynak kontrolü, metin yazımı, pano kurulumu. Araştırma, kaynak kontrolü işleminden önce yapılır. Metin yazımı, kaynak kontrolü işleminin hemen ardından gelir. Pano kurulumu son işlemdir. Her işlem bir kez yapılacağına göre uygun sıra hangisidir?", "choices": ["kaynak kontrolü → araştırma → metin yazımı → pano kurulumu", "araştırma → metin yazımı → kaynak kontrolü → pano kurulumu", "araştırma → kaynak kontrolü → pano kurulumu → metin yazımı", "araştırma → kaynak kontrolü → metin yazımı → pano kurulumu"], "answer": "araştırma → kaynak kontrolü → metin yazımı → pano kurulumu", "explanation": "pano kurulumu sonda olmalıdır. kaynak kontrolü ile metin yazımı yan yana ve bu sırada bulunur; araştırma da onlardan önce gelir."}, {"id": "8-2-lgs-3", "prompt": "Ortak Emek Panosu sonrasında gönüllü 12 katılımcının tamamı anma panosu çalışmasının anlaşılır olduğunu söyledi. Katılmayanlar ve cevap vermeyenler hakkında veri toplanmadı. Bu bilgiye dayanan, kapsamı aşmayan sonuç hangisidir?", "choices": ["Yanıt vermeyenlerin tamamı çalışmayı anlaşılmaz bulmuştur.", "Bu yöntem her koşulda en başarılı yöntemdir.", "Yanıt veren 12 kişi çalışmayı anlaşılır bulmuştur.", "Okuldaki herkes çalışmayı anlaşılır bulmuştur."], "answer": "Yanıt veren 12 kişi çalışmayı anlaşılır bulmuştur.", "explanation": "Veri yalnız yanıt veren gönüllü grubu kapsar; diğer kişiler veya bütün yöntemler hakkında kesin sonuç vermez."}, {"id": "8-2-lgs-4", "prompt": "Ortak Emek Panosu için iki görüş var. I: “Anma panosu kısa olmalı; okuyucu temel bilgiyi hızla bulabilmeli.” II: “Anma panosu gerektiğinde ayrıntı içermeli; okuyucunun önemli koşulları anlaması sağlanmalı.” Bu iki görüş hangi ilkede buluşur?", "choices": ["Okuyucunun ön bilgisi hiçbir zaman dikkate alınmamalıdır.", "İçerik, okuyucunun ihtiyacını karşılayacak biçimde düzenlenmelidir.", "Her metin olabilecek en kısa biçime indirilmelidir.", "Ayrıntılar bütün koşullarda kaldırılmalıdır."], "answer": "İçerik, okuyucunun ihtiyacını karşılayacak biçimde düzenlenmelidir.", "explanation": "İlk görüş hıza, ikincisi koşullara dikkat çeker; ortak nokta okuyucunun bilgiyi uygun biçimde almasıdır."}, {"id": "8-2-lgs-5", "prompt": "Aşağıdaki cümleler anlamlı bir paragraf oluşturacaktır.\nI. Ortak Emek Panosu grubu ilk taslağını hazırladı.\nII. Son değerlendirmede bu iki düzeltmenin etkisini birlikte inceledi.\nIII. Bu taslağı okuyanlar iki belirsiz nokta belirledi.\nIV. Grup, belirlenen noktaları açıklayan iki düzeltme yaptı.\nGönderimler ve işlem sırası gözetildiğinde doğru diziliş hangisidir?", "choices": ["I – III – IV – II", "III – I – IV – II", "I – II – III – IV", "IV – III – I – II"], "answer": "I – III – IV – II", "explanation": "Bu taslak, ilk taslağa; belirlenen noktalar, okuyucu tespitine; bu iki düzeltme, yapılan değişikliklere gönderir."}, {"id": "8-2-lgs-6", "prompt": "Ortak Emek Panosu için hazırlanan anma panosu ilk denemede uzun bulundu. Grup bazı tekrarları çıkardı. ——— önemli bir koşulun da silindiğini görünce onu yeniden ekledi. Daha kısa bir metin elde etmek, her durumda daha doğru bir metin elde etmek değildi. Boşluğa, önceki adımın beklenen yararına karşı ortaya çıkan sınırlılığı belirtmek için hangisi getirilmelidir?", "choices": ["Bu nedenle", "Örneğin", "Başka bir deyişle", "Ancak"], "answer": "Ancak", "explanation": "Kısaltma olumlu bir adım gibi görünürken koşul kaybı ters bir durum getirir; ancak bu karşıtlığı bağlar."}, {"id": "8-2-lgs-7", "prompt": "Anma panosunu hazırlayan sınıf yalnız sahnede konuşanları değil, kaynak ve okunabilirlik kontrolü yapanları da değerlendirdi. Görevlerin birbirine nasıl bağlı olduğunu gösteren bir kayıt hazırladı. Böylece görünür olmanın katkının tek ölçütü olmadığını, ortak ürünün farklı işler sayesinde tamamlandığını fark etti.\nBu parçada asıl vurgulanan düşünce hangisidir?", "choices": ["Yeni bilgi ilk kararı hiçbir koşulda değiştirmemelidir.", "Bütün durumlar tek bir ölçütle eksiksiz açıklanabilir.", "Bir değerlendirme, amaca uygun somut dayanaklarla gözden geçirilmelidir.", "İlk izlenim her zaman yeterli ve kesindir."], "answer": "Bir değerlendirme, amaca uygun somut dayanaklarla gözden geçirilmelidir.", "explanation": "Parçada ilk yargı, yeni inceleme ve somut dayanaklarla düzeltilir; kapsamı geniş kesinlikler savunulmaz."}, {"id": "8-2-lgs-8", "prompt": "Ortak Emek Panosu yönergesi şöyledir: Kaynak bilgisi eksik anma panosu doğrudan geri bildirim aşamasına alınır; tamamlanmadan sunuma geçmez. Kaynak bilgisi tamam olanlar önce içerik kontrolünden geçer, uygun bulunursa sunulur. Kaynak bilgisi eksik bir çalışma için ilk uygun işlem hangisidir?", "choices": ["Kaynak eksik olsa da doğrudan uygun saymak", "Eksik bilgi için geri bildirim vermek", "İçerik kontrolünü atlayıp sunmak", "Eksikliği görünmez biçimde silmek"], "answer": "Eksik bilgi için geri bildirim vermek", "explanation": "Yönergenin ilk koşulu eksik kaynak durumunu açıkça geri bildirime bağlar."}, {"id": "8-2-lgs-9", "prompt": "Ortak Emek Panosu çalışmasında yalnız iki küçük grubun anma panosu örnekleri incelendi. Bir grupta açıklama notu varken diğerinde yoktu. Açıklama notu olan örnekte katılımcılar daha az soru sordu. Bu sınırlı bulgu için kapsamı en doğru başlık hangisidir?", "choices": ["İki Gruptaki Örneklerde Açıklama Notuyla Soru Sayısı Birlikte İncelendi", "Açıklama Notları Bütün Soruları Sonsuza Dek Bitirdi", "Bütün Öğrenciler Aynı Yöntemi Tercih Ediyor", "Not Olmayan Her Çalışma Başarısızdır"], "answer": "İki Gruptaki Örneklerde Açıklama Notuyla Soru Sayısı Birlikte İncelendi", "explanation": "Başlık iki grup ve gözlenen ilişki sınırını korur; evrensel veya nedensel kesinlik üretmez."}, {"id": "8-2-lgs-10", "prompt": "Bir paragrafın konusu Ortak Emek Panosu kayıtlarının nasıl tutulduğudur. I: Tarih ve yöntem her kayda eklendi. II: Gözlenmeyen alanlar boş bırakılıp açıklandı. III: Etkinliğin afişi bence yılın en güzel afişiydi. IV: Yöntem değiştiğinde kayda not düşüldü. Konu bütünlüğünü bozan cümle hangisidir?", "choices": ["III", "I", "II", "IV"], "answer": "III", "explanation": "Diğer cümleler kayıt yöntemini anlatır; III etkinlikle ilgili olsa da afişin kişisel beğeni değerine geçer."}]}'::jsonb),
(8,'8-2-lgs-2',21,'{"id": "8-2-lgs-2", "title": "LGS · 2", "theme": "Millî Mücadele ve Atatürk", "kind": "lgs", "body": null, "questions": [{"id": "8-2-lgs-11", "prompt": "Ortak Emek Panosu değerlendirmesinde dört cümle yazılmıştır. Hangisi kişisel beğeni yerine kontrol edilebilir bir bilgi bildirir?", "choices": ["Bu çalışma tartışmasız en etkileyici üründür.", "Etkinliğin havası bütün diğerlerinden güzeldi.", "Seçilen örnekler herkes için kusursuzdu.", "Dosyada 5 adet anma panosu örneği bulunuyor."], "answer": "Dosyada 5 adet anma panosu örneği bulunuyor.", "explanation": "Örnek sayısı sayılarak kontrol edilebilir; diğer sözler beğeni veya kapsamı belirsiz değer yargısı içerir."}, {"id": "8-2-lgs-12", "prompt": "Ortak Emek Panosu sunumuna kabul edilmek için hem içerik onayı hem paylaşım izni gereklidir. Bir anma panosu örneğinin içerik onayı aldığı biliniyor; paylaşım izni hakkında bilgi yoktur. Kesin olarak söylenebilecek yargı hangisidir?", "choices": ["Kesinlikle paylaşım izni reddedilmiştir.", "İçerik onayı almadığı kanıtlanmıştır.", "Sunuma kabul edildiği henüz kesinleştirilemez.", "Kesinlikle sunuma kabul edilmiştir."], "answer": "Sunuma kabul edildiği henüz kesinleştirilemez.", "explanation": "İki gerekli koşuldan yalnız biri bilinmektedir. İzin bilgisi yokluğu ne kabulü ne de reddi kanıtlar."}, {"id": "8-2-lgs-13", "prompt": "Ortak Emek Panosu kayıt tablosu: toplam çalışma / eksik alan sayısı\nI: 14 / 3\nII: 18 / 1\nIII: 16 / 0\nIV: 20 / 2\nEn az 16 çalışma içeren ve eksik alanı olmayan dosya hangisidir?", "choices": ["IV", "III", "I", "II"], "answer": "III", "explanation": "III alt miktar sınırını sağlar ve eksik alanı sıfırdır. II ve IV miktarı sağlasa da eksikleri vardır; I alt sınırın altındadır."}, {"id": "8-2-lgs-14", "prompt": "Ortak Emek Panosu duyurusunda “Yalnız onaylı anma panosu örnekleri listede gösterilir.” yazıyor. Bu kurala göre hangi yorum doğrudur?", "choices": ["Listede gösterilmeyen bir örnek yine de onaylı olabilir.", "Onaylı olan her örnek mutlaka gösterilmiştir.", "Listede görünen her örnek onaysızdır.", "Onaysız örnekler mutlaka listede yer alır."], "answer": "Listede gösterilmeyen bir örnek yine de onaylı olabilir.", "explanation": "Kural gösterilenlerin onaylı olmasını ister; onaylananların tamamının gösterileceğini söylemez."}, {"id": "8-2-lgs-15", "prompt": "Ortak Emek Panosu için araştırma yapan öğrenci aynı anma panosu bilgisini üç ayrı sayfada bulur. İkinci ve üçüncü sayfanın birinci sayfayı aynen aktardığını görür. Bu üç sayfanın aynı bilgiyi vermesi nasıl değerlendirilmelidir?", "choices": ["Bilgi üç kez yazıldığı için kesin kanıtlanmıştır.", "Kaynağı incelemeye artık gerek yoktur.", "Üç sayfa mutlaka üç ayrı deney raporudur.", "Birbirinden bağımsız üç doğrulama sayılmaz."], "answer": "Birbirinden bağımsız üç doğrulama sayılmaz.", "explanation": "Kopyalanan bilgi ayrı bağımsız dayanak oluşturmaz; ilk kaynağın ve ek kanıtların niteliği incelenmelidir."}, {"id": "8-2-lgs-16", "prompt": "Ortak Emek Panosu kuralı: “Anma panosu dosyası, kaynak bilgisi tamamlanmışsa ve öğretmen uygun bulmuşsa cuma günü paylaşılacaktır.” Bu cümlenin anlamını koruyan özet hangisidir?", "choices": ["Öğretmen uygun bulursa kaynak bilgisine gerek kalmayacak.", "Kaynak tamamlanınca gün gözetmeden otomatik paylaşılacak.", "Paylaşım cuma günü, iki koşul da sağlanırsa yapılacak.", "Dosya cuma günü her durumda paylaşılacak."], "answer": "Paylaşım cuma günü, iki koşul da sağlanırsa yapılacak.", "explanation": "Doğru özet zaman bilgisini ve iki koşulun birlikte gerekli oluşunu korur."}, {"id": "8-2-lgs-17", "prompt": "Ortak Emek Panosu raporunda “Bazı anma panosu örnekleri henüz incelenmedi.” deniyor. Bu cümleden hangi sonuç çıkarılabilir?", "choices": ["İncelenen bütün örnekler başarısızdır.", "En az bir örneğin incelemesi tamamlanmamıştır.", "Bütün örnekler kesinlikle incelenmiştir.", "Hiçbir örnek gelecekte incelenmeyecektir."], "answer": "En az bir örneğin incelemesi tamamlanmamıştır.", "explanation": "Bazı sözü en az bir durumu bildirir; henüz ise gelecekte inceleme ihtimalini kapatmaz."}, {"id": "8-2-lgs-18", "prompt": "Ortak Emek Panosu dosyasında dört grubun tamamladığı anma panosu sayıları A:8, B:14, C:11, D:5 olarak verilmiştir. En yüksekten en düşüğe doğru sıralamayı gösteren grafik etiketleri hangisidir?", "choices": ["B – C – A – D", "B – A – C – D", "D – A – C – B", "C – B – A – D"], "answer": "B – C – A – D", "explanation": "B en yüksek, ardından C ve A, son olarak D gelir. Sıralama tabloda verilen büyüklüklerden okunur."}, {"id": "8-2-lgs-19", "prompt": "Ortak Emek Panosu üzerine bir yazıda “Anma panosu, hazırlayanla okuyan arasında bir köprü kurdu; daha önce görünmeyen düşünceler konuşulabilir oldu.” deniyor. Köprü kurmak sözü burada anlatıma ne katar?", "choices": ["Gerçek bir inşaatın tamamlandığını kanıtlar.", "Bir yolun uzunluğunu sayıyla gösterir.", "İki kişinin her konuda aynı düşündüğünü kesinleştirir.", "İletişim ve bağlantı sağlandığını mecazla anlatır."], "answer": "İletişim ve bağlantı sağlandığını mecazla anlatır.", "explanation": "Köprü somut geçiş yapısından hareketle düşünceler arasında iletişim kurulmasını anlatır; tam uzlaşma iddiası içermez."}, {"id": "8-2-lgs-20", "prompt": "Ortak Emek Panosu için basılı duyuru “Salı, saat 14.00, okul salonu; ön kayıt gerekli.” diyor. Sesli duyuru ise “Salı okul salonunda buluşuyoruz; ön kayıt yaptırmayı unutmayın.” biçimindedir. İki duyuru karşılaştırıldığında sesli duyuruda hangi bilginin eksik olduğu görülür?", "choices": ["Gün", "Yer", "Ön kayıt koşulu", "Başlama saati"], "answer": "Başlama saati", "explanation": "Gün, yer ve kayıt iki duyuruda da vardır; 14.00 bilgisi yalnız basılı duyuruda bulunur."}]}'::jsonb),
(8,'8-3-soz-1',22,'{"id": "8-3-soz-1", "title": "Söz varlığı · 1", "theme": "Erdemler", "kind": "words", "body": [{"kelime": "iletişim", "anlam": "Duygu ve düşüncelerin karşılıklı aktarılması", "ornek": "İletişim için ortak bir zaman belirledik.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "anlaşmazlık", "anlam": "Bir konuda farklı düşünüp uyuşamama durumu", "ornek": "Anlaşmazlığı konuşarak çözmeye çalıştık.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "uzlaşmak", "anlam": "Farklı istekleri ortak bir çözümde buluşturmak", "ornek": "İki grup çalışma saatinde uzlaştı.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "dinleyici", "anlam": "Bir konuşmayı veya sesi dinleyen kişi", "ornek": "Dinleyici soru sormak için sırasını bekledi.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "konuşmacı", "anlam": "Bir topluluğa konuşan kişi", "ornek": "Konuşmacı son cümlesini yeniden açıkladı.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "sıra", "anlam": "Bir işte veya dizilişte izlenecek yer", "ornek": "Söz sırası gelince önerimi sundum.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "üslup", "anlam": "Bir anlatımın kendine özgü söyleyiş biçimi", "ornek": "İletinin üslubu daha nazik hâle getirildi.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "açıklık", "anlam": "Bir anlatımın kolay anlaşılır olma özelliği", "ornek": "Duyurunun açıklığını kontrol ettik.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "nezaket", "anlam": "Başkalarını gözeten incelikli davranış", "ornek": "Nezaket görüş ayrılığında da sürmelidir.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "eleştiri", "anlam": "Bir işin güçlü ve geliştirilebilir yanlarını gerekçeleriyle inceleme", "ornek": "Eleştiri kişiliğe değil çalışmaya yönelikti.", "tip": "kelime", "cikti": "T.8.3.5"}], "questions": [{"id": "8-3-kelime-0", "prompt": "“iletişim” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Duygu ve düşüncelerin karşılıklı aktarılması", "Bir konuda farklı düşünüp uyuşamama durumu