(8,'8-6-soz-3',54,'{"id": "8-6-soz-3", "title": "Söz varlığı · 3", "theme": "Duygular", "kind": "words", "body": [{"kelime": "paylaşmak", "anlam": "Bir düşünceyi veya nesneyi başkasıyla bölüşmek", "ornek": "Düşüncemi grupla paylaşmak istedim.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "anlamak", "anlam": "Bir sözün veya durumun anlamını kavramak", "ornek": "Arkadaşımın duygusunu anlamak için dinledim.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "dinlemek", "anlam": "Söylenenlere dikkatini vererek kulak vermek", "ornek": "Anlatılanları dinlemek konuşmamı kolaylaştırdı.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "farkındalık", "anlam": "Kendi durumunu veya çevrede olanları ayırt etme", "ornek": "Duygu günlüğü farkındalık kazanmama yardım etti.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "dayanmak", "anlam": "Bir güçlük karşısında varlığını veya çabasını sürdürmek", "ornek": "Uzun bekleyişe arkadaş desteğiyle dayandım.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "kabullenmek", "anlam": "Bir gerçeği olduğu gibi tanıyıp kabul etmek", "ornek": "Hata yaptığımı kabullenmek kolay değildi.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "çözüm", "anlam": "Bir güçlüğü gidermeye yarayan yol", "ornek": "Birlikte yeni bir çözüm düşündük.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "tepki", "anlam": "Bir olay karşısında gösterilen davranış", "ornek": "Tepkimi düşünerek vermeye çalıştım.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "ifade", "anlam": "Düşünceyi veya duyguyu anlatma biçimi", "ornek": "Yüzündeki ifade sevinçliydi.", "tip": "kelime", "cikti": "T.8.3.5"}, {"kelime": "öz güven", "anlam": "Kişinin kendi gücüne ve yapabileceklerine inanması", "ornek": "Hazırlanmak öz güvenimi artırdı.", "tip": "kelime", "cikti": "T.8.3.5"}], "questions": [{"id": "8-6-kelime-20", "prompt": "“paylaşmak” sözcüğünün bu temadaki anlamı nedir?", "choices": ["Bir düşünceyi veya nesneyi başkasıyla bölüşmek", "Bir olayın kişide oluşturduğu sevinç